SELECT 'moj-all-verified-judgments-review-002-chunk-070' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6be87d49-9f4e-5391-9aee-ec55d6a7409a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تقرير الطب النفسي -صك والية -صرف النظر عن طلب املدعي العام .","document_number":"3432274","case_number":"33385832","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/06","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تقرير الطب النفسي -صك والية -صرف النظر عن طلب املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3432274 :‬تاريخه ‪1434/02/06 :‬هـ‬\n                        ‫رقم الدعوى ‪33385832 :‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34190060:‬تاريخه‪1434/4/16 :‬هـ‬\n\n\n       ‫مخــدرات‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تقريــر الطــب النفســي ‪ -‬صــك‬\n                           ‫واليــة ‪ -‬صــرف النظــر عــن طلــب املدعــي العــام ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم « رفــع القلــم عــن ثالثــة ‪ ،‬عــن النائــم‬\n       ‫حتــى يســتيقظ ‪ ،‬وعــن الصغيــر حتــى يكبــر ‪ ،‬وعــن املجنــون حتى يفيق»‬\n                  ‫رواه اإلمــام أحمــد وأبــو داود والترمــذي وقــال حديــث حســن ‪.‬‬\n       ‫‪ -2‬منــاط التكليــف يف الشــريعة ‪ :‬البلــوغ والعقــل ‪ ،‬ومــا هيــة العقــل‬\n       ‫هــو مــا يــدرك بــه اإلنســان األشــياء علــى حقيقتهــا ‪ .‬انظــر مجمــوع‬\n                                                ‫الفتــاوى البــن تيميــة (‪. )345/10‬‬\n       ‫العقــاء علــى أن شــرط‬ ‫‪ -3‬قــال اآلمــدي رحمــه اهلل يف اإلحــكام ‪ ( :‬اتفــق ُ‬\n       ‫ا فاهمـ ًا للتكليــف ألن التكليــف خطــاب ‪ ،‬وخطاب‬       ‫املكلــف أن يكــون عاقـ ً‬\n                                                  ‫مــن ال عقــل لــه وال فهــم محــال ) ‪.‬‬\n       ‫‪ -4‬قــال ابــن قدامــة يف املغنــى (‪ ( : )109/5‬فأمــا الطفــل املجنــون‬\n       ‫واملبرســم والنائــم واملغمــى عليــه فــا يصــح إقرارهــم ال نعلــم يف هــذا‬\n                                                                             ‫خالف ـ ًا ) ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f‫ادعــى املدعــى العــام ضــد املدعــى عليــه ببيــع عــدد خمــس حبــات مــن‬\n‫احلبــوب املنبهــة احملظــورة بقصــد االجتــار حيــث توفــرت معلومــات لــدى‬\n‫مكافحــة املخــدرات مــن أحــد مصادرهــا الســرية عــن قيــام املدعى عليه‬\n‫بترويــج احلبــوب احملظــورة ومت تزويــد املصــدر باملبلــغ املرقــم ويف املــكان‬\n‫احملــدد حضــر املدعــى عليــه بســيارته ومتــت عمليــة االســتالم والتســليم‬\n‫أمــام أنظــار الفــرد املرافــق ومت القبــض علــى املدعــى عليــه وطلــب املدعي‬\n‫العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n‫وإعــادة املبلــغ احلكومــي املرقــم ومصــادرة الســيارة واجلــوال‪ .‬ظهــرت‬\n‫علــى املدعــى عليــه آثــار تخلــف عقلــي وحضــر وليــه وأبــرز صــك واليــة‬\n‫علــى املدعــى عليــه وصــدر تقريريــن مــن مستشــفى الصحــة النفســية‬\n‫يفيــدان بتخلــف املدعــى عليــه عقلي ـ ًا ( تخلــف متوســط) ‪ ،‬بنــاء علــى‬\n‫ماتقــدم حكمــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي العــام‬\n                                ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم وتاريــخ ‪1433/06/08‬ه ـ املقيــدة باحملكمة برقم‬\n‫وتاريــخ ‪ 1433/06/08‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/05‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪ /‬وادعــى‬\n‫علــى احلاضــر معــه ‪ /‬ســعودي اجلنســية مبوجــب بالســجل املدنــي رقــم ()‬\n\n                                                                                     ‫‪158‬‬\n\f      ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود‬\n      ‫الشــمالية أدعــي علــى املذكــور أعــاه فإنــه بتاريــخ ‪1433 /4/17‬‬\n      ‫وبنــاء علــى املعلومــات املتوفــرة لــدى مكافحــة املخــدرات مــن أحــد‬\n      ‫املصــادر الســرية عــن قيــام املدعــى عليــه ‪ /‬بترويــج احلبــوب احملظــورة‬\n      ‫واســتعداده اإلطاحــة بــه فتــم التنســيق مــع املصــدر واالتصــال باملــروج‬\n      ‫ـاء وكانــت‬  ‫علــى جوالــه رقــم (‪ ).....‬يف متــام الســاعة الثامنــة والربــع مسـ ً‬\n      ‫املكاملــة علــى مســمع مــن الفــرد املرافــق للمصــدر حيــث مت االتفــاق علــى‬\n      ‫حتديــد موقــع ملقابلــة املــروج فيــه الســتالم األغــراض فتــم االنتقــال إلــى‬\n      ‫املوقــع املتفــق عليــه بالقــرب مــن مدرســة بحــي ‪ ....‬بعــد تفتيــش املصــدر‬\n      ‫وســيارته وإعطــاءه املبلــغ احلكومــي املرقــم وقــدره مائتــي ريــال وعنــد‬\n      ‫الوصــول إلــى املوقــع يف متــام الســاعة الثامنــة وخمــس وعشــرون دقيقــة‬\n      ‫ـاء واالنتظــار وبعــد حوالــي دقيقــة حضــر املدعــى عليــه‬            ‫(‪ )8.25‬مسـ ً‬\n      ‫علــى ســيارته مــن نــوع ‪ ....‬حتمــل لوحــة ســعودية رقــم (‪ )....‬حيــث قــام‬\n      ‫بالســام علــى املصــدر وطلــب املصــدر منــه حبــوب مببلــغ مائتــي ريــال‬\n      ‫فوافــق وقــام بإعطــاء املصــدر عــدد (‪ )5‬خمــس حبــات يشــتبه أن تكــون‬\n      ‫مــن احلبــوب املنبهــة احملظــورة وقــام بتســليمه املبلــغ احلكومــي املرقــم‬\n      ‫ثــم قــام املصــدر بالرجــوع وتســليم احلبــوب إلــى العنصــر املرافــق لــه‬\n      ‫وكانــت عمليــة االســتالم والتســليم أمــام أنظــار الفــرد املرافــق ويف متــام‬\n      ‫ـاء مــن نفــس اليــوم مت القبــض علــى املدعــى عليــه‬    ‫الســاعة التاســعة مسـ ً‬\n      ‫وبتفتيشــه عثــر معــه علــى اجلــوال املســتخدم يف اجلرميــة ويحمــل الرقــم‬\n      ‫التسلســلي (‪ ).....‬وبســماع أقوالــه اقــر ببيــع احلبــوب املنبهــة احملظــورة‬\n      ‫وإيصالهــا ورفــض التبصيــم علــى أقوالــه وباســتجوابه أقــر بتلقيــه‬\n      ‫اتصــال مــن شــخص يطلــب منــه حبــوب ثــم ذهــب إلــى املوقــع املتفــق عليــه‬\n\n\n‫‪159‬‬\n\f‫للقــاء املتصــل بالقــرب مــن مدرســة ‪ ....‬والتفاهــم معــه لتكــرار اتصالــه‬\n‫عليــه وقابلــه وســلم عليــه ومشــى رافض ـ ًا أخــذ أو بيــع احلبــوب كمــا‬\n‫اقــر بعائديــة اجلــوال رقــم (‪ ).....‬لــه وقــد اثبــت التقريــر الكيميائــي‬\n‫الشــرعي الصــادر مــن مركــز الســموم بصحــة تبــوك برقــم (‪/1138‬م‬\n‫س ت ) لعــام ‪1433‬ه ـ ايجابيــة العينــة املرســلة ملــادة االمفيتامــن املنبهــة‬\n‫احملظــورة وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة املنــوه عنهــا يف‬\n‫اجلــدول الثانــي فئــة (ب) بتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n‫رقــم ‪ 89400/19‬وتاريــخ ‪1426/10/25‬ه ـ كمــا صــدر التقريــر الطبــي‬\n‫النفســي اجلنائــي رقــم (‪ )35/347‬وتاريــخ ‪1433/5/18‬ه ـ الصــادر مــن‬\n‫مستشــفى الصحــة النفســية بالطائــف املتضمــن (تخفيــف املســؤولية‬\n‫اجلنائيــة يف قضيتــه احلاليــة لوجــود التخلــف العقلــي ومــا يصاحبــه مــن‬\n‫ســوء احلكــم علــى األمــور وضعــف تقديــر عواقــب األمــور) وقــد انتهــى‬\n‫التحقيــق إلــى اتهــام‪ ......‬ببيــع عــدد خمــس حبــات مــن احلبــوب املنبهــة‬\n‫احملظــورة بقصــد االجتــار وبالبحــث عــن ســوابقه تبــن خلــو ســجله‬\n‫منهــا وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم شــرعا ومجــرم‬\n‫نظامــا بنــص الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه‬\n‫باالتــي‪ -1 :‬الســجن واجللــد والغرامــة وفقــا للمــادة (‪ )38‬الفقــرة (‪ )1‬مــن‬\n‫نظــام مكافحــة املخــدرات مــع مراعــاة مــا ورد بالتقريــر الطبــي النفســي‬\n‫اجلنائــي املرفــق لفــة رقــم (‪ -2 )61‬منــع مــن الســفر خــارج اململكــة وفقــا‬\n‫للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام نفســه ‪ -3‬إلــزام املتهــم بدفــع‬\n‫املبلــغ احلكومــي املرقــم وقــدرة (‪ )200‬مائتــي ريــال وفقـ ًا لبرقيــة صاحب‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n      ‫رقــم ‪ 65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ ‪ -4‬مصــادرة‬\n      ‫الســيارة مــن نــوع ‪ ....‬موديــل (‪ )1993‬حتمــل اللوحــة رقــم (‪ ).....‬واجلــوال‬\n      ‫املســتخدم يف عمليــة الترويــج مــن نــوع ‪ ....‬ابيــض يحمــل الرقــم التسلســلي‬\n      ‫() وعــدم صــرف شــريحة اجلــوال رقــم (‪ )..............‬للمتهــم املذكــور وفقــا‬\n      ‫للمــادة (‪ )53‬الفقــرة األولــى مــن النظــام نفســه هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه عــن الدعــوى فلــم يتجــاوب وظهــر لــي مــن حالــه بــأن‬\n      ‫فيــه تخلــف عقلــي كمــا أنــه يجــاوب بإجابــات غيــر مطابقــة للســؤال‬\n      ‫وبتكــرار ســؤالي لــه عــن الدعــوى بكــى بــكاء شــديد وقــال ال لعبــوا‬\n      ‫علــي وأنــا تعبــت يف التوقيــف أوريــد اخلــروج وبــكالم غيــر مفهــوم كمــا‬\n      ‫ظهــر لــي بــأن املدعــى عليــه بحاجــة للمســاعدة يف بعــض أمــوره لكونــه‬\n      ‫قصيــر القامــة جــد ًا كمــا حضــر يف نفــس اجللســة شــقيق املدعــى عليــه‬\n      ‫وهــو ســعودي بالســجل املدنــي رقــم حيــث أفــاد بــأن شــقيقه ال يحســن‬\n      ‫التصــرف يف بعــض أمــوره ولديــه تخلــف عقلــي وأنــا الولــي الشــرعي عنــه‬\n      ‫وأقــوم برعايتــه وإدارة شــؤون حياتــه نظــر ًا لكونــه يعانــي مــن تخلــف‬\n      ‫عقلــي متوســط وغيــر قــادر علــى حتمــل املســؤولية وإدارة شــؤون حياتــه‬\n      ‫وذلــك حســب صــك الواليــة الصــادر مــن هــذه احملكمــة برقــم ‪3/41‬‬\n      ‫يف ‪1425/4/20‬ه ـ أفــاد ثــم جــرى منــي اإلطــاع علــى التقريــر الطبــي‬\n      ‫النفســي اجلنائــي الصــادر مــن مستشــفى الصحــة النفســية بالطائــف‬\n      ‫واملــدون علــى اللفــة رقــم ‪ 23‬واملتضمــن فيــه بأنــه مــن خــال الفحــص‬\n      ‫العقلــي كان هادئ ـ ًا وال ينظــر بعــن الفاحــص وكان قصيــر القامــة‬\n      ‫ويعانــي مــن ضعــف واضــح بالســمع والنطــق وكالم غيــر مفهــوم يف‬\n      ‫بعــض األحيــان ومزاجــه متبلــد وغيــر متفاعــل ثــم بعــد ذلــك قــررت اللجنة‬\n\n\n‫‪161‬‬\n\f‫بــأن املذكــور يعــود إلــى مرجعــه بــدون عــاج عقلــي ونظــر ًا ملــا يعانيــة‬\n‫املذكــور مــن تخلــف عقلــي ومــا يصاحبــه مــن ســوء يف احلكــم علــى‬\n‫األمــور وتقديــر عواقــب األفعــال كونــه مــن الســهولة ميكــن اســتغالله‬\n‫والتغريــر بــه مــن قبــل اآلخريــن وتــرى اللجنــة بــأن بعــض مــن املســؤولية‬\n‫اجلنائيــة ويأخــذ التعهــد الــازم علــى ذويــه باحملافظــة عليــه حتــى ال‬\n‫يتكــرر مــا بــدر منــه يف قضيتــه اجلاليــة وهــو بتوقيــع الدكتــور ورئيــس‬\n‫اللجنــة الدكتــور كمــا مت اإلطــاع علــى تقريــر الطبــي النفســي اجلنائــي‬\n‫الصــادر مــن مستشــفى الصحــة النفســية بالطائــف برقــم ‪ 35/347‬يف‬\n‫‪1433/5/18‬ه ـ واملــدون علــى اللفــة رقــم ‪ 61‬واملتضمــن فيــه بــأن اللجنــة‬\n‫الطبيــة تقــرر بتخفيــف املســؤولية اجلنائيــة يف قضيتــه احلاليــة لوجــود‬\n‫التخلــف العقلــي ومــا يصاحبــه مــن ســوء احلكــم علــى األمــور وضعــف‬\n‫تقديــر عواقــب األمــور وتشــدد اللجنــة علــى أخــذ التعهــدات الالزمــة‬\n‫علــى وليــه الشــرعي باحملافظــة عليــه حتــى ال يتكــرر منــه مثــل تلــك‬\n‫األفعــال مــرة أخــرى وهــو بتوقيــع د‪ /‬و د‪ /‬ورئيــس اللجنــة د‪ /‬وأيض ـ ًا مت‬\n‫اإلطــاع علــى صــك الواليــة املذكــور أعــاه واملــدون علــى اللفــة رقــم‬\n‫ـاء‬\n‫‪ 11‬واملتضمــن فيــه وفــق مــا ذكــره شــقيق املدعــى عليــه يف إفادتــه فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى ومــا قــرره ولــي املدعــى عليــه الشــرعي وبعــد‬\n‫اإلطــاع علــى التقريريــن الطبيــن النفســيني املذكــوران أعــاه ومبــا أن‬\n‫املدعــى عليــه ال يحســن التصــرف يف أمــوره ولديــه تخلــف عقلــي كمــا‬\n‫ورد يف التقاريــر الطبيــة ومبــا أنــه أيضـ ًا غيــر قــادر علــى حتمــل املســؤولية‬\n‫وإدارة شــؤون حياتــه ونظــر ًا إلقامــة شــقيقه ولي ـ ًا عليــه يقــوم برعايتــه‬\n‫وإدارة شــؤونه وبعــد اإلطــاع علــى صــك الواليــة املذكــور أعــاه ولقولــه‬\n‫صلــى اهلل عليــه وســلم كمــا يف احلديــث [ رفــع القلــم عــن ثالثــة عــن‬\n\n\n                                                                                        ‫‪162‬‬\n\f      ‫النائــم حتــى يســتيقظ وعــن الصغيــر حتــى يكبــر وعــن املجنــون حتــى‬\n      ‫يفيــق ] رواه األمــام أحمــد وأبــو داود والترمــذي وقــال حديــث حســن ومبــا‬\n      ‫أن منــاط تكليــف اإلنســان يف الشــريعة اثنــان وهمــا البلــوغ والعقــل ومبــا‬\n      ‫أن مــا هبــة العقــل هــو مــا يــدرك بــه اإلنســان األشــياء علــى حقيقتهــا [‬\n      ‫ينظــر مجمــوع فتــاوي ابــن تيميــة ‪ ]345/10‬وقــال األمــدي رحمــة اهلل يف‬\n      ‫ا‬\n      ‫اإلحــكام [ اتفــق العقــاء علــى أن شــرط املكلــف أن يكــون عاق ـ ً‬\n      ‫فاهم ـ ًا للتكليــف ألن التكليــف خطــاب مــا وخطــاب مــن ال عقــل لــه‬\n      ‫وال فهــم محــال ] ومبــا أن صحــة التكليــف مبنيــة علــى العقــل الــذي‬\n      ‫هــو آلــة القــدرة ونظــر ًا ألن فاقــد العقــل معــدوم األهليــة ألنــه ال يعــرف‬\n      ‫مصلحتــه مــن ضدهــا ومبــا أن املدعــى عليــه ناقــص العقــل وال يفــرق‬\n      ‫بــن احلــال وال احلــرام وال يعــي خطــورة املخــدرات وضررهــا كمــا‬\n      ‫أنــه غيــر مــدرك لعواقــب األمــور واألفعــال وتقديرهــا ممــا يســهل علــى‬\n      ‫ضعــاف النفــوس مــن املروجــن اســتغالله والتغريــر بــه وقــال ابــن قدامــة‬\n      ‫يف املغنــي ‪ [ 109/5‬فأمــا الطفــل واملجنــون واملبرســم والنائــم واملغمــى‬\n      ‫عليــه فــا يصــح إقرارهــم ال نعلــم يف هــذا خالفـ ًا ] لــذا وجلميــع مــا تقــدم‬\n      ‫فلــم يثبــت لــدي إدانــة املدعــى عليــه ‪ ....‬ببيــع خمــس حبــات مــن احلبــوب‬\n      ‫احملظــورة بقصــد االجتــار ورددت طلبــات املدعــي العــام واملتعلقــة‬\n      ‫بتطبيــق املــواد ‪38‬و ‪56‬و‪ 53‬مــن نظــام مكافحــة املخــدرات بحــق املدعــى‬\n      ‫عليــه كمــال مضحــي لعــدم أهليتــه شــرع ًا وأيضـ ًا رددت دعــوى املدعــي‬\n      ‫العــام بخصــوص املطالبــة بإلــزام املدعــى عليــه بإعــادة املبلــغ احلكومــي‬\n      ‫وكذلــك مصــادرة ســيارته وجوالــه وشــريحته واملذكــورة جميعـ ًا أعــاه‬\n      ‫لعــدم أهليتــه املعتبــرة شــرع ًا و أوصيــة بأخــذ التعهــد الــازم علــى وليــه‬\n      ‫الشــرعي باملتابعــة الشــديدة علــى املدعــى عليــه واحملافظــة عليــه حتــى ال‬\n\n\n‫‪163‬‬\n\f‫يســتغل مــن قبــل اآلخريــن بهــذا حكمــت وبعرضــه علــى املدعــي العــام‬\n‫قــرر املعارضــة علــى احلكــم بالئحــة اعتراضيــة وطلب التمييــز ويف نفس‬\n‫اليــوم جــرى تســليمه صــورة مــن احلكــم لالعتــراض عليــه و أفهــم بــأن‬\n‫مــدة االعتــراض ثالثــون يومـ ًا تبــدأ مــن هــذا اليــوم وإذا مضــت املــدة ولــم‬\n‫يعتــرض ســقط حقــه يف التمييــز وترفــع املعاملــة حملكمــة االســتئناف‬\n‫بــدون الئحــة خــال خمســة وأربعــن يوم ـ ًا مــن تاريــخ هــذا اليــوم ولــه‬\n‫املراجعــة خــال املهلــة واملــدة النظاميــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل على‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ‬\n‫ـاء علــى ورود الالئحــة االعتراضيــة‬       ‫افتتحــت اجللســة الســاعة ‪ 10.00‬بنـ ً‬\n‫علــى هــذا احلكــم واملقدمــة مــن املدعي العام واملقيــدة برقم ‪34617358‬‬\n‫يف ‪1434/03/10‬ه ـ وبإطالعــي عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا‬\n‫حكمــت بــه أو يدعــو للعــدول عنــه وقــررت رفــع املعاملــة مــع القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة حملكمــة االســتئناف باجلــوف‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪ 1434/03/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ....‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــه مبحكمــة االســتئناف مبنطقــة اجلــوف‬\n‫علــى املعاملــة الــواردة مــن احملكمــة العامــه بعرعــر برقــم وتاريــخ‬\n‫‪1434/3/24‬ه ـ املرفــق بهــا القــرار الصادر من فضيلة الشــيخ‪ /‬املســجل‬\n‫برقــم يف‪1434/2/6‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ /‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــرر املصادقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى ألــه‬\n                                                                ‫وصحبــه وســلم‪..‬‬\n                                                                                       ‫‪164‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":157,"source_page_end":164,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"561948258e1eb5182b83ac502d75f0743ced4dd9b727f0ffeb99182960f844f2","normalized_text_hash":"ebf6076ae57c80f80dd41d23003c11d7ad3eb2bfd344c0b8946ad8ecfc908eef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p157-3432274"},{"id":"94e32d6d-f989-5add-9170-550768fced4d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر- الوساطة يف ترويج احلشيش املخدر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد والغرامة واملنع من السفر -تعزير باملصادرة -إقامة حد املسكر.","document_number":"33357665","case_number":"33422213","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/27","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر- الوساطة يف ترويج احلشيش املخدر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد والغرامة واملنع من السفر -تعزير باملصادرة -إقامة حد املسكر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33357665:‬تاريخه ‪1434/7/27:‬هـ‬\n                       ‫رقم الدعوى ‪33422213:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪/34324474‬ج‪/1‬أ تاريخه‪1434/9/22 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر‪ -‬تعاطــي احلشــيش املخــدر‪-‬‬\n      ‫الوســاطة يف ترويــج احلشــيش املخــدر‪ -‬إقــرار ‪ -‬ظــروف مخففــة‬\n      ‫للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‪ -‬تعزيــر‬\n                                                    ‫باملصــادرة‪ -‬إقامــة حــد املســكر‪.‬‬\n\n\n\n\n                       ‫‪ -1‬قوله صلى اهلل عليه وسلم ( كل مسكر حرام ) ‪.‬‬\n                ‫‪ -2‬قوله صلى اهلل عليه وسلم ( من شرب اخلمر فاجلدوه )‪.‬‬\n         ‫‪ -3‬املادة ‪ 56-53-38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليهمــا بتوجيــه االتهــام لــأول بترويــج‬\n      ‫احلشــيش املخــدر وتعاطيــه وتوســط الثانــي يف ترويــج وتعاطــي احلشــيش‬\n      ‫املخــدر‪ ،‬وطلــب املدعــى العــام إثبــات مــا أســند إليهمــا واحلكــم عليهمــا‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة جهــازي جــوال‬\n      ‫للمدعــى عليــه األول الســتخدامها بعمليــة الترويــج وإلغــاء الشــريحتني‬\n      ‫وإعــادة املبلــغ املرقــم ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليهمــا‬\n      ‫بعــد ورود بــاغ عــن املدعــى عليــه الثانــي يقــوم بالتوســط يف ترويــج‬\n      ‫احلشــيش املخــدر ومت التنســيق معــه عــن طريــق أحــد املصــادر لشــراء‬\n\n‫‪165‬‬\n\f‫احلشــيش وتســلم املدعــى عليــه الثانــي احلشــيش مــن املدعــى عليــه‬\n‫األول‪ ،‬اعتــراف املدعــى عليهمــا وثبــوت إدانتهمــا ‪ ،‬بنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بإقامــة حــد املســكر علــى املدعــى عليهمــا وتعزيــر‬\n‫املدعــى عليهمــا بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة‬\n‫وصــدق احلكــم مــن محكمة‬        ‫اجلــوال والشــريحة املســتخدمان يف اجلرميــة ُ‬\n                                                                   ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .........‬القاضــي باحملكمــة العامــة باجلبيــل وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا برقــم (‪ )33422213‬وتاريــخ ‪1433/6/23‬ه ـ واملقيــدة باحملكمــة‬\n‫برقــم (‪ )331183981‬وتاريــخ ‪1433/6/23‬ه ـ ويف يــوم االحــد املوافــق‬\n‫‪433/6/29‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر والنصــف وفيهــا‬\n‫حضــر املدعــي العــام بدائــرة التحقيــق واإلدعــاء العــام باجلبيــل ‪......... /‬‬\n‫واملدعــى عليــه االول ‪ .............‬ســعودي بالســجل املدنــي رقــم (‪).......‬‬\n‫واملدعــى عليــه الثانــي ‪ .........../‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬وادعــى املدعــي العــام قائــا يف دعــواه بصفتــي مدعيــا عاما‬\n‫بدائــرة التحقيــق واإلدعــاء العــام مبحافظــة اجلبيــل أدعــي علــى كل مــن‬\n                                                                      ‫املواطنــن ‪-:‬‬\n‫‪ ........ -1‬مبوجــب الســجل املدنــي رقــم (‪ ).....‬البالــغ مــن العمــر(‪ )18‬عامـ ًا‬\n‫موقــوف لــدى ســجن محافظــة اجلبيــل مبوجــب مذكــرة التوقيــف رقــم‬\n                            ‫(‪ 1252/4/3/15‬س ب) وتاريــخ ‪1433/5/25‬هــ‪.‬‬\n‫‪ ............ -2‬مبوجــب الســجل املدنــي رقــم (‪ )........‬البالــغ مــن العمــر(‪)19‬‬\n\n                                                                                       ‫‪166‬‬\n\f      ‫عامـ ًا موقــوف لــدى ســجن محافظــة اجلبيــل مبوجــب مذكــرة التوقيــف‬\n                          ‫رقــم (‪ 1253/4/3/15‬س ب) وتاريــخ ‪1433/5/25‬هــ‪.‬‬\n      ‫حيــث أنــه بتاريــخ ‪1433/5/22‬ه ـ وردت معلومــات ملكافحــة املخــدرات‬\n      ‫مبحافظــة اجلبيــل مــن أحــد مصادرهــا الســرية عــن قيــام املدعــى عليــه‬\n      ‫الثانــي (‪ )....‬بالتوســط يف ترويــج احلشــيش املخــدر وقــد أبــدى املصــدر‬\n      ‫اســتعداده لإلطاحــة بــه باجلــرم املشــهود ‪ ،‬عليــه وعنــد الســاعة (‪)8:00‬‬\n      ‫ـاء بالتاريــخ أعــاه مت متكينــه مــن االتصــال بالوســيط علــى‬  ‫الثامنــة مسـ ً‬\n      ‫جوالــه رقــم (‪ ).....‬حيــث قــال املصــدر ‪( :‬بغيــت حشــيش) فقــال الوســيط‬\n      ‫(مبائتــن وخمســن) فقــال املصــدر ‪( :‬إيــه إيــه مبائتــن وخمســن) علمـ ًا‬\n      ‫بــأن املكاملــة كانــت علــى مســمع مــن املــازم ‪ ...... /‬والعريــف ‪...... /‬‬\n      ‫عليــه مت تكليــف املــازم (‪ )....‬بتمثيــل دور املشــتري ويرافقــه املصــدر‬\n      ‫ـراء للذمــة ومت االنتقــال للقــاء الوســيط علــى‬\n                                                      ‫كمــا مت تفتيــش املصــدر إبـ ً‬\n      ‫طريــق األميــر ‪ ............‬باجلبيــل البلــد حيــث ركــب الوســيط مــع املصــدر‬\n      ‫وممثــل دور املشــتري بعدهــا حتركــوا إلــى خلــف مستشــفى اجلبيــل البلد‬\n      ‫العــام حيــث اتضــح فيمــا بعــد أنهــم ينتظــرون املــروج وأثنــاء ذلــك لوحــظ‬\n      ‫شــخص يحتــك بهــم واتضــح أنــه املــروج وركــب معهــم أيضـ ًا وحتركــوا‬\n      ‫جميعـ ًا إلــى أمــام محطــة الشــعلة بجــوار شــركة الكهربــاء حيــث نــزل‬\n      ‫املــروج ودخــل أحــد الشــوارع املظلمــة بعدهــا بســاعة نــزل الوســيط بعــد‬\n      ‫االتصــال الــذي ورده مــن املــروج وبعــد خمــس دقائــق عــاد الوســيط وقــام‬\n      ‫بتســليم ممثــل دور املشــتري قطعــة بنيــة اللــون بلــغ وزنهــا (‪ )4.6‬أربعــة‬\n      ‫جرامــات وســتة بالعشــرة مــن اجلــرام يشــتبه أن تكــون مــن احلشــيش‬\n      ‫املخــدر كمــا حضــر املــروج أيض ـ ًا وركــب هــو والوســيط بالســيارة‬\n      ‫بعدهــا مت القبــض عليهمــا حيــث اتضــح أن الوســيط هــو املدعــى عليــه‬\n\n\n‫‪167‬‬\n\f‫الثانــي ولــم يعثــر معــه علــى أيــة ممنوعــات وبضبــط املــروج اتضــح أنــه‬\n‫املدعــى عليــه األول ولــم يعثــر معــه علــى أيــة ممنوعــات ولــم يعثــر معــه‬\n‫علــى املبلــغ املرقــم وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم‬\n‫(‪ 2156‬ك ش) وتاريــخ ‪1433/6/7‬ه ـ ايجابيــة القطعــة املضبوطــة ملــادة‬\n‫احلشــيش املخــدر املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n                                                         ‫وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n‫باســتجواب املدعــى عليــه األول (‪ ).....‬أقــر بصحــة واقعــة القبــض عليــه‬\n‫مــن قبــل مكافحــة املخــدرات باجلبيــل بعــد قيامــه بترويــج قطعــة بلــغ‬\n‫وزنهــا (‪ )4.6‬أربعــة جرامــات وســتة بالعشــرة مــن اجلــرام مــن احلشــيش‬\n‫املخــدر وأنــه حصــل عليهــا مــن شــخص بــأم الســاهك ال يعرفــه مببلــغ‬\n‫(‪ )250‬مائتــن وخمســن ريــا ًال وقصــده مــن عمليــة الترويــج الكســب‬\n‫املــادي وأنــه يتعاطــى احلشــيش املخــدر منــذ ســتة أشــهر وصــادق علــى‬\n‫أقوالــه شــرع ًا وباســتجواب املدعــى عليــه الثانــي (‪ )....‬أقــر بصحــة واقعــة‬\n‫القبــض عليــه مــن قبــل مكافحــة مخــدرات اجلبيــل بعــد قيامــه بالتوســط‬\n‫يف ترويــج قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )4.6‬أربعــة جرامــات‬\n‫وســتة بالعشــرة مــن اجلــرام مــن احلشــيش املخــدر وأن قصــده مــن عمليــة‬\n‫التوســط هــو خدمــة زميلــه وأنــه يتعاطــى احلشــيش املخــدر منــذ خمــس‬\n‫ســنوات وصــادق علــى أقوالــه شــرع ًا وانتهــى التحقيــق إلــى توجيــه االتهام‬\n‫للمدعــى عليــه األول بترويــج قطعــة مــن مــادة احلشــيش املخــدر بلــغ وزنهــا‬\n‫(‪ )4.6‬أربعــة جرامــات وســتة بالعشــرة مــن اجلــرام وتعاطيــه للحشــيش‬\n‫املخــدر وتوســط املدعــى عليــه الثانــي يف ترويــج تلــك القطعــة وتعاطيــه‬\n                             ‫لــذات النــوع وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n\n\n                                                                                     ‫‪168‬‬\n\f      ‫‪ -1‬إقرارهمــا املصــدق شــرع ًا املنــوه عنــه واملــدون علــى الصفحتــن رقــم‬\n                                                 ‫(‪ )15 ، 13‬مــن دفتــر التحقيــق املرفــق‬\n      ‫‪ -2‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                                                         ‫(‪ )1‬مــن دفتــر التحقيــق املرفــق‬\n      ‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                                      ‫(‪)13‬‬\n      ‫وبالبحــث عمــا إذا كان لهمــا ســوابق جنائيــة لــم يعثــر لهمــا علــى‬\n                                                                           ‫ســوابق مســجلة‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات‬\n                                                                                    ‫مــا يلــي‬\n      ‫أو ًال ‪ :‬إثبــات مــا أســند إليهمــا وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪)3‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليهمــا مبــا‬\n                                                                                         ‫يلــي‬\n      ‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املنصــوص عليهــا بالفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )38‬مــن ذات النظــام املشــار إليــه مــع مراعــاة إعمــال‬\n                                             ‫املــادة رقــم (‪ )62‬مــن النظــام املشــار إليــه‬\n      ‫‪ -2‬منعهمــا مــن الســفر إلــى خــارج اململكــة وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n                                      ‫املــادة رقــم (‪ )56‬مــن ذات النظــام املشــار إليــه‬\n      ‫ثانيـ ًا ‪ :‬مصــادرة جهــاز جوالــي املدعــى عليهمــا األول مــن نــوع (‪ )....‬يحمــل‬\n      ‫الرقــم املصنعــي رقــم (‪ )............‬والثانــي مــن نــوع (‪ ).....‬يحمــل الرقــم‬\n      ‫املصنعــي رقــم (‪ )........................‬الســتخدامهما بعمليــة الترويــج وفق ـ ًا‬\n      ‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪169‬‬\n\f‫وإيــداع قيمتــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات وفق ـ ًا‬\n‫لقــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪1421/12/18‬ه ـ ‪ ،‬وإلغــاء‬\n‫الشــريحتني املتعلقــة بالرقمــن املســتخدمني يف اجلرميــة وعــدم صرفهــا‬\n‫للمدعــى عليهمــا مــرة أخــرى وفق ـ ًا لتعميــم صاحــب الســمو امللكــي‬\n‫ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)9798‬‬\n‫وتاريــخ ‪1428/2/10/9‬ه ـ ‪ ،‬وإعــادة املبلــغ املرقــم وقــدره (‪ )250‬مائتــن‬\n‫وخمســن ريــا ًال اســتناد ًا لتعميــم صاحــب الســمو امللكــي ولــي العهــد‬\n‫نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)15980/4/5/1‬‬\n‫وتاريــخ ‪1428/10/23-22‬ه ـ ‪ ،‬وإيداعــه يف حســاب اإلدارة العامــة‬\n‫ملكافحــة املخــدرات وفق ـ ًا للقــرار الســابق وبعــرض دعــوى املدعــي‬\n‫العــام علــى املدعــى عليــه األول ‪ ....‬أجــاب قائــا مــا ذكــره املدعــي‬\n‫العــام يف دعــواه صحيــح جملــة وتفصيــا وبعــرض دعــوى املدعــي العــام‬\n‫علــى املدعــى عليــه الثانــي ‪ ....‬أجــاب قائــا مــا ذكــره املدعــي العــام‬\n‫يف دعــواه صحيــح جملــة وتفصيــا ثــم جــرى ســؤال املدعــي العــام عــن‬\n‫الرقــم اال خــر املســتخدم يف عمليــة الترويــج وكــم هــو رقمــه فقــال‬\n‫أطلــب مهلــة ملراجعــة أوراق املعاملــة رفعــت اجللســة ويف يــوم الســبت‬\n‫املوافــق‪ 1433/07/26‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا‬\n‫حضــر املدعــي العــام ‪ .....‬واملدعــى عليهمــا ‪ .....‬ثــم جــرى ســؤال املدعــي‬\n‫العــام عــن الرقــم اآلخــر املســتخدم يف عمليــة الترويــج فقــال هــو الرقــم‬\n‫(‪ ).......‬كمــا جــرى ســؤاله عــن قصــد املدعــى عليــه األول مــن الترويــج‬\n‫فقــال بقصــد الكســب املــادي ثــم جــرى ســؤال املدعــى عليهمــا مــن الذي‬\n‫اســتلم املبلــغ احلكومــي الــذي قــدره (‪ )250‬مائتــان وخمســون ريــال فقال‬\n‫املدعــى عليــه األول أنــا مــن اســتلمت املبلــغ احلكومــي ثــم جــرى االطالع‬\n\n\n                                                                                   ‫‪170‬‬\n\f      ‫علــى أوراق املعاملــة فوجــد علــى لفــه رقــم (‪ )13‬التقريــر الكيمــاوي‬\n      ‫الشــرعي رقــم (‪ 2156‬ك ش ) وباالطــاع عليــه وجــد يتضمــن ايجابيــة‬\n      ‫العينــات املأخــوذة مــن املضبوطــات مــع املدعــى عليهمــا ملــادة احلشــيش‬\n      ‫املخــدر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى‬\n      ‫عليهمــا بدعــوى املدعــي العــام ولكــون مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫فعــل محــرم شــرعا ولقولــه صلــى اهلل عليــه وســلم (كل مســكر حــرام)‬\n      ‫وقولــه (مــن شــرب اخلمــر فاجلــدوه) رواهمــا أبــوداود وأحمــد وبنــاء علــى‬\n      ‫املــادة رقــم (‪ )38‬ورقــم (‪ )53‬ورقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة فقــد ثبــت لــدي إدانــة املدعــى عليــه األول بترويــج‬\n      ‫قطعــة مــن مــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )4.6‬أربعــة جرامــات‬\n      ‫وســتة بالعشــرة مــن اجلــرام بقصــد الكســب املــادي وتعاطيــه للحشــيش‬\n      ‫املخــدر وتوســط املدعــى عليــه الثانــي يف ترويــج تلــك القطعــة وتعاطيــه‬\n      ‫لــذات النــوع ولقلــة الكميــة املروجــة ولعــدم وجــود ســوابق علــى املدعــى‬\n      ‫عليهمــا ولصغــر ســنهما فقــد حكمــت علــى األول ‪ .....‬مبــا يلــي ‪ :‬أوال‬\n      ‫‪ :‬يجلــد (‪ )80‬ثمانــن جلــده حــد املســكر ثانيــا ‪ :‬يســجن ملــدة ثــاث‬\n      ‫ســنوات مــن تاريــخ إيقافــه ثالثــا‪ :‬يجلــد (‪ )300‬ثالثمائــة جلــدة مفرقــه‬\n      ‫علــى ســتة بــن كل دفعــة واألخــرى خمســة عشــر يومـ ًا رابعــا ‪ :‬مينــع مــن‬\n      ‫الســفر خــارج اململكــة ملــدة ثــاث ســنوات بعــد تنفيــذ عقوبــة الســجن‬\n      ‫خامســا ‪ :‬إعــادة املبلــغ احلكومــي وقــدره (‪ )250‬مائتــان وخمســون ريــا ًال‬\n      ‫ويــودع يف حســاب اإلدارة العامــة املكافحــة املخــدرات سادســا ‪ :‬إلغــاء‬\n      ‫رقــم الشــريحة (‪ )......‬وعــدم صرفــه لــه مــرة أخــرى وحكمــت علــى‬\n      ‫املدعــى عليــه الثانــي مبــا يلــي أوال ‪ :‬يجلــد (‪ )80‬جلــده حــد املســكر‬\n      ‫ثانيــا ‪ :‬يســجن املــدة ســنتني مــن تاريــخ إيقــاف ثالثــا ‪ :‬يجلــد (‪ )200‬مئتــي‬\n\n\n‫‪171‬‬\n\f‫جلــدة مفرقــة علــى أربــع دفعــات بــن كل دفعــة واالخــرى خمســة عشــر‬\n‫يــوم رابعــا ‪ :‬مينــع مــن الســفر خــارج اململكــة املــدة عامــن بعــد تنفيــذ‬\n‫احلكــم خامســا ‪:‬الغــاء الشــريحة رقــم (‪ )....‬وعــدم صرفــه لــه مــرة أخــرى‬\n‫كمــا حكمــت مبصــادرة جهــازي اجلــوال املذكــور رقمهمــا املصنعيــة‬\n‫يف الدعــوى وإيــداع قيمتهمــا يف حســاب اإلدارة العامــة املكافحــة‬\n‫املخــدرات وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليهمــا القناعة‬\n‫واملدعــي العــام عدمهــا وطلــب رفــع القضيــة حملكمــة اإلســتئناف بــدون‬\n‫الئحــة اعتراضيــة واكتفــى مبــا قــدم لــذا قــررت رفــع القضيــة حملكمــة‬\n‫اإلســتئناف باملنطقــة الشــرقية وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/07/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫لــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم األحــد‬\n‫املوافــق ‪ 1434/03/22‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‬\n‫وحيــث كنــت مشــارك بــدورة تدريبيــة مبدينــة الريــاض مــن تاريــخ‬\n‫‪ 1433/12/18‬إلــى ‪1434/03/18‬ه ـ وفيهــا حضــر املدعي العام بدائرة‬\n‫التحقيــق واإلدعــاء العــام باجلبيــل ‪ ......‬واملدعــى عليهمــا األول ‪ .....‬والثانــي‬\n‫‪ ....‬وكانــت قــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية باخلطــاب رقــم ( ‪ ) 331570304‬وتاريــخ ‪1433/11/21‬ه ـ‬\n‫املرفــق بــه القــرار رقــم ( ‪ ) 33444434‬وتاريــخ ‪1433/11/02‬ه ـ‬\n‫املتضمــن انــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫أن فضيلتــه اثبــت ادانــة املدعــى عليهمــا بالترويــج والتوســط ولــم يحكــم‬\n‫عليهمــا بغرامــة ماليــة حســب مــا نصــت عليــة املــادة الثامنــة والثالثــون‬\n‫مــن نظــام مكافحــة املخــدرات عليــه أجيــب فقــد حكمــت علــى املدعــى‬\n\n\n                                                                                         ‫‪172‬‬\n\f      ‫عليهمــا بدفــع غرامــة قدرهــا (‪ )1000‬ألــف ريــال تــودع يف حســاب اإلدارة‬\n      ‫العامــة ملكافحــة املخــدرات وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/ 03 /22‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n      ‫‪ ......‬القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم االثنــن املوافــق‬\n      ‫‪ 1434/08/29‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا حضــر‬\n      ‫املدعــى عليهمــا األول ‪ .....‬والثانــي ‪ .......‬وحيــث عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية باخلطــاب رقــم ‪341734585‬‬\n      ‫وتاريــخ ‪1434/08/02‬ه ـ واملقيــدة باحملكمــة برقــم ‪341917981‬‬\n      ‫وتاريــخ ‪1434/08/08‬ه ـ واملرفــق بــه القــرار رقــم ‪ 34280744‬وتاريــخ‬\n      ‫‪1434/07/26‬ه ـ املتضمــن أنــه وبدراســة القــرار وصــورة ضبطــه لوحــظ‬\n      ‫مــا يلــي أوال ‪ /‬أن فضيلتــه حكــم علــى املدعــى عليهمــا بدفــع ألــف ريــال‬\n      ‫ولــم يوضــح احلكــم هــل الدفــع لــكل واحــد منهمــا أم يشــتركان يف‬\n      ‫دفــع االلــف ثانيــا‪ /‬لــم يعــرض فضيلتــه احلكــم علــى املدعــى عليهمــا‬\n      ‫فيمــا حكــم بــه أخيــرا عليــه أجيــب أمــا مــا يتعلــق باملالحظــة األولــى‬\n      ‫فــإن مبلــغ الغرامــة احملكــوم بــه هــو علــى كل واحــد مــن املدعــى عليهــم‬\n      ‫وأمــا مــا يتعلــق باملالحظــة الثانيــة فبعــرض احلكــم األخيــر علــى املدعــى‬\n      ‫عليهمــا قــررا القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/29‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .......‬القاضــي باحملكمــة العامــة باجلبيــل والقائــم بعمــل املكتــب‬\n      ‫القضائــي الثالــث ففــي يــوم األربعــاء املوافــق ‪ 1434/10/28‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة ويف يــوم األربعــاء املوافــق ‪1434/10/28‬ه ـ‬\n\n\n‫‪173‬‬\n\f‫افتتحــت اجللســة الســاعة العاشــرة وكانــت قــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم(‪)342200831‬‬\n‫وتاريــخ ‪1434/01/01‬ه ـ واملقيــدة لدينــا برقــم(‪ )342315157‬وتاريــخ‬\n‫‪1434/10/14‬ه ـ واملرفــق بهــا القــرار رقــم (‪/34324474‬ج‪/1‬أ) وتاريــخ‬\n‫‪1434/09/22‬ه ـ واملتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                       ‫‪1434/10/28‬ه ـ‬\n\n\n\n\n                                                                          ‫‪174‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":165,"source_page_end":174,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb3c604191bbd78ee27bb0a9306ae757cf0944fa31b29c9c2dca51b8cd17558c","normalized_text_hash":"3ba2785b05a01aa73d1596abaf85c918c5f52e590d7651d4f4b34adba624a64a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p165-33357665"},{"id":"d8034249-2096-5c4a-a256-027c286ce375","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -اقرار مصدق شرع ا -طلب تشديد عقوبة -مراعاة تخفيف العقوبة لعدم السوابق -مراعاة تخفيف العقوبة لقلة الكمية املضبوطة -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال .","document_number":"33410812","case_number":"33427178","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل بن لنا من رئيس المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/19","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -اقرار مصدق شرع ا -طلب تشديد عقوبة -مراعاة تخفيف العقوبة لعدم السوابق -مراعاة تخفيف العقوبة لقلة الكمية املضبوطة -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33410812:‬تاريخه ‪1433/3/19:‬هـ‬\n                         ‫رقم الدعوى ‪33427178:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34174256‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة‪ -‬تعاطي احلبوب احملظورة‪ -‬اقرار‬\n      ‫مصــدق شــرع ًا‪ -‬طلــب تشــديد عقوبــة‪ -‬مراعــاة تخفيــف العقوبــة لعــدم‬\n      ‫الســوابق‪ -‬مراعــاة تخفيــف العقوبــة لقلــة الكميــة املضبوطــة ‪ -‬التعزيــر‬\n             ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال ‪.‬‬\n\n\n\n\n      ‫‪ -1‬الفقــرة االولــى مــن املــادة ‪ 38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقليــة ‪.‬‬\n                   ‫‪ -2‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بترويج حبوب‬\n      ‫اإلمفيتامــن احملظــورة بقصــد الكســب املــادي وتعاطيــه لهــا ‪ ،‬وطلــب‬\n      ‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء‬\n      ‫الشــريحة املســتخدمة يف اجلرميــة وتشــديد العقوبــة لترويجــه احلبــوب‬\n      ‫احملظــورة ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليــه بســبب قضيــة‬\n      ‫املخــدرات املنظــورة ‪ ،‬إقــرار املدعــى عليــه بالدعــوى‪ ،‬بنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة‬\n\n‫‪175‬‬\n\f‫واملنــع مــن الســفر‪ ،‬ومصــادرة اجلــوال وألغــاء الشــريحة للمســتخدمني يف‬\n                 ‫اجلرميــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1433/09/11‬ه ـ لــدي‬\n‫ـاء علــى اإلحالــة الــواردة‬\n                           ‫أنــا ‪ ......‬القاضــي باحملكمــة العامــة باجلبيــل بنـ ً‬\n‫لنــا مــن رئيــس احملكمــة برقــم ‪ 33427178‬واملقيــدة باحملكمــة‬\n‫برقــم ‪ 331199945‬يف ‪1433/06/25‬ه ـ حضــر ‪ .....‬بصفتــه املدعــي‬\n‫العــام بهيئــة التحقيــق باجلبيــل وادعــى علــى احلاضــر معــه ‪ ......‬ســعودي‬\n‫ا يف دعــواه أنــه بتاريــخ‬\n                          ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائـ ً‬\n‫‪1433/06/02‬ه ـ مت القبــض علــى املدعــى عليــه يف قضيــة مخــدرات‬\n‫وانتهــى التحقيــق إلــى توجيــه االتهــام لــه بترويــج عــدد (‪ )6‬ســت حبــات‬\n‫مــن حبــوب اإلمفيتامــن احملظــورة بقصــد الكســب املــادي وتعاطيــه‬\n                          ‫لــذات النــوع ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪ -1‬إقــراره املصــدق عليــه شــرع ًا املنــوه عنــه واملــدون علــى الصفحــة رقــم‬\n                                                 ‫(‪ )8‬مــن دفتــر التحقيــق املرفــق‪.‬‬\n‫‪ -2‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                                                ‫(‪ )1‬مــن دفتــر التحقيــق املرفــق‪.‬‬\n   ‫‪ -3‬التقرير الكيماوي الشرعي املنوه عنه املرفق على اللفة رقم (‪.)13‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق جنائيــة عثــر لــه على ســابقتني األولى‬\n‫ارتــكاب عــدة ســرقات اقترنــت بإطــاق النــار والثانيــة ســرقة ســيارات‬\n‫واقترنــت بســرقة حيوانــات‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪-‬‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا و‬\n\n                                                                                       ‫‪176‬‬\n\f      ‫نظامـ ًا أطلــب إثبــات مــا أســند إليــه وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه باآلتــي ‪-:‬‬\n      ‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املنصــوص عليهــا يف الفقــرة رقــم‬\n                              ‫(‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام املشــار إليــه‪.‬‬\n      ‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n                                          ‫املــادة رقــم (‪ )56‬مــن النظــام املشــار إليــه‪.‬‬\n      ‫‪ -3‬مصــادرة الهاتــف النقــال مــن نــوع (‪ ).....‬يحمــل الرقــم املصنعــي‬\n      ‫(‪ )............‬املســتخدم يف عمليــة ترويــج املخــدرات وفقـ ًا للفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات وإيــداع قيمتــه يف‬\n      ‫حســاب اإلدارة العامــة ملكافحــة املخــدرات وفقـ ًا لقــرار مجلــس الــوزراء‬\n      ‫رقــم (‪ )47‬وتاريــخ ‪1421/12/18‬ه ـ ‪ ،‬وإلغــاء الشــريحة املتعلقــة بالرقــم‬\n      ‫املســتخدم يف اجلرميــة وعــدم صرفهــا للمدعــى عليــه مــرة أخــرى وفق ـ ًا‬\n      ‫لتعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الوزراء‬\n                       ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n      ‫‪ -4‬تشــديد العقوبــة عليــه لترويجــه احلبــوب احملظــورة اســتناد ًا لبرقيــة‬\n      ‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n      ‫الداخليــة رقــم (‪2/8346/4/5/1‬ش) وتاريــخ ‪1427/2/8‬ه ـ هــذه‬\n      ‫ا مــا ذكــره املدعي‬   ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫العــام كلــه ثابــت وصحيــح فقــد قمــت ببيــع ســت حبــات مــن حبــوب‬\n      ‫االمفيتامــن احملظــورة مببلــغ وقــدره مائتــي ريــال كمــا أننــي أتعاطــى‬\n      ‫احلبــوب احملظــورة وأنــا تائــب ونــادم أشــد النــدم وأعدكــم أال أعــود ملثــل‬\n      ‫هــذه األمــور هكــذا أجــاب ثــم جــرى االطــاع علــى التقريــر الكيمــاوي‬\n      ‫الشــرعي رقــم ‪ 2245‬ك ش يف ‪1433/06/11‬ه ـ فوجــد يتضمــن إيجابيــة‬\n\n\n‫‪177‬‬\n\f‫احلبــوب املضبوطــة ملــادة اإلمفيتامــن احملظــورة ثــم جــرى اإلطــاع علــى‬\n‫مذكــرة الســوابق فوجــدت كمــا ذكــر املدعــي العــام وبعرضهــا علــى‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬  ‫املدعــى عليــه صــادق عليهــا فبنـ ً‬\n‫ومــا قــرره الطرفــان فقــد ثبــت لــدي قيــام املدعــى عليــه بترويــج عــدد (‪)6‬‬\n‫ســت حبــات مــن حبــوب اإلمفيتامــن احملظــورة بقصــد الكســب املــادي‬\n                             ‫وتعاطيــه لــذات النــوع وحكمــت عليــه مبــا يلــي‪:‬‬\n‫‪ -1‬تطبيــق العقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n‫مكافحــة املخــدرات وذلــك بســجنه خمــس ســنوات تعتبــر مــن تاريــخ‬\n‫إيقافــه وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات كل دفعــة‬\n‫خمســون جلــدة بــن الدفعــة والتــي تليهــا فتــرة ال تقــل عــن اســبوعني‬\n                                       ‫وتغرميــه مبلــغ وقــدره خمســة اآلف ريــال‪.‬‬\n‫‪-2‬منعــه مــن الســفر ملــدة خمــس ســنوات تعتبــر مــن تاريــخ خروجــه مــن‬\n                                                                            ‫الســجن‪.‬‬\n‫‪-3‬مصــادرة الهاتــف النقــال مــن نــوع ‪ .....‬يحمــل الرقــم املصنعــي ‪............‬‬\n     ‫املســتخدم يف عمليــة ترويــج املخــدرات والغــاء الشــريحة للرقــم (‪)......‬‬\n‫‪-4‬تشــديد العقوبــة عليــه لترويجــه احلبــوب احملظــورة وذلــك بجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن‬\n                            ‫الدفعــة والتــي تليهــا فتــرة ال تقــل عــن اســبوعني‪.‬‬\n‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n‫قناعتــه باحلكــم كمــا قــرر املدعــى عليــه عــدم قناعتــه بــه وطالــب‬\n‫بتمييــزه بــدون الئحــة فأجبتــه لطلبــه وأمــرت برفــع األوراق حملكمــة‬\n‫االســتئناف باملنطقــة الشــرقية‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/09/11‬هــ‪.‬‬\n\n\n                                                                                        ‫‪178‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1433/11/22‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف باملنطقة الشــرقية برقم ‪331737183‬‬\n      ‫يف ‪1433/11/10‬ه ـ وبرفقهــا قــرار اجــاب الفضيلــة قضــاة الدائــرة‬\n      ‫اجلزائيــة الثانيــة رقــم ‪ 33425305‬يف ‪1433/10/14‬ه ـ ونــص املقصــود‬\n      ‫منــه ( وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ مايلــي‪:‬‬\n      ‫أوالً‪ /‬لــم يتــم توقيــع املدعــى عليــه يف الضبــط كمــا يظهــر مــن صــورة‬\n      ‫الضبــط املرفقــة‪ .‬ثانيـاً‪ /‬أال يــرى فضيلتــه إعمــال املــادة الســتني مــن نظام‬\n      ‫املخــدرات ويخفــف الســجن علــى املدعــى عليــه وأنــه ليــس عليــه ســوابق‬\n      ‫والكميــة قليلــه فعلــى فضيلتــه مالحظــة مــا ذكــر ) أ‪ .‬هــ‪ .‬ولوجاهــة مــا‬\n      ‫ُذكــر فقــد رجعــت عمــا حكمــت بــه ســابق ًا وحكمــت علــى املدعــى‬\n      ‫عليــه مبايلــي‪ /1:‬تطبيــق العقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪)38‬‬\n      ‫مــع مراعــاة مــا ورد يف املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات نظــر ًا‬\n      ‫لعــدم وجــود ســوابق علــى املدعــى عليــه لقلــة الكميــة املروجــة وذلــك‬\n      ‫بســجنه ملــدة ســنتني تعتبــر مــن تاريــخ إيقافــه وجلــده خمســمائة جلــده‬\n      ‫مفرقــة علــى عشــر دفعــات كل دفعــه خمســون جلــده بــن الدفعــة والتــي‬\n      ‫تليهــا فتــرة ال تقــل عــن اســبوعني وتغرميــه مبلــغ وقــدره خمســة آالف ريــال‪.‬‬\n      ‫‪ /2‬منعــه مــن الســفر خــارج اململكــة ملــدة خمــس ســنوات تعتبــر من تاريخ‬\n      ‫خروجــه مــن الســجن‪ /3 .‬مصــدرة الهاتــف النقــال مــن نــوع نوكيــا يحمــل‬\n      ‫الرقــم املصنعــي ‪ ............‬املســتخدم يف عمليــة ترويــج املخــدرات وإلغــاء‬\n      ‫الشــريحة للرقــم(‪ /4 .).........‬تشــديد العقوبــة عليــه لترويجــه احلبــوب‬\n      ‫احملظــورة وذلــك بجلــده ثالثمائــة جلــده مفرقــة علــى ســت دفعــات كل‬\n      ‫دفعــه خمســون جلــده بــن الدفعــة والتــي تليهــا فتــرة ال تقل عن أســبوعني‪.‬‬\n\n\n‫‪179‬‬\n\f‫وبالنســبة ملــا ورد يف املالحظــة األولــى فقــد مت إكمــال الــازم حيالهــا‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم‬\n‫وقــرر املدعــي العــام عــدم قناعتــه بــه وأنــه ال يــزال علــى اعتراضــه بــدون‬\n‫الئحــة فأجبتــه لطلبــه وأمــرت بإعــادة املعاملــة الــى محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية كاملتبــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/22‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام كمــا حضــر املدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 332196032‬يف وبرفقهــا قــرار‬\n‫اصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم ‪ 33478085‬يف‬\n‫‪1433/12/26‬ه ـ ونــص املقصــود منــه ( وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه علــى قرارنــا رقــم ‪/33425305‬ج‪/2‬ب يف ‪1433/10/14‬ه ـ‬\n‫لوحــظ أن فضيلتــه منــع املدعــى عليــه مــن الســفر ملــدة خمــس ســنوات‬\n‫واملتعــن أن يكــون املنــع مــن الســفر مــدة مماثلــة لســجنه فعلــى فضيلتــه‬\n‫مالحــظ مــا ذكــر ) أ‪ .‬هــ‪ .‬ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد‬\n‫رجعــت عمــا حكمــت بــه ســابق ًا مبنــع املدعــى عليــه مــن الســفر ملــدة‬\n‫خمــس ســنوات وحكمــت مبنــع املدعــى عليــه مــن الســفر ملــدة ســنتني‬\n‫تعتبــر مــن تاريــخ خروجــه مــن الســجن وبعــرض احلكــم علــى الطرفــن‬\n‫قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام بقائــه علــى‬\n‫اعتراضــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف‪1434/02/20‬هــ‪ .‬احلمــد هلل وحــده وبعـدـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة لــدي أنــا املــازم‬\n‫القضائــي باحملكمــة العامــة باجلبيــل والقائــم بعمــل املكتــب القضائــي‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫ـاء علــى تعميــد فضيلــة رئيــس احملكمــة رقــم‬‫الثانــي بهــذه احملكمــة بنـ ً‬\n      ‫‪ 34828702‬يف ‪1434/04/06‬ه ـ وقــد وردتنــي املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 34711066‬يف ‪1434/04/08‬ه ـ‬\n      ‫وبرفقهــا قــرار اصحــاب الفضيلــة رقــم ‪ 34174256‬يف ‪1434/03/29‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم ولبيانــه جــرى منــا تدوينــه‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                   ‫حــرر يف ‪ 1434/04/20‬ه ـ ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":175,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"07c88690d0d19eba710a0771989fc87252f99f2337ed4f8e47990e253ac536a1","normalized_text_hash":"76fd39a79f77791ec200cf76f49a78ab6331fcad9ef6d5ff3aded58d2c43b281","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p175-33410812"},{"id":"2e65e854-d0a3-5efb-8aa8-45b7012547c2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -قيادة سيارة حتت تأثير املخدر -تستر -إثبات إدانة -إقامة حد املسكر على متعاطي احلشيش -تعزير بالسجن واجللد والغرامة واإلبعاد املادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","document_number":"33439718","case_number":"33473749","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/28","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -قيادة سيارة حتت تأثير املخدر -تستر -إثبات إدانة -إقامة حد املسكر على متعاطي احلشيش -تعزير بالسجن واجللد والغرامة واإلبعاد املادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33439718 :‬تاريخه ‪1433/10/28 :‬هـ‬\n                    ‫رقم الدعوى‪33473749 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 33454856‬تاريخه‪1433/7/8 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬قيادة‬\n ‫ســيارة حتــت تأثيــر املخــدر ‪ -‬تســتر ‪ -‬إثبــات إدانــة ‪ -‬إقامــة حــد املســكر‬\n ‫علــى متعاطــي احلشــيش ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واإلبعــاد‬\n\n\n\n                  ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بترويجــه قطعــة مــن احلشــيش‬\n ‫املخــدر وتعاطيــه احلشــيش املخــدر وقيادتــه للســيارة حتــت تأثيــر تعاطــي‬\n ‫احلشــيش و تســتره علــى مصــدر مــا مت ترويجــه‪ ،‬طلــب املدعــي العــام‬\n ‫إثبــات مــا أســند إليــه و احلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n ‫املاليــة‪ ،‬إبعــاده إلــى خــارج البــاد بعــد انتهــاء عقوبــة الســجن وعــدم‬\n ‫الســماح لــه بالعــودة مــرة أخــرى وإجــراء املقتضــى الشــرعي لقــاء تعاطيــه‬\n ‫احلشــيش املخــدر ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة و إلغــاء‬\n ‫الشــريحة املســتخدمة يف اجلرميــة وإلــزام املدعــى عليــه بــرد املبلــغ املرقــم‬\n ‫كامـاً‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليــه بعــد ورود بــاغ عنــه‬\n ‫بأنــه يقــوم بالتوســط يف بيــع احلشــيش املخــدر‪ ،‬وقــد مت التنســيق مــع‬\n ‫أحــد املصــادر الســرية لإلطاحــة بــه و مت االتصــال علــى املدعــى عليــه‬\n\n                                                                                       ‫‪182‬‬\n\f      ‫مــن قبــل املصــدر ومت التنســيق معــه واالتفــاق علــى الزمــان و املــكان و‬\n      ‫بعــد ذلــك مت القبــض عليــه متلبسـ ًا بعــد اســتالم املبلــغ املرقــم مــن املصــدر‬\n      ‫واســتالم املدعى عليه قطعة احلشــيش من قائد ســيارة أخرى و تســليمها‬\n      ‫للمصــدر‪ ،‬صــادق املدعــى عليــه علــى مــا نســب إليــه بتعاطــي احلشــيش‬\n      ‫املخــدر‪ ،‬وأنكــر املدعــى عليــه ترويجــه لقطعــة احلشــيش املخــدر‪ ،‬رغــم‬\n      ‫إقــراره حتقيق ـ ًا وثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه‪ ،‬معاملــة‬\n      ‫املدعــى عليــه وفــق املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه‬\n      ‫بالســجن واجللــد وإقامــة حــد املســكر علــى املدعــى عليــه والغرامــة و‬\n      ‫اإلبعــاد وصــرف النظــر عــن دعــوى املدعي العام بإرجــاع املبلغ احلكومي‬\n                ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬            ‫و مصــادرة اجلــوال ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33473749‬وتاريــخ ‪ 1433/07/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331353830‬وتاريــخ ‪ 1433/07/19‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1433/08/07‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ....‬وقــدم الئحة الدعــوى قائال بصفتي عضو‬\n      ‫هيئــة التحقيــق واالدعــاء العــام بدائــرة شــرق مدينــة الريــاض ادعي على‪/‬‬\n      ‫اســم املتهــم‪ .... :‬اجلنــس‪ :‬ذكــر ‪،‬اجلنســية‪ :‬فلســطيني ‪،‬الديانــة‪ :‬مســلم‪،‬‬\n      ‫نــوع الهويــة‪ :‬رخصــة إقامــة‪ ،‬رقــم الهويــة‪ ،..... :‬املهنــة‪ :‬طالــب ‪ ،‬احلالــة‬\n      ‫االجتماعيــة‪ :‬أعــزب ‪،‬جهــة اإليقــاف‪ :‬شــعبة ســجن امللــز ‪،‬تاريــخ القبــض‪:‬‬\n\n‫‪183‬‬\n\f‫‪، 1433/6/5‬حالــة املتهــم‪ :‬موقــوف ‪،‬االتهــام‪ :‬بيــع ‪ ،‬املــواد املخــدرة‬\n‫الســوابق‪ :‬ال يوجــد فبتاريــخ ‪1433/6/5‬ه ـ قبــض علــى املذكــور مــن‬\n‫قبــل إحــدى فــرق قــوة املســاندة اخلاصــة اثــر توافــر معلومــات لــدى الفرقــة‬\n‫عــن طريــق أحــد مصادرهــا الســرية عــن قيــام املتهــم املذكــور بالتوســط‬\n‫يف ترويــج احلشــيش املخــدر ويســكن بحــي الربــوة ويتواجــد علــى هاتفــه‬\n‫اجلــوال رقــم (‪ )....‬وقــد اســتعد املصــدر لإلطاحــة بــه باجلــرم املشــهود عليــه‬\n‫مت اإليعــاز للمصــدر باالتصــال علــى جــوال املــروج وطلــب منــه كميــة مــن‬\n‫احلشــيش املخــدر مببلــغ وقــدره (‪ )200‬مائتــي ريــال وأفــاد للمصــدر بأنــه‬\n‫ســوف يأخــذ قطعــة احلشــيش مــن شــخص آخــر بعــد اســتالمه للمبلــغ‬\n‫ومت االتفــاق معــه علــى ذلــك وطلــب مــن املصــدر احلضــور إلــى أســواق‬\n‫(‪ )....‬ومت تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا وتزويــده باملبلــغ املرقــم وقــدره‬\n‫(‪ )200‬مائتــي ريــال ومت تكليــف أحــد أفــراد الفرقــة مبرافقــه املصــدر‬\n‫لإلشــراف علــى عمليــة االســتالم والتســليم وبانتقــال الفرقــة إلــى املوقــع‬\n‫املتفــق عليــه حضــر املــروج وركــب مــع املصــدر وفــرد الفرقــة املكلــف‬\n‫واســتلم املبلــغ املرقــم وقــدره (‪ )200‬مائتــي ثــم قــام باالتصــال علــى‬\n‫شــخص وأخبــره بأنــه يف املوقــع وعندهــا حضــرت ســيارة مــن نــوع ‪....‬‬\n‫حتمــل اللوحــة رقــم (‪( )......‬مت فــرز أوراق مســتقلة للســيارة وقائدهــا ومت‬\n‫بعثهــا إلــى مكافحــة املخــدرات بشــرق الريــاض مبوجــب اخلطــاب رقــم‬\n‫(‪ )5109‬وتاريــخ ‪1433/7/2‬ه ـ حلــن القبــض عليــه وإحضــاره) وتوقــف‬\n‫بجانــب ســيارة الفرقــة واســتلم املبلــغ املرقــم وقــدره (‪ )200‬مائتــي ريــال‬\n‫مــن املذكــور وســلمه قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر تــزن‬\n‫(‪ )5،2‬خمســة جرامــات وعشــري اجلــرام ثــم قــام بتســليمها إلــى الفــرد‬\n‫املكلــف ومتــت مداهمــة املذكــور والقبــض عليــه ومبتابعــة صاحــب‬\n\n\n                                                                                        ‫‪184‬‬\n\f      ‫الســيارة ‪ ....‬اختفــى عــن األنظــار لكونــه يقــود الســيارة بســرعة جنونيــة‬\n      ‫ومتهــورة وبتفتيــش املذكــور شــخصي ًا عثــر معــه علــى جهــاز جــوال مــن‬\n      ‫نــوع ‪ .....‬يحمــل الرقــم املصنعــي (‪ )............‬اتضــح انــه نفــس اجلــوال الــذي‬\n      ‫متــت عليــه عمليــة التفــاوض والتنســيق ولــم يعثــر معــه علــى املبلــغ املرقــم‬\n                                                           ‫وقــدره (‪ )200‬مائتــي ريــال ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض رقــم (‪/6317‬س) لعــام‬\n      ‫‪1433‬ه ـ ايجابيــة عينــة القطعــة املروجــة ملــادة احلشــيش وهــو مــن املــواد‬\n      ‫املخــدرة واملدرجــة يف اجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة ‪ .‬جــرى مخاطبــة مكافحــة املخــدرات‬\n      ‫بشــرق الريــاض مبوجــب اخلطــاب رقــم (‪ )2350‬وتاريــخ ‪1433/6/7‬ه ـ‬\n      ‫لطلــب حجــز الهاتــف مــع الشــريحة متهيــد ًا ملصادرتــه وبســماع أقــوال‬\n         ‫املتهــم اعتــرف بصحــة قيامــه بالتوســط يف ترويــج احلشــيش املخــدر ‪.‬‬\n      ‫وباســتجوابه اعتــرف حتقيقـ ًا بحيــازة احلشــيش املخــدر بقصــد التعاطــي‬\n      ‫وتعاطيــه احلشــيش املخــدر منــذ ثــاث ســنوات آخرهــا يــوم القبــض عليــه‬\n      ‫كمــا اعتــرف بقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر‬\n      ‫ولــم يــدل املذكــور بــأي معلومــات عــن مصــدر حصولــه علــى احلشــيش‬\n      ‫املخــدر ‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام إلــى‪...../‬‬\n      ‫ببيــع قطعــة مــن احلشــيش املخــدر تــزن (‪ )5،2‬خمســة جرامــات وعشــري‬\n      ‫اجلــرام بقصــد االجتــار والترويــج وتعاطيــه احلشــيش املخــدر املجــرم‬\n      ‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪،‬‬\n      ‫وقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر املعاقــب علــى‬\n\n\n‫‪185‬‬\n\f‫ذلــك مبوجــب املــادة (‪ )68‬مــن نظــام املــرور الصــادر باملرســوم امللكــي‬\n   ‫رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ ‪ ،‬وتســتره علــى مصــدر مــا مت‬\n      ‫ترويجه املعاقب على ذلك شرع ًا ‪ .‬وذلك لألدلة والقرائن التالية ‪- :‬‬\n‫‪ -1‬مــا تضمنــه اعترافــه حتقيق ـ ًا بحيازتــه احلشــيش وتعاطيــه وقيادتــه‬\n‫)‪.‬‬              ‫للســيارة حتــت تأثيــره املنــوه عنــه املــدون علــى اللفــات رقــم (‬\n‫‪ -2‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املدون‬\n‫علــى الصفحــة رقــم ( ) مــن ملــف إجــراءات االســتدالل املرفــق لفــة ( ) ‪.‬‬\n‫‪ -3‬مــا تضمنــه محضــر البــاغ والقبــض واالنتقــال والتفتيــش املنــوه عنــه‬\n‫) مــن ملــف إجــراءات االســتدالل‬                  ‫املــدون علــى الصفحــات رقــم (‬\n                                                                      ‫املرفــق لفــة ( ) ‪.‬‬\n‫‪ -4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n‫رقــم ( ) ‪ .‬وبــورود صحيفــة ســوابقه اتضــح عــدم وجــود ســوابق مســجلة‬\n                                                                 ‫ضــده حتــى تاريخــه ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪:‬‬\n‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا ملــا ورد بالفقــرة‬\n‫(األولــى) مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                             ‫العقليــة ملــا أســند إليــه‪.‬‬\n‫‪ -2‬إبعــاده إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه وعــدم‬\n‫الســماح لــه بالعــودة مــرة أخــرى وفق ـ ًا للفقــرة (الثانيــة) مــن املــادة (‪)56‬‬\n                                                          ‫مــن النظــام املشــار إليــه ‪.‬‬\n         ‫‪ -3‬إجراء املقتضى الشرعي بحقه لقاء تعاطيه احلشيش املخدر ‪.‬‬\n‫‪ -4‬مصــادرة الهاتــف اجلــوال املســتخدم يف التنســيق لعمليــة الترويــج مــن‬\n\n\n                                                                                              ‫‪186‬‬\n\f      ‫نــوع نوكيــا حامــل الرقــم املصنعــي (‪ )............‬وفق ـ ًا للفقــرة (‪ )1‬مــن‬\n                                                ‫املــادة (‪ )53‬مــن النظــام املشــار إليــه ‪.‬‬\n      ‫‪ -5‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة التــي حتمــل الرقــم (‪)....‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حالــة صــدور احلكــم باإللغــاء وإبــاغ‬\n      ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا لتعميــم صاحــب الســمو‬\n          ‫امللكــي وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n      ‫‪ -6‬النظــر فيمــا يتعلــق بقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش‬\n      ‫املخــدر وفــق الفقــرة (الثانيــة) مــن املرســوم امللكــي املشــار إليــه رقــم‬\n      ‫(م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ ‪ - .‬إلــزام املتهــم املذكــور بــرد املبلــغ‬\n      ‫ا وقــدره (‪ )200‬مائتــي ريــال اســتناد ًا لبرقيــة صاحــب‬           ‫املرقــم كام ـ ً‬\n      ‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n                                   ‫رقــم (‪ )65980‬وتاريــخ ‪1428/10/23-22‬ه ـ ‪.‬‬\n      ‫‪ -8‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا مت ترويجــه‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا‬\n      ‫ذكــره املدعــي العــام مــن توســطي يف بيــع احلشــيش املخــدر غيــر صحيــح‬\n      ‫والصحيــح انــه وجــد معــي قطعــة حشــيش قدرهــا خمســة جــرام وعشــري‬\n      ‫اجلــرام مــن احلشــيش املخــدر لغــرض االســتخدام فأنــا أدخــن احلشــيش‬\n      ‫وليــس علــي ســوابق هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام‬\n      ‫علــى توســط املدعــى عليــه مــن ترويــج احلشــيش قــال اطلــب رفــع اجللســة‬\n      ‫إلحضارهــا فرفعــت اجللســة وقــد حــددت لهمــا موعــدا هــو يــوم الســبت‬\n      ‫املوافق ‪1433/08/24‬هـ الساعة التاسعة ‪ .‬وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/08/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1433/08/24‬ه ـ‬\n\n\n‫‪187‬‬\n\f‫افتتحــت اجللســة الســاعة التاســعة وخمســون دقيقــة وفيهــا حضــر املدعي‬\n‫العــام ‪ ....‬واملدعــى عليــه ‪ ....‬ولــم حتضــر البينــة وحــددت لــه موعــدا هــو‬\n‫يــوم األحــد املوافــق ‪1433/09/10‬ه ـ الســاعة احلاديــة عشــر‪ .‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1433/08/24‬ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم األحــد‬\n‫املوافــق‪ 1433/09/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 02:00‬وفيهــا حضر‬\n‫املدعــي العــام ‪ ....‬واملدعــى عليــه ‪ ....‬ولــم يحضــر املدعــي العــام الفرقــة‬\n‫القابضــة وطلــب رفــع اجللســة إلحضارهــم ورفعــت اجللســة لذلــك وقــد‬\n‫حــددت لهمــا موعــدا هــو يــوم االثنــن ‪1433/10/9‬ه ـ الســاعة التاســعة‬\n    ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1433/09/10‬ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم األحــد‬\n‫املوافق‪1433/10/09‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وخمســن‬\n‫دقيقــه وفيهــا حضــر املدعــي العــام ‪ ....‬واملدعــى عليــه ‪ ....‬ولــم يحضــر‬\n‫املدعــي العــام الفرقــة القابضــة وطلــب رفــع اجللســة إلحضارهــم ورفعــت‬\n‫اجللســة لذلــك وقــد حــددت لهما موعدا هو يوم االثنــن ‪1433/10/16‬هـ‬\n‫الســاعة التاســعة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافق‪1433/10/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11:00‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه مؤيــد ولــم يحضــر املدعــي العــام الفرقــة القابضــة وهــذه هــي‬\n‫اجللســة الرابعــة لطلبهــا وقــد جــرى نقــاش املدعــى عليــه عــن دعــوى‬\n‫املدعــي العــام فأصــر علــى جوابــه وأقـ َّـر انــه قــاد الســيارة وهو حتــت تأثير‬\n‫احلشــيش هــذا وقــد جــرى اطالعــي علــى دفتــر التحقيــق املرفــق لفــه (‪)1‬‬\n\n\n                                                                                          ‫‪188‬‬\n\f      ‫صفحــة (‪ )18‬وجــدت املدعــى عليــه ‪ ...‬ملــا ســئل انــت متهــم بالتوســط‬\n      ‫يف ترويــج احلشــيش املخــدر اجــاب قائــا نعــم صحيــح وملــا ســئل مــا هــو‬\n      ‫قصــدك مــن التوســط يف تلــك العمليــة اجــاب بــأن الشــخص الــذي قــام‬\n      ‫بطلبــي احلشــيش قــال احضــر لــي احلشــيش مقابــل مبلــغ مالــي ولذلــك‬\n      ‫ســوف أوفــره لــك وبعرضــه عليــه اجــاب قائــا نعــم اجبــت مبــا ذكــر‬\n      ‫لــدى مكافحــة املخــدرات نتيجــة الضــرب مــن قبــل احملقــق وقــد بصمــت‬\n      ‫عليــه هــذا وقــد جــرى اطالعــي علــى واقعــة القبــض بدفتــر التحقيــق‬\n      ‫املرفــق لفــه (‪ )1‬ص (‪ )11.12‬وجدتــه كمــا نــص عليــه يف دعــوى املدعــي‬\n      ‫العــام ولــم اجــد فيــه اســماء االشــخاص اللذيــن قامــوا بالقبــض ولــم اجده‬\n      ‫موقعــا وبعرضــه علــى املدعــى عليــه اجــاب قائــا نعــم لقــد قبــض علــي‬\n      ‫مــن قبــل الفرقــة ولكــن وجــدوا معــي قطعــة حشــيش لكــن لــم ابــع ولــو‬\n      ‫كنــت بعــت ايــن دراهمــه فــا صحــة لذلــك هــذا وقــد جــرى اطالعــي‬\n      ‫علــى التقريــر الكيمــاوي الشــرعي رقــم ( ‪/6317‬س) لعــام ‪1433‬ه ـ‬\n      ‫املتضمــن ايجابيــة القطعــة املروجــة ملــادة احلشــيش كمــا جــرى اطالعــي‬\n      ‫علــى صحيفــة ســوابق املدعــى عليــه ‪ ...‬فلــم اجــد لــه ســوابقا وقــد وجــدت‬\n      ‫انــه اوقــف يف ‪1433/6/5‬ه ـ فبنــاء ملــا تقــدم مــن الدعــوى واالجابــة‬\n      ‫وحيــث اقــر املدعــى عليــه مؤيــد بحيازتــه لقطعــة احلشــيش املذكــورة‬\n      ‫يف الدعــوى وذكــر انهــا للتعاطــي وليســت للترويــج وحيــث اقــر بتدخــن‬\n      ‫احلشــيش وحيــث اقــر يف دفتــر التحقيــق لــدى احملقــق بالتوســط يف بيعــه‬\n      ‫قطعــة احلشــيش وادعــى انــه حتــت الضــرب وبنــاء ملــا ورد يف محضــر‬\n      ‫القبــض وحيــث لــم يحضــر شــهود الفرقــة القابضــة ولــم يــدل يف دفتــر‬\n      ‫التحقيــق وإلجابتــه عــن اســتخدامه للجــوال والشــريحة يف ترويــج‬\n      ‫املخــدرات فقــد ثبــت لــدي مــا نســب للمدعــى عليــه مــن ترويــج احلشــيش‬\n\n\n‫‪189‬‬\n\f‫البالــغ وزنــه خمســة جرامــات وعشــري اجلــرام وتعاطيــه للحشــيش ونظــرا‬\n‫لصغــر ســن املدعــى عليــه وعــدم ســوابقه ولقلــة الكميــة فقــد قــررت‬\n‫معاملتــه حســب املــادة الســتون مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة وقــررت مــا يلــي اوال ســجن املدعــى عليــه ســنة اعتبــارا مــن تاريــخ‬\n‫توقيفــه ثانيــا جلــده ثمانــن جلــده حــد املســكر ثالثــا جلــده تعزيــرا علــى‬\n‫تســتره علــى املصــدر اربعــن جلــده رابعــا تغرميــه الــف ريــال خلزينــة الدولــة‬\n‫تعزيــرا خامســا ابعــاده عــن اململكــة بعــد انتهــاء فتــرة عقوبــة ســجنه‬\n‫وعــدم الســماح بالرجــوع للمملكــة اال حســب مــا تقتضيــه تعليمــات‬\n‫احلــج والعمــرة سادســا ثبــت لــدي قيــادة املدعــى عليــه للســيارة وهــو حتــت‬\n‫تأثيــر احلشــيش ســابعا صرفــت النظــر عــن دعــوى املدعــي العــام ارجاعــه‬\n‫املبلــغ املرقــم مائتــي ريــال وكذلــك مصــادرة اجلــوال وبعــرض احلكــم‬\n‫علــى اجلميــع قنــع املدعــى عليــه باحلكــم ولــم يقنــع املدعــي العــام وطلــب‬\n‫تدقيقــه مــن قبــل محكمــة االســتئناف بــدون الئحــة فأجيــب لطلبــه‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم ‪ .‬حــرر يف ‪ 1433/10/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء ‪1434/3/18‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 1.30‬بعــد الظهــر وفيهــا حضــر املدعــي العــام ‪......‬‬\n‫واملدعــى عليــه ‪ ...‬وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف‬\n‫وبرفقهــا قــرار أصحــاب الفضيلــة رقــم ‪ 3439879‬يف ‪1434/2/18‬ه ـ‬\n‫ونــص احلاجــة منــه وبدراســة القــرار وصــورة وأوراق املعاملــة قررنــا‬\n‫إعادتهــا ملالحظــة اآلتــي ‪ :‬أوالً‪ /‬أثبــت فضيلتــه مــا نســب إلــى املدعــى‬\n‫عليــه مــن ترويــج احلشــيش املخــدر وهــذا محــل نظــر فليــس يف اعتــراف‬\n‫املدعــى عليــه حتقيق ـ ًا مــا يثبــت ذلــك ولــم يبــن فضيلتــه نــوع الترويــج‬\n\n\n                                                                                        ‫‪190‬‬\n\f      ‫ثانيـاً‪ /‬ملــا عــرض علــى املدعــى عليــه إقــراره حتقيقـ ًا ادعــى أنــه اعتــرف‬\n      ‫بــه نتيجــة الضــرب وهــذه الدعــوى يتوجــه عرضهــا علــى املدعــي العــام‬\n      ‫وإجــراء الوجــه الشــرعي فيهــا ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ .....‬توقيعــه‬\n      ‫وختمــه قاضــي اســتئناف ‪ ...‬توقيعــه وختمــه رئيــس الدائــرة ‪ ....‬توقيعــه‬\n      ‫وختمــه واجلــواب علــى مالحظــة أصحــاب الفضيلــة األولــى والثانيــة أنــه‬\n      ‫جــرى مناقشــة املدعــى عليــه ‪ .....‬عــن إقــراره لــدى احملقــق بــاع خمســة‬\n      ‫جرامــات مــن احلشــيش وعشــرين اجلــرام قــال نعــم أقــررت علــى الضــرب‬\n      ‫بحديــدة املســدس وال أطلــب بإحالــة للمستشــفى للكشــف علــي فــا‬\n      ‫أريــد ذلــك هكــذا قــال وعليــه فــإن نوعيــة الترويــج هــي التوســط يف بيــع‬\n      ‫احلشــيش واضيــف علــى مــا ذكــر يف سادسـ ًا بــأن عقوبتــه علــى قيادتــه‬\n      ‫للســيارة وهــو حتــت تأثيــر احلشــيش عائــدة للجهــة املختصــة واهلل املوفــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬حــرر‬\n                                                                ‫يف ‪ 1434/03/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34508739‬‬\n      ‫وتاريــخ ‪1434/6/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ ‪ ..... /‬املســجل برقــم ‪ 33439718‬وتاريــخ‬\n      ‫‪1433/10/28‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ( ...... /‬فلســطيني‬\n      ‫اجلنســية ) التهامــه بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وحيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب‬\n\n\n‫‪191‬‬\n\f‫بــه فضيلتــه علــى قــرار الدائــرة رقــم ‪ 3439879‬وتاريــخ ‪1434/2/18‬ه ـ‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر مــع تنبيــه فضيلتــه‬\n‫لذكــر املــدة بــن احلــد والتعزيــر يف القــرار قبــل بعثهــا جلهــة التنفيــذ ‪.‬‬\n ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪192‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":182,"source_page_end":192,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a06f4a9f5fd31ac5c02e152dfa8bbc82636429ca01a3a3ffdfd36a6892aff75","normalized_text_hash":"9a2e349b74c0b8a7934cea0075cf63ec48122557cda7defe7e3d6b278062b3c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p182-33439718"},{"id":"413f90cb-a595-56c2-b20e-dce4dc251185","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -تستر- إقامة حد املسكر على تعاطي احلشيش -التعزير بالسجن واجللد والغرامة واملنع من السفر -التعزير مبصادرة اجلوال والشريحة املستخدمتان يف اجلرمية -التعزير بالغرامة لتستره على املصدر.","document_number":"33361642","case_number":"33475473","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/3","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -تستر- إقامة حد املسكر على تعاطي احلشيش -التعزير بالسجن واجللد والغرامة واملنع من السفر -التعزير مبصادرة اجلوال والشريحة املستخدمتان يف اجلرمية -التعزير بالغرامة لتستره على املصدر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 33361642:‬تاريخه ‪1433/7/3:‬هـ‬\n                         ‫رقم الدعوى‪33475473:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 33454856‬تاريخه‪1433/11/15 :‬هـ‬\n\n\n      ‫مخدرات ‪ -‬ترويج احلشــيش املخدر‪ -‬تعاطي احلشــيش املخدر‪ -‬تســتر‪-‬‬\n      ‫إقامــة حــد املســكر علــى تعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد‬\n      ‫والغرامــة واملنــع مــن الســفر‪ -‬التعزيــر مبصــادرة اجلــوال والشــريحة‬\n       ‫املســتخدمتان يف اجلرميــة ‪ -‬التعزيــر بالغرامــة لتســتره علــى املصــدر‪.‬‬\n\n\n\n\n                   ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                   ‫‪ -2‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n      ‫‪ -3‬الفقــرة األولــى مــن املــادة ‪ 58‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقلية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليــه ترويــج احلشــيش املخــدر وحيــازة‬\n      ‫احلشــيش املخــدر بقصــد الترويــج والتعاطــي وتعاطيــه للحشــيش املخدر‪،‬‬\n      ‫وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكم عليه بالســجن واجللد‬\n      ‫والغرامــة املاليــة ومنعــه مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء‬\n      ‫شــريحته املســتخدمة يف اجلرميــة وعــدم صرفهــا لنفــس املشــترك ‪ ،‬حيــث‬\n      ‫ـاء علــى إخباريــة مفادهــا أن املدعــى‬\n                                           ‫أنــه مت القبــض علــى املدعــى عليــه بنـ ً‬\n      ‫عليــه يقــوم بترويــج احلشــيش املخــدر فتــم التنســيق مــع أحــد املصــادر‬\n\n‫‪193‬‬\n\f‫الســرية لإلطاحــة باملدعــى عليــه ومت التنســيق مــع املدعــى عليــه مــن قبــل‬\n‫وس ـلِم للمصــدر املبلــغ املرقــم ومت تفتيشــه تفتيش ـ ًا دقيق ـ ًا ومت‬\n                                                                      ‫املصــدر ُ‬\n‫مقابلــة املصــدر للمدعــى عليــه وركــب معــه يف الســيارة ثــم نــزل املصــدر‬\n‫وســلم للفرقــة قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر ‪ ،‬ثــم قبــض‬\n‫علــى املدعــى عليــه ووجــد املبلــغ املرقــم معــه وكذلــك اجلــوال املســتخدم‬\n‫يف اجلرميــة ‪ ،‬إقــرار املدعــى عليــه ثبــوت إدانــة املدعــى عليــه ‪ ،‬بنــاء علــى‬\n‫مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســحن واجللــد‬\n‫والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال والشــريحة املســتخدمني‬\n‫يف اجلرميــة وإقامــة حــد املســكر ‪ ،‬وصــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33475473‬وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331360505‬وتاريــخ ‪1433/07/20‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1433/07/23‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام‪ ...... /‬وادعــى علــى‪ ............ ...... /‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )......‬بتاريــخ ‪1433/6/6‬ه ـ‬\n‫قبــض علــى املذكــور مــن قبــل إحــدى فــرق قــوة املســاندة اخلاصــة التابعــة‬\n‫للمديريــة العامــة ملكافحــة املخــدرات مبنطقــة الريــاض وذلــك بنــاء‬\n‫علــى املعلومــات الــواردة لهــا عــن طريــق أحــد املصــادر الســرية عــن وجــود‬\n‫شــخص يدعــى ‪ ...... /‬يســكن يف حــي ‪ ............‬ويقــوم بترويــج احلشــيش‬\n\n                                                                                       ‫‪194‬‬\n\f      ‫املخــدر ويتواجــد علــى هاتفــه اجلــوال رقــم (‪ )......‬ويســتقل ســيارة مــن نــوع‬\n      ‫‪ ......‬وابــدى املصــدر اســتعداده بالتعــاون يف القبــض عليــه وبنــاء ًا علــى‬\n      ‫ذلــك مت االيعــاز للمصــدر باالتصــال عليــه وطلــب منــه توفيــر قطعــة مــن‬\n      ‫احلشــيش املخــدر مقابــل (‪ )200‬مائتــا ريــال فوافــق الشــخص املذكــور‬\n      ‫وحــدد مــع املصــدر مــكان وتوقيــت تســليم القطعة املروجة‪ ،‬وبنــاء ًا عليه‬\n      ‫مت ترقيــم مبلــغ مرقــم وقــدره (‪ )200‬مائتــان ريــال بعــد تفتيــش املصــدر‬\n      ‫بــكل دقــة وزود باملبلــغ املرقــم ويف املوعــد احملــدد نــزل املصــدر مــن‬\n      ‫ســيارة الفرقــة واجتــه الــى احــدى الصيدليــات ملقابلــة املــروج وبعد حوالي‬\n      ‫خمــس دقائــق حضــرت ســيارة مــن نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪).... ...‬‬\n      ‫(تعــود ملكيتهــا ملكتــب ‪ ............‬لتأجيــر الســيارات) كان يســتقلها‬\n      ‫املذكــور ووقفــت بجانــب املصــدر حيــث قــام املصــدر بالركــوب معــه‬\n      ‫يف الســيارة وبعــد ان حتــرك اخــذ املســار الثانــي مــن الشــارع وتوقفــت‬\n      ‫الســيارة ونــزل منهــا املصــدر وبعــد حتــرك الســيارة مــرة اخــرى ووقوفــه‬\n      ‫عنــد االشــارة متــت مداهمتــه والقبــض عليــه وقــام املصــدر بتســليم قائــد‬\n      ‫الفرقــة القطعــة املروجــة وهــي قطعــة تــزن (‪ )2,5‬جرامــن ونصــف‬\n      ‫اجلــرام يشــتبه ان تكــون مــن احلشــيش املخــدر ‪،‬وبتفتيــش املذكــور عثــر‬\n      ‫يف جيــب بنطلونــه اخللفــي علــى املبلــغ املرقــم وعثــر علــى الهاتــف اجلــوال‬\n      ‫املســتخدم يف عمليــة التفــاوض معــه ويحمــل الرقــم املصنعــي (‪.)............‬‬\n      ‫‪ -1‬مت االمــر بتســليم الســيارة مبوجــب اخلطــاب ‪ 2709‬وتاريــخ‬\n                                                                      ‫‪1433/6/9‬ه ـ ‪.‬‬\n      ‫‪ -2‬مت االمــر بحجــز اجلــوال والشــريحة متهيدا للمصــادرة مبوجب اخلطاب‬\n                                                    ‫رقم ‪ 2632‬وتاريخ ‪1433/6/9‬هـ ‪.‬‬\n      ‫‪ -3‬مت االمــر بتســليم املبلــغ املالــي وقــدره (‪ )167‬املضبــوط مــع املذكــور‬\n\n\n‫‪195‬‬\n\f                          ‫مبوجــب اخلطــاب رقــم ‪ 2464‬وتاريــخ ‪1433/6/8‬ه ـ ‪.‬‬\n‫‪ -4‬وبطلــب القــرار الشــرعي رقــم ‪66/5/‬ق وتاريــخ ‪1426/2/4‬ه ـ تبــن‬\n‫ان الســابقة املســجلة عليــه حيــازة احلشــيش املخــدر بقصــد التعاطــي‬\n                                                     ‫وليســت ترويــج مخــدرات‪.‬‬\n‫‪ -5‬مت مخاطبــة ادارة االدلــة اجلنائيــة لتعديــل الوصف اجلرمي يف صحيفة‬\n‫الســوابق مــن ترويــج املخــدرات الــى حيــازة املخــدرات بقصــد التعاطــي‬\n                        ‫مبوجــب اخلطــاب رقــم ‪ 6028‬وتاريــخ ‪1433/7/14‬هــ‪.‬‬\n              ‫وبسماع أقواله االولية اقر بانه سلم املصدر قطعة احلشيش ‪.‬‬\n‫وباســتجوابه اقــر بترويــج احلشــيش املخــدر واقــر بتعاطيــه لــه واقــر بانــه‬\n‫بعــد ان اشــترى القطعــة مــن شــخص يدعــى‪ ... /‬اقتطــع منهــا قطعــة‬\n‫صغيــرة وضعهــا يف جيبــه وانــه عنــد مداهمــة الفرقــة لــه قــام بإخراجهــا‬\n                                                              ‫مــن جيبــه ورماهــا‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي املرفــق رقــم (‪/6318‬س) لعــام‬\n‫‪1433‬ه ـ ايجابيــة عينــة القطعــة املروجــة للحشــيش وهــو املــواد املخــدرة‬\n‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــه املخــدرات‬\n‫واملؤثــرات العقليــة‪ .‬وقــد اســفرت اجــراءات التحقيــق الــى توجيــه االتهــام‬\n‫لــ‪ ........ /‬ببيــع مــا وزنــه (‪ )2,5‬جرامــن ونصــف اجلــرام مــن احلشــيش‬\n‫املخــدر بقصــد االجتــار والترويــج وحيازتــه لقطعــة حشــيش مخــدر مــن‬\n‫ذات نــوع القطعــة املبيعــة غيــر معروفــة الــوزن بقصــد الترويــج والتعاطــي‬\n‫وتعاطيــه للحشــيش املخــدر املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا مت ترويجــه‬\n                                                   ‫املعاقــب علــى ذلــك شــرع ًا ‪.‬‬\n\n\n                                                                                      ‫‪196‬‬\n\f                                                            ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n                 ‫‪ -1‬ما تضمنه اعترافه حتقيق ًا املنوه عنه يف محضر استجوابه‪.‬‬\n              ‫‪ -2‬ما تضمنته اعترافه مبحضر سماع اقواله االولية املنوه عنها ‪.‬‬\n                                                    ‫‪ -3‬ما تضمنه محضر القبض املنوه ‪.‬‬\n                                                     ‫‪ -4‬ما تضمنه التقرير الكيميائي ‪.‬‬\n                                                  ‫‪ -5‬ما تضمنه محضر مطابقة املبلغ ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪-:‬‬\n      ‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة وفق ـ ًا للفقــرة (األولــى) مــن‬\n      ‫املــادة رقــم (‪ )38‬مــن نظــام مكافحــه املخــدرات املؤثــرات العقلية املشــار‬\n      ‫إليــه ‪ ،‬وإعمــال الفقــرة (األولــى )مــن املادة(‪)62‬مــن ذات النظــام بحقــه‬\n                                                                         ‫لقــاء مــا أســند إليــه‪.‬‬\n      ‫‪-2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبتــه وفقـ ًا للفقرة‬\n      ‫(األولــى) مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                                        ‫العقليــة‪.‬‬\n      ‫‪ -3‬مصــادرة الهاتــف اجلــوال العائــد للمذكــور املســتخدم يف اجلرميــة وهــو‬\n      ‫مــن نــوع نوكيــا يحمــل الرقــم املصنعــي (‪ )............‬وفقـ ًا للفقــرة (األولــى)‬\n                                               ‫مــن املــادة (‪ )53‬مــن النظــام املشــار إليــه ‪.‬‬\n      ‫‪ -4‬الغــاء الشــريحة ذات الرقــم (‪ ).....‬املســتخدمة يف عمليــة الترويــج‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حالــة صــدور احلكــم باملصــادرة‬\n      ‫وإبــاغ الشــركة مصــدرة الشــريحة بذلــك اســتنادا لتعميــم وزيــر‬\n                            ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n                      ‫‪ -5‬اجراء املقتضى الشرعي لقاء تعاطيه احلشيش املخدر ‪.‬‬\n\n\n‫‪197‬‬\n\f                 ‫‪ -6‬بعقوبة تعزيرية لقاء تستره على مصدر ما مت ترويجه ‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي‬\n‫العــام أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه صحيــح فأنــا‬\n‫ـخص‬‫اشــتريت القطعــة وتعاطيــت منهــا شــيئ ًا يســير ًا وبعتهــا علــى شـ ٍ‬\n‫آخــر هكــذا أجــاب ‪ ،‬وحيــث األمــر مــا ذكــر مــن الدعــوى واإلجابــة‬\n‫وحيــث اعتــرف املدعــى عليــه بدعــوى املدعــي العــام جــرى اإلطــاع‬\n‫علــى التقريــر الكيمــاوي الشــرعي املرفــق باملعاملــة حتــت لفــة رقــم‬\n‫(‪ )31‬وهــو صــادر مــن مركــز مراقبــة الســموم والكيميــاء الشــرعية‬\n‫رقــم (‪/44/2/6318‬ك) يف ‪1433/6/22‬ه ـ واملتضمــن إيجابيــة القطعــة‬\n                                                      ‫املضبوطــة ملــادة احلشــيش املخــدر‪.‬‬\n‫ـاء عليــه ثبــت لــدي إدانــة املدعــى عليــه ببيــع مــا وزنــه جرامني ونصف‬         ‫وبنـ ـ ً‬\n‫اجلــرام بقصــد الترويــج واالجتــار وحيازتــه لقطعــة حشــيش مخــدر مــن‬\n‫ذات النــوع غيــر معروفــة الــوزن بقصــد الترويــج والتعاطــي وتعاطيــه‬\n‫ا باملــادة رقــم‬\n                ‫للحشــيش املخــدر وحكمــت عليــه مبــا يلــي‪ -:‬أوالً‪ :‬عم ـ ً‬\n‫(‪ )38‬مــن نظــام مكافحــة املخــدرات املؤثــرات العقليــة واملــادة رقــم (‪)60‬‬\n‫مــن ذات النظــام والتــي أجــازت للقاضــي النــزول عــن احلــد األدنــى إذا‬\n‫أتــى بأســباب مقنعــة وحيــث ال توجــد ســابقة ترويــج علــى املدعــى عليــه‬\n‫والكميــة املروجــة قليلــة لــذا حكمــت بتعزيــر املدعــى عليــه بســجنه‬\n‫ســنة مــن تاريــخ إيقافــه وجلــده خمســن جلــدة دفع ـ ًة واحــد ًة وتغرميــه‬\n‫ألفــي ريــال تدفــع للخزينــة العامــة للدولــة‪ .‬ثانيـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت‬\n‫مبنعــه مــن الســفر إلــى خــارج اململكــة ملــدة ســنتني بعــد تنفيــذ العقوبــة‬\n‫ـاء علــى الفقــرة األولــى مــن املــادة رقــم (‪ )58‬مــن ذات النظــام‪.‬‬          ‫عليــه بنـ ً‬\n‫ثالثـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت بإلغــاء الشــريحة ذات الرقــم (‪ ).......‬املســتخدمة‬\n\n\n                                                                                                 ‫‪198‬‬\n\f      ‫يف عمليــة الترويــج وعــدم صرفهــا لنفــس املشــترك وإبــاغ الشــركة‬\n      ‫مصــدرة الشــريحة بذلــك‪ .‬رابع ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت مبصــادرة الهاتــف‬\n      ‫اجلــوال العائــد للمذكــور املســتخدم يف اجلرميــة وهــو مــن نــوع ‪ ......‬يحمــل‬\n      ‫الرقــم املصنعــي (‪ )............‬وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن‬\n      ‫ذات النظــام املشــار إليــه‪ .‬خامسـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬جلــده حــد اخلمــر ثمانــن‬\n      ‫جلــدة لقــاء تعاطيــه احلشــيش املخــدر‪ .‬سادس ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت بتغرميــه‬\n      ‫ألــف ريــال لقــاء تســتره علــى مصــدر مــا ضبــط‪ .‬وبــه حكم ــت ‪ ،‬وبعــرض‬\n      ‫احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه قناعتــه‬\n      ‫باحلكــم أمــا املدعــي العــام فطلــب االســتئناف مكتفيـ ًا بالئحــة اإلدعــاء‬\n      ‫عــن الالئحــة اإلعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/07/23‬هـ ــ‪..‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة اجلزائية‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33475473‬وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331360505‬وتاريــخ ‪ 1433/07/20‬ه ـ ففــي يــوم‬\n      ‫اإلثنــن املوافــق‪ 1433/11/29‬ه ـ افتتحــت اجللســة ثــم عــادت العاملــة مــن‬\n      ‫محكمــة االســتئناف برقــم ‪ 33454856‬يف ‪1433/11/15‬ه ـ واملتضمن‬\n      ‫التصديــق علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض رقــم‬\n      ‫‪ 332129313‬وتاريــخ ‪ 1433/12/1‬ه ـ ومشــفوعة املعاملــة اخلاصــة‬\n      ‫بدعــوى ‪ /‬املدعــي العــام ضــد ‪ ....... /‬واملنظــورة لــدى فضيلــة الشــيخ ‪/‬‬\n\n\n‫‪199‬‬\n\f‫‪ .........‬واملنتهيــة لديــه بالقــرار رقــم ‪ 33361642 /‬وتاريــخ ‪ 1433/7/3‬هـ‬\n‫وبعــد اإلطــاع علــى املعاملــة تبــن أنــه ســبق دراســة احلكــم واملصادقــة‬\n‫عليــه مــن قبــل الدائــرة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪200‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":193,"source_page_end":200,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d966c2c7377de9c2f94aac35631bf5f52e2f0c7651137dcdd72ab0e674b14fa3","normalized_text_hash":"d3d2ea6128a17e41fb555f5e82e2344ad4b07dd53cde5f82ad29fef9c1e8017b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p193-33361642"},{"id":"66ee9976-2502-5a17-b599-86d831d1b367","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -بيع احلبوب احملظورة -حيازة احلبوب احملظورة -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -تعزير بالسجن واجللد والغرامة -مصادرة مبلغ -مصادرة اجلوال املستخدم يف اجلرمية -إلغاء شريحة جوال مستخدمة يف اجلرمية .","document_number":"33464331","case_number":"33475860","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"مخدرات -بيع احلبوب احملظورة -حيازة احلبوب احملظورة -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -تعزير بالسجن واجللد والغرامة -مصادرة مبلغ -مصادرة اجلوال املستخدم يف اجلرمية -إلغاء شريحة جوال مستخدمة يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33464331 :‬تاريخه ‪1433/11/23 :‬هـ‬\n                         ‫رقم الدعوى ‪33475860 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3424078‬تاريخه‪1434/01/27 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬بيــع احلبــوب احملظــورة ‪ -‬حيــازة احلبــوب احملظــورة ‪ -‬ترويــج‬\n       ‫احلبــوب احملظــورة ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬تعزيــر بالســجن‬\n       ‫واجللــد والغرامــة ‪ -‬مصــادرة مبلــغ ‪ -‬مصــادرة اجلــوال املســتخدم يف‬\n                  ‫اجلرميــة ‪ -‬إلغــاء شــريحة جــوال مســتخدمة يف اجلرميــة ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                    ‫‪ -2‬املادة ‪ 53‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                    ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n       ‫دعــوى املدعــي العــام ضــد املدعــى عليــه ببيــع احلبــوب احملظــورة بقصــد‬\n       ‫الترويــج و التعاطــي و تعاطيــه لهــا و ترويجــه للحبــوب احملظــورة ‪ -‬وطلــب‬\n       ‫املدعــي العــام إثبــات مــا أســند إليــه و احلكــم عليــه بالســجن و اجللــد‬\n       ‫والغرامــة و مصــادرة املبلــغ املالــي املضبــوط معــه و الســيارة املســتخدمة‬\n       ‫يف اجلرميــة و مصــادرة هاتفــه اجلــوال املســتخدم يف اجلرميــة و إلغــاء اخلدمــة‬\n       ‫مــن شــريحته و عــدم صرفهــا مــرة أخــرى و منعــه مــن الســفر إلــى خــارج‬\n       ‫اململكــة‪ ،‬مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا أنــه يقــوم‬\n       ‫بترويــج احلبــوب احملظــورة فتــم االتصــال عليــه مــن أحــد املصــادر ومت‬\n\n‫‪201‬‬\n\f‫االتفــاق معــه علــى شــراء كميــة مــن احلبــوب و اســتعد بذلــك وحضــر‬\n‫املصــدر للمــكان املتفــق عليــه وحضــر املدعــى عليــه ومت االســتالم‬\n‫والتســليم بــن الطرفــن وصــدر التقريــر الكيميائــي بإيجابيــة العينــة‬\n‫املرســلة‪ ،‬إقــرار املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد‬\n‫والغرامــة و مصــادرة اجلــوال و إلغــاء الشــريحة اخلاصــة بــه املســتخدمني‬\n                 ‫يف اجلرميــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪ ....‬وتاريــخ ‪ .....‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ ....‬وتاريــخ ‪ ....‬ه ـ ففــي يــوم االثنــن املوافــق‪....‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا أدعــى املدعــي العــام ‪/‬‬\n‫‪...‬نيابــة عــن ‪.... /‬مبوجــب خطــاب التعميــد رقــك ‪ 24/6‬يف تاريــخ ‪......‬هـ ‪،‬‬\n‫‪ )33(............‬عامـ ًا ‪ ،‬ســعودي اجلنســية‪ ،‬مبوجــب ســجل مدنــي رقــم(‪)....‬‬\n‫املهنة‪/‬عســكري‪ ،‬موقــوف بســجون محافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقــم(‪ ).....‬وتاريــخ ‪.....‬ه ـ اســتنادا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫بتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة‪ .‬بتاريــخ ‪1433/5/20‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل‬\n‫أفــراد مكافحــة املخــدرات مبحافظــة جــدة بنــاء علــى إخباريــة أحــد‬\n‫املصــادر الســرية املتضمنــة ترويــج املدعــى عليــه للحبــوب احملظــورة‬\n‫علــى ســيارة مــن نــوع فــورد حتمــل اللوحــة رقــم (‪ ).....‬فتــم االتصــال علــى‬\n                                                          ‫جوالــه رقــم(‪ُ ).......‬‬\n‫وطلــب منــه شــراء حبــوب مؤثــرة عقليـ ًا مببلــغ مائتــن‬\n\n                                                                                        ‫‪202‬‬\n\f      ‫ريــال فوافــق وباملوقــع احملــدد حضــر املدعــى عليــه أعــاه بســيارته املنــوه‬\n      ‫عنهــا ونــزل منهــا وســلم للمتعــاون (‪)7‬ســبع حبــات واســتلم املبلــغ فتــم‬\n      ‫القبــض عليــه وضبــط املبلــغ املرقــم بجيبــه وضبــط معــه اجلــوال الــذي مت‬\n      ‫التنســيق عليــه واحلامــل للرقــم املصنعــي (‪ )..........‬وبتفتيــش ســيارته مت‬\n      ‫ضبــط بهــا(‪ )12‬اثنتــا عشــرة حبــة فتــم االنتقــال إلــى منزلــه وبتفتيشــه‬\n      ‫عثــر بغرفــة النــوم علــى خزانــه حديديــه بداخلهــا(‪ )836‬ثمامنائــة وســتة‬\n      ‫وثالثون حبة و مبلغ مالي وقدره (‪ )12703.5‬اثنا عشــر الفا وســبعمائة‬\n      ‫وثالثــة ريــاالت ونصــف الريــال كمــا ضبــط مســدس ربــع محشــو بأربــع‬\n      ‫طلقــات حيــة وأفــاد بــأن الســيارة عائــده لــه ولكنــه ســجلها باســم زوجته‬\n      ‫‪.‬وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )../...‬لعام‪1433‬ه ـ احتــواء‬\n      ‫العينــات (أ) و(ب) و(ج) مــن احلبــوب املضبوطــة واملرســلة للتحليــل علــى‬\n      ‫مــادة االمفيتامــن املؤثــرة عقلي ـ ًا املدرجــة باجلــدول رقــم (‪)2‬فئــة(ب)‬\n      ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وباســتجواب‬\n      ‫املدعــى عليه‪/‬أقــر ببيــع(‪ )7‬ســبع حبــات مؤثــرة عقليـ ًا مقابــل مائتــا ريــال‬\n      ‫و أن (‪)12‬االثنتــا عشــرة حبــة مــن ذات النــوع وكذلــك(‪ )836‬الثمامنائــة‬\n      ‫وســتة وثالثــون حبــة مــن ذات النــوع املضبوطــة مبنزلــه عائــده لــه بقصــد‬\n      ‫التعاطــي كمــا أقــر بتعاطيــه مــن ذات احلبــوب وترويجــه وتعاطيــه لنوعها‬\n      ‫ســابق ًا كمــا أقــر بــأن الســيارة عائــده لــه وقــام بتســجيلها باســم زوجتــه‬\n      ‫ومت فصل أوراق مســتقلة للســاح واالوراق ‪ .‬وأســفر التحقيق عن توجيه‬\n      ‫االتهــام إلــى املدعــى عليــه ببيــع (‪)7‬حبــات حتتــوي على مــادة االمفيتامني‬\n      ‫املؤثــرة عقليــا بقصــد االجتــار وحيــازة (‪ )848‬ثمامنائــة وثمانيــة وأربعــون‬\n      ‫حبــة مــن ذات النــوع بقصــد الترويــج والتعاطــي‪ ،‬وتعاطيــه منهــا وترويجه‬\n      ‫وتعاطيــه لنوعــه ســابق ًا املجـ ّـرم اســتنادا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن‬\n\n\n‫‪203‬‬\n\f‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫وباالطــاع علــى ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة عليــه‪ .‬وحيــث‬\n‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا مــن‬\n‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n                                                        ‫م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫واملعاقــب عليهــا اســتناد ًا للمادتــن (‪ )41.38‬مــع مراعــاة مــا ورد باملــادة‬\n‫(‪ )62‬مــن ذات النظــام لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n                                                          ‫عليــه بالعقوبتــن التاليتــن ‪:‬‬\n‫‪1‬ـ بالســجن واجللــد والغرامــة لقــاء مــا اســند إليــه اســتناد ًا للفقــرة (‪ )1‬مــع‬\n‫تشــديد العقوبــة عليــه وفقـ ًا للحالــة(ج) مــن الفقــرة ‪2‬مــن املــادة (‪ )38‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وتعميــم وزيــر الداخليــة‬\n    ‫رقــم ‪2/8346/4/5/1‬ش وتاريــخ ‪1427/2/8‬ه ـ لقــاء ترويــج احلبــوب‪.‬‬\n‫‪2‬ـ مصــادرة املبلــغ املالــي املضبــوط معــه وقــدره (‪ )12703‬اثنــا عشــر‬\n‫ألفـ ًا وســبعمائة وثالثــة ريــاالت ونصــف الريــال والســيارة املســتخدمة يف‬\n‫ارتــكاب اجلرميــة مــن نــوع فــورد فضيــة اللــون رقــم لوحتهــا (‪ ).....‬وهاتفــه‬\n‫اجلــوال املســتخدم يف ارتــكاب اجلرميــة ذي الرقــم املصنعــي (‪)............‬‬\n‫اســتنادا للفقــرة (‪ )2.1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه وإلغــاء اخلدمــة عــن شــريحة اجلــوال وعــدم صرفهــا ملــن أســاء‬\n‫اســتخدامها اســتناد ًا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n                                      ‫رقــم (‪ )9798‬وتاريــخ ‪ 9‬ــ‪1428/2/10‬ه ـ ‪.‬‬\n‫‪3‬ـ منعــه مــن الســفر الــى خــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتــه‬\n‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n\n\n                                                                                            ‫‪204‬‬\n\f      ‫واملؤثــرات العقليــة هــذه دعــواي واســاله اجلــواب وبســؤال املدعــى‬\n      ‫عليــه عــن الدعــوى قــال صحيــح أننــي قمــت ببيــع ‪ 7‬حبــات مــن حبــوب‬\n      ‫اإلمفتامــن احملظــورة وحــزت ‪ 848‬ثمامنائــة وثمانيــة وأربعــون حبــة مــن‬\n      ‫ذات النــوع بقصــد الترويــج والتعاطــي وتعاطيــه منهــا وانوعهــا يف الســابق‬\n      ‫وأن املبلــغ املذكــور البالــغ قــدره ‪ 12703‬ريــال أثنــا عشــر ألف وســبعمائة‬\n      ‫وثالثــة ريــال هــو لــي اكتســبته مــن الترويــج وأن الســيارة الفــورد موديــل‬\n      ‫‪99‬م والتــي ضبطــت فيهــا احلبــوب املخــدرة والتــي كنــت أقودهــا هــي‬\n      ‫ليســت لــي وإمنــا لزوجتــي ‪...............‬وأن الهاتــف اجلــوال مــع شــريحته‬\n      ‫املذكــور يعــود لــي هــذه هــي احلقيقــة وبعــرض ذلــك علــى املدعــي العــام‬\n      ‫بإمــكان الرجــوع إلــى اســتمارة الســيارة املذكــورة يف الدعــوى ملعرفــة‬\n      ‫مــن تعــود الســيارة إليــه وأطلــب إمهالــي لذلــك حــرر يف ‪......‬ه ـ ‪ .‬ويف يــوم‬\n      ‫األربعــاء املوافــق ‪.....‬ه ـ حضــر املدعــي العــام وحضــر حلضــوره الســجني‬\n      ‫املذكــور وقــد جــرى االطــاع علــى اســتمارة الســيارة املشــار إليهمــا‬\n      ‫أعــاه واملطلــوب مصادرتهــا يف الدعــوى فوجــدت أنهــا حتتــوي الرقــم‬\n      ‫املشــار إليــه أعــاه وهــي باســم املــرأة ‪ ................ /‬وأرفــق صــورة مــن‬\n      ‫االســتمارة املذكــورة يف املعاملــة وبعــرض ذلــك علــى املدعــي العــام‬\n      ‫قــال أطلــب إجــراء الوجــه الشــرعي وبالرجــوع إلــى أوراق املعاملــة وجــد‬\n      ‫التقريــر الكيميائــي الشــرعي املشــار إلــى رقمــه ومضمونــة أعــاه ولــم‬\n      ‫يعثــر لــه علــى ســوابق مســجلة وعليــه وحيــث احلــال مــا ذكــر مــن دعــوى‬\n      ‫املدعــي العــام ضــد املذكــور وبطلــب مجازاتــه وبعــد التأمــل واالطــاع‬\n      ‫ولكــون االعتــراف ســيد األدلــة فقــد ثبــت لــدي إدانــة املدعــى عليــه فيمــا‬\n      ‫نســب إليــه مــن الدعــوى أعــاه وهــي بيــع ســبع حبــات مــن احلبــوب املؤثــرة‬\n      ‫عقلي ـ ًا بقصــد اإلجتــار وحيــازة ثمامنائــة وثمانيــة وأربعــن حبــة مــن ذات‬\n\n\n‫‪205‬‬\n\f‫النــوع بقصــد الترويــج والتعاطــي وتعاطيــه منهــا وترويجــه وتعاطيه لنوعه‬\n‫ســابق ًا واســتخدامه للجــوال مــع شــريحته وان املبلــغ اعــاه مكتســب‬\n‫مــن الترويــج يف اجلرميــة وحكمــت أو ًال ‪ /‬تعزيــر املدعــى عليــه لبيعــه‬\n‫احلبــوب املذكــورة وحيازتــه لهــا بقصــد التعاطــي والترويــج بالســجن‬\n‫خمــس ســنوات مــن تاريــخ دخولــه الســجن وجلــده خمســمائة جلــدة علــى‬\n‫عشــر دفعــات كل دفعــة خمســون جلــده بــن الدفعــة والتــي تليهــا خمســة‬\n‫عشــر يوم ـ ًا وغرامــة ماليــة قدرهــا ألــف ريــال إســتناد ًا للمــادة (‪ )38‬مــن‬\n‫نظــام املخــدرات وهــذه العقوبــة شــاملة التعاطــي للحبــوب لنوعهــا مــن‬\n‫الســابق ‪ .‬ثاني ـ ًا ‪ /‬مصــادرة املبلــغ الشــارة إليــه أعــاه ومصــادرة اجلــوال‬\n‫مــع إلغــاء شــريحته ومنــع صرفهــا لــه مــرة أخــرى إســتناد ًا للمــادة (‪)53‬‬\n‫مــن ذات النظــام ‪ .‬ثالثـ ًا ‪ /‬منــع املذكــور مــن الســفر خــارج اململكــة بعــد‬\n‫إنتهــاء محكوميتــه ملــدة خمــس ســنوات إســتناد ًا للمــادة (‪ )56‬مــن ذات‬\n‫النظــام ‪ .‬رابع ـ ًا ‪ /‬صرفــت النظــر عــن طلــب املدعــي مصــادرة الســيارة‬\n‫املذكــورة واملســتخدمة يف اجلرميــة كونهــا ليســت للمذكــور املدعــى‬\n‫عليــه وبعرضــه عليهمــا قــرر املدعــى عليــه قناعتــه بذلــك وأبــدى املدعــي‬\n‫العــام إعتراضــه بالئحــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/01‬ه ـ ‪ .‬احلمــد‬\n‫هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى منــا‬\n‫نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بجــدة املســاعد رقــم وتاريــخ ‪........‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة الشــيخ‪ ......./‬القاضــي باحملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة رقــم ‪ ........‬وتاريــخ ‪.......‬ه ـ احملكــوم فيــه مبــا‬\n\n\n                                                                                      ‫‪206‬‬\n\f      ‫دون بباطــن القــرار املتضمــن دعــوى املدعــى العــام ضــد‪ ......./‬ســعودي‬\n      ‫اجلنســية املتهــم يف مخــدرات وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل‬\n                            ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪،،،،‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":201,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ecf8874e6e2ef18a8d51c0abd280f88ef6f32baec493902b21ff5cb9d4cb9e6","normalized_text_hash":"e0c4368ee336b9458d63a35b545e3dac1ffdfeb57d21d74059bb65deb90792c5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p201-33464331"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6be87d49-9f4e-5391-9aee-ec55d6a7409a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تقرير الطب النفسي -صك والية -صرف النظر عن طلب املدعي العام .","document_number":"3432274","case_number":"33385832","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/06","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تقرير الطب النفسي -صك والية -صرف النظر عن طلب املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3432274 :‬تاريخه ‪1434/02/06 :‬هـ‬\n                        ‫رقم الدعوى ‪33385832 :‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34190060:‬تاريخه‪1434/4/16 :‬هـ‬\n\n\n       ‫مخــدرات‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تقريــر الطــب النفســي ‪ -‬صــك‬\n                           ‫واليــة ‪ -‬صــرف النظــر عــن طلــب املدعــي العــام ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم « رفــع القلــم عــن ثالثــة ‪ ،‬عــن النائــم‬\n       ‫حتــى يســتيقظ ‪ ،‬وعــن الصغيــر حتــى يكبــر ‪ ،‬وعــن املجنــون حتى يفيق»‬\n                  ‫رواه اإلمــام أحمــد وأبــو داود والترمــذي وقــال حديــث حســن ‪.‬‬\n       ‫‪ -2‬منــاط التكليــف يف الشــريعة ‪ :‬البلــوغ والعقــل ‪ ،‬ومــا هيــة العقــل‬\n       ‫هــو مــا يــدرك بــه اإلنســان األشــياء علــى حقيقتهــا ‪ .‬انظــر مجمــوع‬\n                                                ‫الفتــاوى البــن تيميــة (‪. )345/10‬‬\n       ‫العقــاء علــى أن شــرط‬ ‫‪ -3‬قــال اآلمــدي رحمــه اهلل يف اإلحــكام ‪ ( :‬اتفــق ُ‬\n       ‫ا فاهمـ ًا للتكليــف ألن التكليــف خطــاب ‪ ،‬وخطاب‬       ‫املكلــف أن يكــون عاقـ ً‬\n                                                  ‫مــن ال عقــل لــه وال فهــم محــال ) ‪.‬‬\n       ‫‪ -4‬قــال ابــن قدامــة يف املغنــى (‪ ( : )109/5‬فأمــا الطفــل املجنــون‬\n       ‫واملبرســم والنائــم واملغمــى عليــه فــا يصــح إقرارهــم ال نعلــم يف هــذا‬\n                                                                             ‫خالف ـ ًا ) ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f‫ادعــى املدعــى العــام ضــد املدعــى عليــه ببيــع عــدد خمــس حبــات مــن‬\n‫احلبــوب املنبهــة احملظــورة بقصــد االجتــار حيــث توفــرت معلومــات لــدى‬\n‫مكافحــة املخــدرات مــن أحــد مصادرهــا الســرية عــن قيــام املدعى عليه‬\n‫بترويــج احلبــوب احملظــورة ومت تزويــد املصــدر باملبلــغ املرقــم ويف املــكان‬\n‫احملــدد حضــر املدعــى عليــه بســيارته ومتــت عمليــة االســتالم والتســليم‬\n‫أمــام أنظــار الفــرد املرافــق ومت القبــض علــى املدعــى عليــه وطلــب املدعي‬\n‫العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n‫وإعــادة املبلــغ احلكومــي املرقــم ومصــادرة الســيارة واجلــوال‪ .‬ظهــرت‬\n‫علــى املدعــى عليــه آثــار تخلــف عقلــي وحضــر وليــه وأبــرز صــك واليــة‬\n‫علــى املدعــى عليــه وصــدر تقريريــن مــن مستشــفى الصحــة النفســية‬\n‫يفيــدان بتخلــف املدعــى عليــه عقلي ـ ًا ( تخلــف متوســط) ‪ ،‬بنــاء علــى‬\n‫ماتقــدم حكمــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي العــام‬\n                                ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم وتاريــخ ‪1433/06/08‬ه ـ املقيــدة باحملكمة برقم‬\n‫وتاريــخ ‪ 1433/06/08‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/05‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪ /‬وادعــى‬\n‫علــى احلاضــر معــه ‪ /‬ســعودي اجلنســية مبوجــب بالســجل املدنــي رقــم ()‬\n\n                                                                                     ‫‪158‬‬\n\f      ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود‬\n      ‫الشــمالية أدعــي علــى املذكــور أعــاه فإنــه بتاريــخ ‪1433 /4/17‬‬\n      ‫وبنــاء علــى املعلومــات املتوفــرة لــدى مكافحــة املخــدرات مــن أحــد‬\n      ‫املصــادر الســرية عــن قيــام املدعــى عليــه ‪ /‬بترويــج احلبــوب احملظــورة‬\n      ‫واســتعداده اإلطاحــة بــه فتــم التنســيق مــع املصــدر واالتصــال باملــروج‬\n      ‫ـاء وكانــت‬  ‫علــى جوالــه رقــم (‪ ).....‬يف متــام الســاعة الثامنــة والربــع مسـ ً‬\n      ‫املكاملــة علــى مســمع مــن الفــرد املرافــق للمصــدر حيــث مت االتفــاق علــى‬\n      ‫حتديــد موقــع ملقابلــة املــروج فيــه الســتالم األغــراض فتــم االنتقــال إلــى‬\n      ‫املوقــع املتفــق عليــه بالقــرب مــن مدرســة بحــي ‪ ....‬بعــد تفتيــش املصــدر‬\n      ‫وســيارته وإعطــاءه املبلــغ احلكومــي املرقــم وقــدره مائتــي ريــال وعنــد‬\n      ‫الوصــول إلــى املوقــع يف متــام الســاعة الثامنــة وخمــس وعشــرون دقيقــة‬\n      ‫ـاء واالنتظــار وبعــد حوالــي دقيقــة حضــر املدعــى عليــه‬            ‫(‪ )8.25‬مسـ ً‬\n      ‫علــى ســيارته مــن نــوع ‪ ....‬حتمــل لوحــة ســعودية رقــم (‪ )....‬حيــث قــام‬\n      ‫بالســام علــى املصــدر وطلــب املصــدر منــه حبــوب مببلــغ مائتــي ريــال‬\n      ‫فوافــق وقــام بإعطــاء املصــدر عــدد (‪ )5‬خمــس حبــات يشــتبه أن تكــون‬\n      ‫مــن احلبــوب املنبهــة احملظــورة وقــام بتســليمه املبلــغ احلكومــي املرقــم‬\n      ‫ثــم قــام املصــدر بالرجــوع وتســليم احلبــوب إلــى العنصــر املرافــق لــه‬\n      ‫وكانــت عمليــة االســتالم والتســليم أمــام أنظــار الفــرد املرافــق ويف متــام‬\n      ‫ـاء مــن نفــس اليــوم مت القبــض علــى املدعــى عليــه‬    ‫الســاعة التاســعة مسـ ً‬\n      ‫وبتفتيشــه عثــر معــه علــى اجلــوال املســتخدم يف اجلرميــة ويحمــل الرقــم‬\n      ‫التسلســلي (‪ ).....‬وبســماع أقوالــه اقــر ببيــع احلبــوب املنبهــة احملظــورة‬\n      ‫وإيصالهــا ورفــض التبصيــم علــى أقوالــه وباســتجوابه أقــر بتلقيــه‬\n      ‫اتصــال مــن شــخص يطلــب منــه حبــوب ثــم ذهــب إلــى املوقــع املتفــق عليــه‬\n\n\n‫‪159‬‬\n\f‫للقــاء املتصــل بالقــرب مــن مدرســة ‪ ....‬والتفاهــم معــه لتكــرار اتصالــه‬\n‫عليــه وقابلــه وســلم عليــه ومشــى رافض ـ ًا أخــذ أو بيــع احلبــوب كمــا‬\n‫اقــر بعائديــة اجلــوال رقــم (‪ ).....‬لــه وقــد اثبــت التقريــر الكيميائــي‬\n‫الشــرعي الصــادر مــن مركــز الســموم بصحــة تبــوك برقــم (‪/1138‬م‬\n‫س ت ) لعــام ‪1433‬ه ـ ايجابيــة العينــة املرســلة ملــادة االمفيتامــن املنبهــة‬\n‫احملظــورة وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة املنــوه عنهــا يف‬\n‫اجلــدول الثانــي فئــة (ب) بتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n‫رقــم ‪ 89400/19‬وتاريــخ ‪1426/10/25‬ه ـ كمــا صــدر التقريــر الطبــي‬\n‫النفســي اجلنائــي رقــم (‪ )35/347‬وتاريــخ ‪1433/5/18‬ه ـ الصــادر مــن‬\n‫مستشــفى الصحــة النفســية بالطائــف املتضمــن (تخفيــف املســؤولية‬\n‫اجلنائيــة يف قضيتــه احلاليــة لوجــود التخلــف العقلــي ومــا يصاحبــه مــن‬\n‫ســوء احلكــم علــى األمــور وضعــف تقديــر عواقــب األمــور) وقــد انتهــى‬\n‫التحقيــق إلــى اتهــام‪ ......‬ببيــع عــدد خمــس حبــات مــن احلبــوب املنبهــة‬\n‫احملظــورة بقصــد االجتــار وبالبحــث عــن ســوابقه تبــن خلــو ســجله‬\n‫منهــا وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم شــرعا ومجــرم‬\n‫نظامــا بنــص الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه‬\n‫باالتــي‪ -1 :‬الســجن واجللــد والغرامــة وفقــا للمــادة (‪ )38‬الفقــرة (‪ )1‬مــن‬\n‫نظــام مكافحــة املخــدرات مــع مراعــاة مــا ورد بالتقريــر الطبــي النفســي‬\n‫اجلنائــي املرفــق لفــة رقــم (‪ -2 )61‬منــع مــن الســفر خــارج اململكــة وفقــا‬\n‫للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام نفســه ‪ -3‬إلــزام املتهــم بدفــع‬\n‫املبلــغ احلكومــي املرقــم وقــدرة (‪ )200‬مائتــي ريــال وفقـ ًا لبرقيــة صاحب‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n      ‫رقــم ‪ 65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ ‪ -4‬مصــادرة‬\n      ‫الســيارة مــن نــوع ‪ ....‬موديــل (‪ )1993‬حتمــل اللوحــة رقــم (‪ ).....‬واجلــوال‬\n      ‫املســتخدم يف عمليــة الترويــج مــن نــوع ‪ ....‬ابيــض يحمــل الرقــم التسلســلي‬\n      ‫() وعــدم صــرف شــريحة اجلــوال رقــم (‪ )..............‬للمتهــم املذكــور وفقــا‬\n      ‫للمــادة (‪ )53‬الفقــرة األولــى مــن النظــام نفســه هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه عــن الدعــوى فلــم يتجــاوب وظهــر لــي مــن حالــه بــأن‬\n      ‫فيــه تخلــف عقلــي كمــا أنــه يجــاوب بإجابــات غيــر مطابقــة للســؤال‬\n      ‫وبتكــرار ســؤالي لــه عــن الدعــوى بكــى بــكاء شــديد وقــال ال لعبــوا‬\n      ‫علــي وأنــا تعبــت يف التوقيــف أوريــد اخلــروج وبــكالم غيــر مفهــوم كمــا‬\n      ‫ظهــر لــي بــأن املدعــى عليــه بحاجــة للمســاعدة يف بعــض أمــوره لكونــه‬\n      ‫قصيــر القامــة جــد ًا كمــا حضــر يف نفــس اجللســة شــقيق املدعــى عليــه‬\n      ‫وهــو ســعودي بالســجل املدنــي رقــم حيــث أفــاد بــأن شــقيقه ال يحســن‬\n      ‫التصــرف يف بعــض أمــوره ولديــه تخلــف عقلــي وأنــا الولــي الشــرعي عنــه‬\n      ‫وأقــوم برعايتــه وإدارة شــؤون حياتــه نظــر ًا لكونــه يعانــي مــن تخلــف‬\n      ‫عقلــي متوســط وغيــر قــادر علــى حتمــل املســؤولية وإدارة شــؤون حياتــه‬\n      ‫وذلــك حســب صــك الواليــة الصــادر مــن هــذه احملكمــة برقــم ‪3/41‬‬\n      ‫يف ‪1425/4/20‬ه ـ أفــاد ثــم جــرى منــي اإلطــاع علــى التقريــر الطبــي‬\n      ‫النفســي اجلنائــي الصــادر مــن مستشــفى الصحــة النفســية بالطائــف‬\n      ‫واملــدون علــى اللفــة رقــم ‪ 23‬واملتضمــن فيــه بأنــه مــن خــال الفحــص‬\n      ‫العقلــي كان هادئ ـ ًا وال ينظــر بعــن الفاحــص وكان قصيــر القامــة‬\n      ‫ويعانــي مــن ضعــف واضــح بالســمع والنطــق وكالم غيــر مفهــوم يف‬\n      ‫بعــض األحيــان ومزاجــه متبلــد وغيــر متفاعــل ثــم بعــد ذلــك قــررت اللجنة‬\n\n\n‫‪161‬‬\n\f‫بــأن املذكــور يعــود إلــى مرجعــه بــدون عــاج عقلــي ونظــر ًا ملــا يعانيــة‬\n‫املذكــور مــن تخلــف عقلــي ومــا يصاحبــه مــن ســوء يف احلكــم علــى‬\n‫األمــور وتقديــر عواقــب األفعــال كونــه مــن الســهولة ميكــن اســتغالله‬\n‫والتغريــر بــه مــن قبــل اآلخريــن وتــرى اللجنــة بــأن بعــض مــن املســؤولية‬\n‫اجلنائيــة ويأخــذ التعهــد الــازم علــى ذويــه باحملافظــة عليــه حتــى ال‬\n‫يتكــرر مــا بــدر منــه يف قضيتــه اجلاليــة وهــو بتوقيــع الدكتــور ورئيــس‬\n‫اللجنــة الدكتــور كمــا مت اإلطــاع علــى تقريــر الطبــي النفســي اجلنائــي‬\n‫الصــادر مــن مستشــفى الصحــة النفســية بالطائــف برقــم ‪ 35/347‬يف‬\n‫‪1433/5/18‬ه ـ واملــدون علــى اللفــة رقــم ‪ 61‬واملتضمــن فيــه بــأن اللجنــة‬\n‫الطبيــة تقــرر بتخفيــف املســؤولية اجلنائيــة يف قضيتــه احلاليــة لوجــود‬\n‫التخلــف العقلــي ومــا يصاحبــه مــن ســوء احلكــم علــى األمــور وضعــف‬\n‫تقديــر عواقــب األمــور وتشــدد اللجنــة علــى أخــذ التعهــدات الالزمــة‬\n‫علــى وليــه الشــرعي باحملافظــة عليــه حتــى ال يتكــرر منــه مثــل تلــك‬\n‫األفعــال مــرة أخــرى وهــو بتوقيــع د‪ /‬و د‪ /‬ورئيــس اللجنــة د‪ /‬وأيض ـ ًا مت‬\n‫اإلطــاع علــى صــك الواليــة املذكــور أعــاه واملــدون علــى اللفــة رقــم‬\n‫ـاء‬\n‫‪ 11‬واملتضمــن فيــه وفــق مــا ذكــره شــقيق املدعــى عليــه يف إفادتــه فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى ومــا قــرره ولــي املدعــى عليــه الشــرعي وبعــد‬\n‫اإلطــاع علــى التقريريــن الطبيــن النفســيني املذكــوران أعــاه ومبــا أن‬\n‫املدعــى عليــه ال يحســن التصــرف يف أمــوره ولديــه تخلــف عقلــي كمــا‬\n‫ورد يف التقاريــر الطبيــة ومبــا أنــه أيضـ ًا غيــر قــادر علــى حتمــل املســؤولية‬\n‫وإدارة شــؤون حياتــه ونظــر ًا إلقامــة شــقيقه ولي ـ ًا عليــه يقــوم برعايتــه‬\n‫وإدارة شــؤونه وبعــد اإلطــاع علــى صــك الواليــة املذكــور أعــاه ولقولــه‬\n‫صلــى اهلل عليــه وســلم كمــا يف احلديــث [ رفــع القلــم عــن ثالثــة عــن‬\n\n\n                                                                                        ‫‪162‬‬\n\f      ‫النائــم حتــى يســتيقظ وعــن الصغيــر حتــى يكبــر وعــن املجنــون حتــى‬\n      ‫يفيــق ] رواه األمــام أحمــد وأبــو داود والترمــذي وقــال حديــث حســن ومبــا‬\n      ‫أن منــاط تكليــف اإلنســان يف الشــريعة اثنــان وهمــا البلــوغ والعقــل ومبــا‬\n      ‫أن مــا هبــة العقــل هــو مــا يــدرك بــه اإلنســان األشــياء علــى حقيقتهــا [‬\n      ‫ينظــر مجمــوع فتــاوي ابــن تيميــة ‪ ]345/10‬وقــال األمــدي رحمــة اهلل يف‬\n      ‫ا‬\n      ‫اإلحــكام [ اتفــق العقــاء علــى أن شــرط املكلــف أن يكــون عاق ـ ً‬\n      ‫فاهم ـ ًا للتكليــف ألن التكليــف خطــاب مــا وخطــاب مــن ال عقــل لــه‬\n      ‫وال فهــم محــال ] ومبــا أن صحــة التكليــف مبنيــة علــى العقــل الــذي‬\n      ‫هــو آلــة القــدرة ونظــر ًا ألن فاقــد العقــل معــدوم األهليــة ألنــه ال يعــرف‬\n      ‫مصلحتــه مــن ضدهــا ومبــا أن املدعــى عليــه ناقــص العقــل وال يفــرق‬\n      ‫بــن احلــال وال احلــرام وال يعــي خطــورة املخــدرات وضررهــا كمــا‬\n      ‫أنــه غيــر مــدرك لعواقــب األمــور واألفعــال وتقديرهــا ممــا يســهل علــى‬\n      ‫ضعــاف النفــوس مــن املروجــن اســتغالله والتغريــر بــه وقــال ابــن قدامــة‬\n      ‫يف املغنــي ‪ [ 109/5‬فأمــا الطفــل واملجنــون واملبرســم والنائــم واملغمــى‬\n      ‫عليــه فــا يصــح إقرارهــم ال نعلــم يف هــذا خالفـ ًا ] لــذا وجلميــع مــا تقــدم‬\n      ‫فلــم يثبــت لــدي إدانــة املدعــى عليــه ‪ ....‬ببيــع خمــس حبــات مــن احلبــوب‬\n      ‫احملظــورة بقصــد االجتــار ورددت طلبــات املدعــي العــام واملتعلقــة‬\n      ‫بتطبيــق املــواد ‪38‬و ‪56‬و‪ 53‬مــن نظــام مكافحــة املخــدرات بحــق املدعــى‬\n      ‫عليــه كمــال مضحــي لعــدم أهليتــه شــرع ًا وأيضـ ًا رددت دعــوى املدعــي‬\n      ‫العــام بخصــوص املطالبــة بإلــزام املدعــى عليــه بإعــادة املبلــغ احلكومــي‬\n      ‫وكذلــك مصــادرة ســيارته وجوالــه وشــريحته واملذكــورة جميعـ ًا أعــاه‬\n      ‫لعــدم أهليتــه املعتبــرة شــرع ًا و أوصيــة بأخــذ التعهــد الــازم علــى وليــه‬\n      ‫الشــرعي باملتابعــة الشــديدة علــى املدعــى عليــه واحملافظــة عليــه حتــى ال‬\n\n\n‫‪163‬‬\n\f‫يســتغل مــن قبــل اآلخريــن بهــذا حكمــت وبعرضــه علــى املدعــي العــام‬\n‫قــرر املعارضــة علــى احلكــم بالئحــة اعتراضيــة وطلب التمييــز ويف نفس‬\n‫اليــوم جــرى تســليمه صــورة مــن احلكــم لالعتــراض عليــه و أفهــم بــأن‬\n‫مــدة االعتــراض ثالثــون يومـ ًا تبــدأ مــن هــذا اليــوم وإذا مضــت املــدة ولــم‬\n‫يعتــرض ســقط حقــه يف التمييــز وترفــع املعاملــة حملكمــة االســتئناف‬\n‫بــدون الئحــة خــال خمســة وأربعــن يوم ـ ًا مــن تاريــخ هــذا اليــوم ولــه‬\n‫املراجعــة خــال املهلــة واملــدة النظاميــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل على‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ‬\n‫ـاء علــى ورود الالئحــة االعتراضيــة‬       ‫افتتحــت اجللســة الســاعة ‪ 10.00‬بنـ ً‬\n‫علــى هــذا احلكــم واملقدمــة مــن املدعي العام واملقيــدة برقم ‪34617358‬‬\n‫يف ‪1434/03/10‬ه ـ وبإطالعــي عليهــا لــم أجــد فيهــا مــا يؤثــر علــى مــا‬\n‫حكمــت بــه أو يدعــو للعــدول عنــه وقــررت رفــع املعاملــة مــع القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة حملكمــة االســتئناف باجلــوف‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪ 1434/03/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ....‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــه مبحكمــة االســتئناف مبنطقــة اجلــوف‬\n‫علــى املعاملــة الــواردة مــن احملكمــة العامــه بعرعــر برقــم وتاريــخ‬\n‫‪1434/3/24‬ه ـ املرفــق بهــا القــرار الصادر من فضيلة الشــيخ‪ /‬املســجل‬\n‫برقــم يف‪1434/2/6‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ /‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــرر املصادقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى ألــه‬\n                                                                ‫وصحبــه وســلم‪..‬‬\n                                                                                       ‫‪164‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":157,"source_page_end":164,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"561948258e1eb5182b83ac502d75f0743ced4dd9b727f0ffeb99182960f844f2","normalized_text_hash":"ebf6076ae57c80f80dd41d23003c11d7ad3eb2bfd344c0b8946ad8ecfc908eef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p157-3432274"},{"id":"94e32d6d-f989-5add-9170-550768fced4d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر- الوساطة يف ترويج احلشيش املخدر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد والغرامة واملنع من السفر -تعزير باملصادرة -إقامة حد املسكر.","document_number":"33357665","case_number":"33422213","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/27","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر- الوساطة يف ترويج احلشيش املخدر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد والغرامة واملنع من السفر -تعزير باملصادرة -إقامة حد املسكر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33357665:‬تاريخه ‪1434/7/27:‬هـ‬\n                       ‫رقم الدعوى ‪33422213:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪/34324474‬ج‪/1‬أ تاريخه‪1434/9/22 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر‪ -‬تعاطــي احلشــيش املخــدر‪-‬‬\n      ‫الوســاطة يف ترويــج احلشــيش املخــدر‪ -‬إقــرار ‪ -‬ظــروف مخففــة‬\n      ‫للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‪ -‬تعزيــر‬\n                                                    ‫باملصــادرة‪ -‬إقامــة حــد املســكر‪.‬‬\n\n\n\n\n                       ‫‪ -1‬قوله صلى اهلل عليه وسلم ( كل مسكر حرام ) ‪.‬‬\n                ‫‪ -2‬قوله صلى اهلل عليه وسلم ( من شرب اخلمر فاجلدوه )‪.‬‬\n         ‫‪ -3‬املادة ‪ 56-53-38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليهمــا بتوجيــه االتهــام لــأول بترويــج‬\n      ‫احلشــيش املخــدر وتعاطيــه وتوســط الثانــي يف ترويــج وتعاطــي احلشــيش‬\n      ‫املخــدر‪ ،‬وطلــب املدعــى العــام إثبــات مــا أســند إليهمــا واحلكــم عليهمــا‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة جهــازي جــوال‬\n      ‫للمدعــى عليــه األول الســتخدامها بعمليــة الترويــج وإلغــاء الشــريحتني‬\n      ‫وإعــادة املبلــغ املرقــم ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليهمــا‬\n      ‫بعــد ورود بــاغ عــن املدعــى عليــه الثانــي يقــوم بالتوســط يف ترويــج‬\n      ‫احلشــيش املخــدر ومت التنســيق معــه عــن طريــق أحــد املصــادر لشــراء‬\n\n‫‪165‬‬\n\f‫احلشــيش وتســلم املدعــى عليــه الثانــي احلشــيش مــن املدعــى عليــه‬\n‫األول‪ ،‬اعتــراف املدعــى عليهمــا وثبــوت إدانتهمــا ‪ ،‬بنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بإقامــة حــد املســكر علــى املدعــى عليهمــا وتعزيــر‬\n‫املدعــى عليهمــا بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة‬\n‫وصــدق احلكــم مــن محكمة‬        ‫اجلــوال والشــريحة املســتخدمان يف اجلرميــة ُ‬\n                                                                   ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .........‬القاضــي باحملكمــة العامــة باجلبيــل وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا برقــم (‪ )33422213‬وتاريــخ ‪1433/6/23‬ه ـ واملقيــدة باحملكمــة‬\n‫برقــم (‪ )331183981‬وتاريــخ ‪1433/6/23‬ه ـ ويف يــوم االحــد املوافــق‬\n‫‪433/6/29‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر والنصــف وفيهــا‬\n‫حضــر املدعــي العــام بدائــرة التحقيــق واإلدعــاء العــام باجلبيــل ‪......... /‬‬\n‫واملدعــى عليــه االول ‪ .............‬ســعودي بالســجل املدنــي رقــم (‪).......‬‬\n‫واملدعــى عليــه الثانــي ‪ .........../‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬وادعــى املدعــي العــام قائــا يف دعــواه بصفتــي مدعيــا عاما‬\n‫بدائــرة التحقيــق واإلدعــاء العــام مبحافظــة اجلبيــل أدعــي علــى كل مــن‬\n                                                                      ‫املواطنــن ‪-:‬‬\n‫‪ ........ -1‬مبوجــب الســجل املدنــي رقــم (‪ ).....‬البالــغ مــن العمــر(‪ )18‬عامـ ًا‬\n‫موقــوف لــدى ســجن محافظــة اجلبيــل مبوجــب مذكــرة التوقيــف رقــم‬\n                            ‫(‪ 1252/4/3/15‬س ب) وتاريــخ ‪1433/5/25‬هــ‪.‬‬\n‫‪ ............ -2‬مبوجــب الســجل املدنــي رقــم (‪ )........‬البالــغ مــن العمــر(‪)19‬‬\n\n                                                                                       ‫‪166‬‬\n\f      ‫عامـ ًا موقــوف لــدى ســجن محافظــة اجلبيــل مبوجــب مذكــرة التوقيــف‬\n                          ‫رقــم (‪ 1253/4/3/15‬س ب) وتاريــخ ‪1433/5/25‬هــ‪.‬‬\n      ‫حيــث أنــه بتاريــخ ‪1433/5/22‬ه ـ وردت معلومــات ملكافحــة املخــدرات‬\n      ‫مبحافظــة اجلبيــل مــن أحــد مصادرهــا الســرية عــن قيــام املدعــى عليــه‬\n      ‫الثانــي (‪ )....‬بالتوســط يف ترويــج احلشــيش املخــدر وقــد أبــدى املصــدر‬\n      ‫اســتعداده لإلطاحــة بــه باجلــرم املشــهود ‪ ،‬عليــه وعنــد الســاعة (‪)8:00‬‬\n      ‫ـاء بالتاريــخ أعــاه مت متكينــه مــن االتصــال بالوســيط علــى‬  ‫الثامنــة مسـ ً‬\n      ‫جوالــه رقــم (‪ ).....‬حيــث قــال املصــدر ‪( :‬بغيــت حشــيش) فقــال الوســيط‬\n      ‫(مبائتــن وخمســن) فقــال املصــدر ‪( :‬إيــه إيــه مبائتــن وخمســن) علمـ ًا‬\n      ‫بــأن املكاملــة كانــت علــى مســمع مــن املــازم ‪ ...... /‬والعريــف ‪...... /‬‬\n      ‫عليــه مت تكليــف املــازم (‪ )....‬بتمثيــل دور املشــتري ويرافقــه املصــدر‬\n      ‫ـراء للذمــة ومت االنتقــال للقــاء الوســيط علــى‬\n                                                      ‫كمــا مت تفتيــش املصــدر إبـ ً‬\n      ‫طريــق األميــر ‪ ............‬باجلبيــل البلــد حيــث ركــب الوســيط مــع املصــدر‬\n      ‫وممثــل دور املشــتري بعدهــا حتركــوا إلــى خلــف مستشــفى اجلبيــل البلد‬\n      ‫العــام حيــث اتضــح فيمــا بعــد أنهــم ينتظــرون املــروج وأثنــاء ذلــك لوحــظ‬\n      ‫شــخص يحتــك بهــم واتضــح أنــه املــروج وركــب معهــم أيضـ ًا وحتركــوا‬\n      ‫جميعـ ًا إلــى أمــام محطــة الشــعلة بجــوار شــركة الكهربــاء حيــث نــزل‬\n      ‫املــروج ودخــل أحــد الشــوارع املظلمــة بعدهــا بســاعة نــزل الوســيط بعــد‬\n      ‫االتصــال الــذي ورده مــن املــروج وبعــد خمــس دقائــق عــاد الوســيط وقــام‬\n      ‫بتســليم ممثــل دور املشــتري قطعــة بنيــة اللــون بلــغ وزنهــا (‪ )4.6‬أربعــة‬\n      ‫جرامــات وســتة بالعشــرة مــن اجلــرام يشــتبه أن تكــون مــن احلشــيش‬\n      ‫املخــدر كمــا حضــر املــروج أيض ـ ًا وركــب هــو والوســيط بالســيارة‬\n      ‫بعدهــا مت القبــض عليهمــا حيــث اتضــح أن الوســيط هــو املدعــى عليــه‬\n\n\n‫‪167‬‬\n\f‫الثانــي ولــم يعثــر معــه علــى أيــة ممنوعــات وبضبــط املــروج اتضــح أنــه‬\n‫املدعــى عليــه األول ولــم يعثــر معــه علــى أيــة ممنوعــات ولــم يعثــر معــه‬\n‫علــى املبلــغ املرقــم وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم‬\n‫(‪ 2156‬ك ش) وتاريــخ ‪1433/6/7‬ه ـ ايجابيــة القطعــة املضبوطــة ملــادة‬\n‫احلشــيش املخــدر املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n                                                         ‫وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n‫باســتجواب املدعــى عليــه األول (‪ ).....‬أقــر بصحــة واقعــة القبــض عليــه‬\n‫مــن قبــل مكافحــة املخــدرات باجلبيــل بعــد قيامــه بترويــج قطعــة بلــغ‬\n‫وزنهــا (‪ )4.6‬أربعــة جرامــات وســتة بالعشــرة مــن اجلــرام مــن احلشــيش‬\n‫املخــدر وأنــه حصــل عليهــا مــن شــخص بــأم الســاهك ال يعرفــه مببلــغ‬\n‫(‪ )250‬مائتــن وخمســن ريــا ًال وقصــده مــن عمليــة الترويــج الكســب‬\n‫املــادي وأنــه يتعاطــى احلشــيش املخــدر منــذ ســتة أشــهر وصــادق علــى‬\n‫أقوالــه شــرع ًا وباســتجواب املدعــى عليــه الثانــي (‪ )....‬أقــر بصحــة واقعــة‬\n‫القبــض عليــه مــن قبــل مكافحــة مخــدرات اجلبيــل بعــد قيامــه بالتوســط‬\n‫يف ترويــج قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )4.6‬أربعــة جرامــات‬\n‫وســتة بالعشــرة مــن اجلــرام مــن احلشــيش املخــدر وأن قصــده مــن عمليــة‬\n‫التوســط هــو خدمــة زميلــه وأنــه يتعاطــى احلشــيش املخــدر منــذ خمــس‬\n‫ســنوات وصــادق علــى أقوالــه شــرع ًا وانتهــى التحقيــق إلــى توجيــه االتهام‬\n‫للمدعــى عليــه األول بترويــج قطعــة مــن مــادة احلشــيش املخــدر بلــغ وزنهــا‬\n‫(‪ )4.6‬أربعــة جرامــات وســتة بالعشــرة مــن اجلــرام وتعاطيــه للحشــيش‬\n‫املخــدر وتوســط املدعــى عليــه الثانــي يف ترويــج تلــك القطعــة وتعاطيــه‬\n                             ‫لــذات النــوع وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n\n\n                                                                                     ‫‪168‬‬\n\f      ‫‪ -1‬إقرارهمــا املصــدق شــرع ًا املنــوه عنــه واملــدون علــى الصفحتــن رقــم‬\n                                                 ‫(‪ )15 ، 13‬مــن دفتــر التحقيــق املرفــق‬\n      ‫‪ -2‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                                                         ‫(‪ )1‬مــن دفتــر التحقيــق املرفــق‬\n      ‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                                      ‫(‪)13‬‬\n      ‫وبالبحــث عمــا إذا كان لهمــا ســوابق جنائيــة لــم يعثــر لهمــا علــى‬\n                                                                           ‫ســوابق مســجلة‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات‬\n                                                                                    ‫مــا يلــي‬\n      ‫أو ًال ‪ :‬إثبــات مــا أســند إليهمــا وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪)3‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليهمــا مبــا‬\n                                                                                         ‫يلــي‬\n      ‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املنصــوص عليهــا بالفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )38‬مــن ذات النظــام املشــار إليــه مــع مراعــاة إعمــال‬\n                                             ‫املــادة رقــم (‪ )62‬مــن النظــام املشــار إليــه‬\n      ‫‪ -2‬منعهمــا مــن الســفر إلــى خــارج اململكــة وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n                                      ‫املــادة رقــم (‪ )56‬مــن ذات النظــام املشــار إليــه‬\n      ‫ثانيـ ًا ‪ :‬مصــادرة جهــاز جوالــي املدعــى عليهمــا األول مــن نــوع (‪ )....‬يحمــل‬\n      ‫الرقــم املصنعــي رقــم (‪ )............‬والثانــي مــن نــوع (‪ ).....‬يحمــل الرقــم‬\n      ‫املصنعــي رقــم (‪ )........................‬الســتخدامهما بعمليــة الترويــج وفق ـ ًا‬\n      ‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪169‬‬\n\f‫وإيــداع قيمتــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات وفق ـ ًا‬\n‫لقــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪1421/12/18‬ه ـ ‪ ،‬وإلغــاء‬\n‫الشــريحتني املتعلقــة بالرقمــن املســتخدمني يف اجلرميــة وعــدم صرفهــا‬\n‫للمدعــى عليهمــا مــرة أخــرى وفق ـ ًا لتعميــم صاحــب الســمو امللكــي‬\n‫ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)9798‬‬\n‫وتاريــخ ‪1428/2/10/9‬ه ـ ‪ ،‬وإعــادة املبلــغ املرقــم وقــدره (‪ )250‬مائتــن‬\n‫وخمســن ريــا ًال اســتناد ًا لتعميــم صاحــب الســمو امللكــي ولــي العهــد‬\n‫نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)15980/4/5/1‬‬\n‫وتاريــخ ‪1428/10/23-22‬ه ـ ‪ ،‬وإيداعــه يف حســاب اإلدارة العامــة‬\n‫ملكافحــة املخــدرات وفق ـ ًا للقــرار الســابق وبعــرض دعــوى املدعــي‬\n‫العــام علــى املدعــى عليــه األول ‪ ....‬أجــاب قائــا مــا ذكــره املدعــي‬\n‫العــام يف دعــواه صحيــح جملــة وتفصيــا وبعــرض دعــوى املدعــي العــام‬\n‫علــى املدعــى عليــه الثانــي ‪ ....‬أجــاب قائــا مــا ذكــره املدعــي العــام‬\n‫يف دعــواه صحيــح جملــة وتفصيــا ثــم جــرى ســؤال املدعــي العــام عــن‬\n‫الرقــم اال خــر املســتخدم يف عمليــة الترويــج وكــم هــو رقمــه فقــال‬\n‫أطلــب مهلــة ملراجعــة أوراق املعاملــة رفعــت اجللســة ويف يــوم الســبت‬\n‫املوافــق‪ 1433/07/26‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا‬\n‫حضــر املدعــي العــام ‪ .....‬واملدعــى عليهمــا ‪ .....‬ثــم جــرى ســؤال املدعــي‬\n‫العــام عــن الرقــم اآلخــر املســتخدم يف عمليــة الترويــج فقــال هــو الرقــم‬\n‫(‪ ).......‬كمــا جــرى ســؤاله عــن قصــد املدعــى عليــه األول مــن الترويــج‬\n‫فقــال بقصــد الكســب املــادي ثــم جــرى ســؤال املدعــى عليهمــا مــن الذي‬\n‫اســتلم املبلــغ احلكومــي الــذي قــدره (‪ )250‬مائتــان وخمســون ريــال فقال‬\n‫املدعــى عليــه األول أنــا مــن اســتلمت املبلــغ احلكومــي ثــم جــرى االطالع‬\n\n\n                                                                                   ‫‪170‬‬\n\f      ‫علــى أوراق املعاملــة فوجــد علــى لفــه رقــم (‪ )13‬التقريــر الكيمــاوي‬\n      ‫الشــرعي رقــم (‪ 2156‬ك ش ) وباالطــاع عليــه وجــد يتضمــن ايجابيــة‬\n      ‫العينــات املأخــوذة مــن املضبوطــات مــع املدعــى عليهمــا ملــادة احلشــيش‬\n      ‫املخــدر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى‬\n      ‫عليهمــا بدعــوى املدعــي العــام ولكــون مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫فعــل محــرم شــرعا ولقولــه صلــى اهلل عليــه وســلم (كل مســكر حــرام)‬\n      ‫وقولــه (مــن شــرب اخلمــر فاجلــدوه) رواهمــا أبــوداود وأحمــد وبنــاء علــى‬\n      ‫املــادة رقــم (‪ )38‬ورقــم (‪ )53‬ورقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة فقــد ثبــت لــدي إدانــة املدعــى عليــه األول بترويــج‬\n      ‫قطعــة مــن مــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )4.6‬أربعــة جرامــات‬\n      ‫وســتة بالعشــرة مــن اجلــرام بقصــد الكســب املــادي وتعاطيــه للحشــيش‬\n      ‫املخــدر وتوســط املدعــى عليــه الثانــي يف ترويــج تلــك القطعــة وتعاطيــه‬\n      ‫لــذات النــوع ولقلــة الكميــة املروجــة ولعــدم وجــود ســوابق علــى املدعــى‬\n      ‫عليهمــا ولصغــر ســنهما فقــد حكمــت علــى األول ‪ .....‬مبــا يلــي ‪ :‬أوال‬\n      ‫‪ :‬يجلــد (‪ )80‬ثمانــن جلــده حــد املســكر ثانيــا ‪ :‬يســجن ملــدة ثــاث‬\n      ‫ســنوات مــن تاريــخ إيقافــه ثالثــا‪ :‬يجلــد (‪ )300‬ثالثمائــة جلــدة مفرقــه‬\n      ‫علــى ســتة بــن كل دفعــة واألخــرى خمســة عشــر يومـ ًا رابعــا ‪ :‬مينــع مــن‬\n      ‫الســفر خــارج اململكــة ملــدة ثــاث ســنوات بعــد تنفيــذ عقوبــة الســجن‬\n      ‫خامســا ‪ :‬إعــادة املبلــغ احلكومــي وقــدره (‪ )250‬مائتــان وخمســون ريــا ًال‬\n      ‫ويــودع يف حســاب اإلدارة العامــة املكافحــة املخــدرات سادســا ‪ :‬إلغــاء‬\n      ‫رقــم الشــريحة (‪ )......‬وعــدم صرفــه لــه مــرة أخــرى وحكمــت علــى‬\n      ‫املدعــى عليــه الثانــي مبــا يلــي أوال ‪ :‬يجلــد (‪ )80‬جلــده حــد املســكر‬\n      ‫ثانيــا ‪ :‬يســجن املــدة ســنتني مــن تاريــخ إيقــاف ثالثــا ‪ :‬يجلــد (‪ )200‬مئتــي‬\n\n\n‫‪171‬‬\n\f‫جلــدة مفرقــة علــى أربــع دفعــات بــن كل دفعــة واالخــرى خمســة عشــر‬\n‫يــوم رابعــا ‪ :‬مينــع مــن الســفر خــارج اململكــة املــدة عامــن بعــد تنفيــذ‬\n‫احلكــم خامســا ‪:‬الغــاء الشــريحة رقــم (‪ )....‬وعــدم صرفــه لــه مــرة أخــرى‬\n‫كمــا حكمــت مبصــادرة جهــازي اجلــوال املذكــور رقمهمــا املصنعيــة‬\n‫يف الدعــوى وإيــداع قيمتهمــا يف حســاب اإلدارة العامــة املكافحــة‬\n‫املخــدرات وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليهمــا القناعة‬\n‫واملدعــي العــام عدمهــا وطلــب رفــع القضيــة حملكمــة اإلســتئناف بــدون‬\n‫الئحــة اعتراضيــة واكتفــى مبــا قــدم لــذا قــررت رفــع القضيــة حملكمــة‬\n‫اإلســتئناف باملنطقــة الشــرقية وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/07/26‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫لــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم األحــد‬\n‫املوافــق ‪ 1434/03/22‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‬\n‫وحيــث كنــت مشــارك بــدورة تدريبيــة مبدينــة الريــاض مــن تاريــخ‬\n‫‪ 1433/12/18‬إلــى ‪1434/03/18‬ه ـ وفيهــا حضــر املدعي العام بدائرة‬\n‫التحقيــق واإلدعــاء العــام باجلبيــل ‪ ......‬واملدعــى عليهمــا األول ‪ .....‬والثانــي‬\n‫‪ ....‬وكانــت قــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية باخلطــاب رقــم ( ‪ ) 331570304‬وتاريــخ ‪1433/11/21‬ه ـ‬\n‫املرفــق بــه القــرار رقــم ( ‪ ) 33444434‬وتاريــخ ‪1433/11/02‬ه ـ‬\n‫املتضمــن انــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫أن فضيلتــه اثبــت ادانــة املدعــى عليهمــا بالترويــج والتوســط ولــم يحكــم‬\n‫عليهمــا بغرامــة ماليــة حســب مــا نصــت عليــة املــادة الثامنــة والثالثــون‬\n‫مــن نظــام مكافحــة املخــدرات عليــه أجيــب فقــد حكمــت علــى املدعــى‬\n\n\n                                                                                         ‫‪172‬‬\n\f      ‫عليهمــا بدفــع غرامــة قدرهــا (‪ )1000‬ألــف ريــال تــودع يف حســاب اإلدارة‬\n      ‫العامــة ملكافحــة املخــدرات وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/ 03 /22‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n      ‫‪ ......‬القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم االثنــن املوافــق‬\n      ‫‪ 1434/08/29‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا حضــر‬\n      ‫املدعــى عليهمــا األول ‪ .....‬والثانــي ‪ .......‬وحيــث عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية باخلطــاب رقــم ‪341734585‬‬\n      ‫وتاريــخ ‪1434/08/02‬ه ـ واملقيــدة باحملكمــة برقــم ‪341917981‬‬\n      ‫وتاريــخ ‪1434/08/08‬ه ـ واملرفــق بــه القــرار رقــم ‪ 34280744‬وتاريــخ‬\n      ‫‪1434/07/26‬ه ـ املتضمــن أنــه وبدراســة القــرار وصــورة ضبطــه لوحــظ‬\n      ‫مــا يلــي أوال ‪ /‬أن فضيلتــه حكــم علــى املدعــى عليهمــا بدفــع ألــف ريــال‬\n      ‫ولــم يوضــح احلكــم هــل الدفــع لــكل واحــد منهمــا أم يشــتركان يف‬\n      ‫دفــع االلــف ثانيــا‪ /‬لــم يعــرض فضيلتــه احلكــم علــى املدعــى عليهمــا‬\n      ‫فيمــا حكــم بــه أخيــرا عليــه أجيــب أمــا مــا يتعلــق باملالحظــة األولــى‬\n      ‫فــإن مبلــغ الغرامــة احملكــوم بــه هــو علــى كل واحــد مــن املدعــى عليهــم‬\n      ‫وأمــا مــا يتعلــق باملالحظــة الثانيــة فبعــرض احلكــم األخيــر علــى املدعــى‬\n      ‫عليهمــا قــررا القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/29‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .......‬القاضــي باحملكمــة العامــة باجلبيــل والقائــم بعمــل املكتــب‬\n      ‫القضائــي الثالــث ففــي يــوم األربعــاء املوافــق ‪ 1434/10/28‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة ويف يــوم األربعــاء املوافــق ‪1434/10/28‬ه ـ‬\n\n\n‫‪173‬‬\n\f‫افتتحــت اجللســة الســاعة العاشــرة وكانــت قــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم(‪)342200831‬‬\n‫وتاريــخ ‪1434/01/01‬ه ـ واملقيــدة لدينــا برقــم(‪ )342315157‬وتاريــخ‬\n‫‪1434/10/14‬ه ـ واملرفــق بهــا القــرار رقــم (‪/34324474‬ج‪/1‬أ) وتاريــخ‬\n‫‪1434/09/22‬ه ـ واملتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                       ‫‪1434/10/28‬ه ـ‬\n\n\n\n\n                                                                          ‫‪174‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":165,"source_page_end":174,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb3c604191bbd78ee27bb0a9306ae757cf0944fa31b29c9c2dca51b8cd17558c","normalized_text_hash":"3ba2785b05a01aa73d1596abaf85c918c5f52e590d7651d4f4b34adba624a64a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p165-33357665"},{"id":"d8034249-2096-5c4a-a256-027c286ce375","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -اقرار مصدق شرع ا -طلب تشديد عقوبة -مراعاة تخفيف العقوبة لعدم السوابق -مراعاة تخفيف العقوبة لقلة الكمية املضبوطة -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال .","document_number":"33410812","case_number":"33427178","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل بن لنا من رئيس المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/19","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -اقرار مصدق شرع ا -طلب تشديد عقوبة -مراعاة تخفيف العقوبة لعدم السوابق -مراعاة تخفيف العقوبة لقلة الكمية املضبوطة -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33410812:‬تاريخه ‪1433/3/19:‬هـ‬\n                         ‫رقم الدعوى ‪33427178:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34174256‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة‪ -‬تعاطي احلبوب احملظورة‪ -‬اقرار‬\n      ‫مصــدق شــرع ًا‪ -‬طلــب تشــديد عقوبــة‪ -‬مراعــاة تخفيــف العقوبــة لعــدم‬\n      ‫الســوابق‪ -‬مراعــاة تخفيــف العقوبــة لقلــة الكميــة املضبوطــة ‪ -‬التعزيــر‬\n             ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال ‪.‬‬\n\n\n\n\n      ‫‪ -1‬الفقــرة االولــى مــن املــادة ‪ 38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقليــة ‪.‬‬\n                   ‫‪ -2‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بترويج حبوب‬\n      ‫اإلمفيتامــن احملظــورة بقصــد الكســب املــادي وتعاطيــه لهــا ‪ ،‬وطلــب‬\n      ‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء‬\n      ‫الشــريحة املســتخدمة يف اجلرميــة وتشــديد العقوبــة لترويجــه احلبــوب‬\n      ‫احملظــورة ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليــه بســبب قضيــة‬\n      ‫املخــدرات املنظــورة ‪ ،‬إقــرار املدعــى عليــه بالدعــوى‪ ،‬بنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة‬\n\n‫‪175‬‬\n\f‫واملنــع مــن الســفر‪ ،‬ومصــادرة اجلــوال وألغــاء الشــريحة للمســتخدمني يف‬\n                 ‫اجلرميــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1433/09/11‬ه ـ لــدي‬\n‫ـاء علــى اإلحالــة الــواردة‬\n                           ‫أنــا ‪ ......‬القاضــي باحملكمــة العامــة باجلبيــل بنـ ً‬\n‫لنــا مــن رئيــس احملكمــة برقــم ‪ 33427178‬واملقيــدة باحملكمــة‬\n‫برقــم ‪ 331199945‬يف ‪1433/06/25‬ه ـ حضــر ‪ .....‬بصفتــه املدعــي‬\n‫العــام بهيئــة التحقيــق باجلبيــل وادعــى علــى احلاضــر معــه ‪ ......‬ســعودي‬\n‫ا يف دعــواه أنــه بتاريــخ‬\n                          ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائـ ً‬\n‫‪1433/06/02‬ه ـ مت القبــض علــى املدعــى عليــه يف قضيــة مخــدرات‬\n‫وانتهــى التحقيــق إلــى توجيــه االتهــام لــه بترويــج عــدد (‪ )6‬ســت حبــات‬\n‫مــن حبــوب اإلمفيتامــن احملظــورة بقصــد الكســب املــادي وتعاطيــه‬\n                          ‫لــذات النــوع ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪ -1‬إقــراره املصــدق عليــه شــرع ًا املنــوه عنــه واملــدون علــى الصفحــة رقــم‬\n                                                 ‫(‪ )8‬مــن دفتــر التحقيــق املرفــق‪.‬‬\n‫‪ -2‬محضــر القبــض والتفتيــش املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                                                ‫(‪ )1‬مــن دفتــر التحقيــق املرفــق‪.‬‬\n   ‫‪ -3‬التقرير الكيماوي الشرعي املنوه عنه املرفق على اللفة رقم (‪.)13‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق جنائيــة عثــر لــه على ســابقتني األولى‬\n‫ارتــكاب عــدة ســرقات اقترنــت بإطــاق النــار والثانيــة ســرقة ســيارات‬\n‫واقترنــت بســرقة حيوانــات‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪-‬‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا و‬\n\n                                                                                       ‫‪176‬‬\n\f      ‫نظامـ ًا أطلــب إثبــات مــا أســند إليــه وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه باآلتــي ‪-:‬‬\n      ‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املنصــوص عليهــا يف الفقــرة رقــم‬\n                              ‫(‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام املشــار إليــه‪.‬‬\n      ‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن‬\n                                          ‫املــادة رقــم (‪ )56‬مــن النظــام املشــار إليــه‪.‬‬\n      ‫‪ -3‬مصــادرة الهاتــف النقــال مــن نــوع (‪ ).....‬يحمــل الرقــم املصنعــي‬\n      ‫(‪ )............‬املســتخدم يف عمليــة ترويــج املخــدرات وفقـ ًا للفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات وإيــداع قيمتــه يف‬\n      ‫حســاب اإلدارة العامــة ملكافحــة املخــدرات وفقـ ًا لقــرار مجلــس الــوزراء‬\n      ‫رقــم (‪ )47‬وتاريــخ ‪1421/12/18‬ه ـ ‪ ،‬وإلغــاء الشــريحة املتعلقــة بالرقــم‬\n      ‫املســتخدم يف اجلرميــة وعــدم صرفهــا للمدعــى عليــه مــرة أخــرى وفق ـ ًا‬\n      ‫لتعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الوزراء‬\n                       ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n      ‫‪ -4‬تشــديد العقوبــة عليــه لترويجــه احلبــوب احملظــورة اســتناد ًا لبرقيــة‬\n      ‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n      ‫الداخليــة رقــم (‪2/8346/4/5/1‬ش) وتاريــخ ‪1427/2/8‬ه ـ هــذه‬\n      ‫ا مــا ذكــره املدعي‬   ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫العــام كلــه ثابــت وصحيــح فقــد قمــت ببيــع ســت حبــات مــن حبــوب‬\n      ‫االمفيتامــن احملظــورة مببلــغ وقــدره مائتــي ريــال كمــا أننــي أتعاطــى‬\n      ‫احلبــوب احملظــورة وأنــا تائــب ونــادم أشــد النــدم وأعدكــم أال أعــود ملثــل‬\n      ‫هــذه األمــور هكــذا أجــاب ثــم جــرى االطــاع علــى التقريــر الكيمــاوي‬\n      ‫الشــرعي رقــم ‪ 2245‬ك ش يف ‪1433/06/11‬ه ـ فوجــد يتضمــن إيجابيــة‬\n\n\n‫‪177‬‬\n\f‫احلبــوب املضبوطــة ملــادة اإلمفيتامــن احملظــورة ثــم جــرى اإلطــاع علــى‬\n‫مذكــرة الســوابق فوجــدت كمــا ذكــر املدعــي العــام وبعرضهــا علــى‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬  ‫املدعــى عليــه صــادق عليهــا فبنـ ً‬\n‫ومــا قــرره الطرفــان فقــد ثبــت لــدي قيــام املدعــى عليــه بترويــج عــدد (‪)6‬‬\n‫ســت حبــات مــن حبــوب اإلمفيتامــن احملظــورة بقصــد الكســب املــادي‬\n                             ‫وتعاطيــه لــذات النــوع وحكمــت عليــه مبــا يلــي‪:‬‬\n‫‪ -1‬تطبيــق العقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام‬\n‫مكافحــة املخــدرات وذلــك بســجنه خمــس ســنوات تعتبــر مــن تاريــخ‬\n‫إيقافــه وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات كل دفعــة‬\n‫خمســون جلــدة بــن الدفعــة والتــي تليهــا فتــرة ال تقــل عــن اســبوعني‬\n                                       ‫وتغرميــه مبلــغ وقــدره خمســة اآلف ريــال‪.‬‬\n‫‪-2‬منعــه مــن الســفر ملــدة خمــس ســنوات تعتبــر مــن تاريــخ خروجــه مــن‬\n                                                                            ‫الســجن‪.‬‬\n‫‪-3‬مصــادرة الهاتــف النقــال مــن نــوع ‪ .....‬يحمــل الرقــم املصنعــي ‪............‬‬\n     ‫املســتخدم يف عمليــة ترويــج املخــدرات والغــاء الشــريحة للرقــم (‪)......‬‬\n‫‪-4‬تشــديد العقوبــة عليــه لترويجــه احلبــوب احملظــورة وذلــك بجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن‬\n                            ‫الدفعــة والتــي تليهــا فتــرة ال تقــل عــن اســبوعني‪.‬‬\n‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n‫قناعتــه باحلكــم كمــا قــرر املدعــى عليــه عــدم قناعتــه بــه وطالــب‬\n‫بتمييــزه بــدون الئحــة فأجبتــه لطلبــه وأمــرت برفــع األوراق حملكمــة‬\n‫االســتئناف باملنطقــة الشــرقية‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/09/11‬هــ‪.‬‬\n\n\n                                                                                        ‫‪178‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1433/11/22‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف باملنطقة الشــرقية برقم ‪331737183‬‬\n      ‫يف ‪1433/11/10‬ه ـ وبرفقهــا قــرار اجــاب الفضيلــة قضــاة الدائــرة‬\n      ‫اجلزائيــة الثانيــة رقــم ‪ 33425305‬يف ‪1433/10/14‬ه ـ ونــص املقصــود‬\n      ‫منــه ( وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ مايلــي‪:‬‬\n      ‫أوالً‪ /‬لــم يتــم توقيــع املدعــى عليــه يف الضبــط كمــا يظهــر مــن صــورة‬\n      ‫الضبــط املرفقــة‪ .‬ثانيـاً‪ /‬أال يــرى فضيلتــه إعمــال املــادة الســتني مــن نظام‬\n      ‫املخــدرات ويخفــف الســجن علــى املدعــى عليــه وأنــه ليــس عليــه ســوابق‬\n      ‫والكميــة قليلــه فعلــى فضيلتــه مالحظــة مــا ذكــر ) أ‪ .‬هــ‪ .‬ولوجاهــة مــا‬\n      ‫ُذكــر فقــد رجعــت عمــا حكمــت بــه ســابق ًا وحكمــت علــى املدعــى‬\n      ‫عليــه مبايلــي‪ /1:‬تطبيــق العقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪)38‬‬\n      ‫مــع مراعــاة مــا ورد يف املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات نظــر ًا‬\n      ‫لعــدم وجــود ســوابق علــى املدعــى عليــه لقلــة الكميــة املروجــة وذلــك‬\n      ‫بســجنه ملــدة ســنتني تعتبــر مــن تاريــخ إيقافــه وجلــده خمســمائة جلــده‬\n      ‫مفرقــة علــى عشــر دفعــات كل دفعــه خمســون جلــده بــن الدفعــة والتــي‬\n      ‫تليهــا فتــرة ال تقــل عــن اســبوعني وتغرميــه مبلــغ وقــدره خمســة آالف ريــال‪.‬‬\n      ‫‪ /2‬منعــه مــن الســفر خــارج اململكــة ملــدة خمــس ســنوات تعتبــر من تاريخ‬\n      ‫خروجــه مــن الســجن‪ /3 .‬مصــدرة الهاتــف النقــال مــن نــوع نوكيــا يحمــل‬\n      ‫الرقــم املصنعــي ‪ ............‬املســتخدم يف عمليــة ترويــج املخــدرات وإلغــاء‬\n      ‫الشــريحة للرقــم(‪ /4 .).........‬تشــديد العقوبــة عليــه لترويجــه احلبــوب‬\n      ‫احملظــورة وذلــك بجلــده ثالثمائــة جلــده مفرقــة علــى ســت دفعــات كل‬\n      ‫دفعــه خمســون جلــده بــن الدفعــة والتــي تليهــا فتــرة ال تقل عن أســبوعني‪.‬‬\n\n\n‫‪179‬‬\n\f‫وبالنســبة ملــا ورد يف املالحظــة األولــى فقــد مت إكمــال الــازم حيالهــا‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم‬\n‫وقــرر املدعــي العــام عــدم قناعتــه بــه وأنــه ال يــزال علــى اعتراضــه بــدون‬\n‫الئحــة فأجبتــه لطلبــه وأمــرت بإعــادة املعاملــة الــى محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية كاملتبــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/22‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام كمــا حضــر املدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 332196032‬يف وبرفقهــا قــرار‬\n‫اصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم ‪ 33478085‬يف‬\n‫‪1433/12/26‬ه ـ ونــص املقصــود منــه ( وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه علــى قرارنــا رقــم ‪/33425305‬ج‪/2‬ب يف ‪1433/10/14‬ه ـ‬\n‫لوحــظ أن فضيلتــه منــع املدعــى عليــه مــن الســفر ملــدة خمــس ســنوات‬\n‫واملتعــن أن يكــون املنــع مــن الســفر مــدة مماثلــة لســجنه فعلــى فضيلتــه‬\n‫مالحــظ مــا ذكــر ) أ‪ .‬هــ‪ .‬ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد‬\n‫رجعــت عمــا حكمــت بــه ســابق ًا مبنــع املدعــى عليــه مــن الســفر ملــدة‬\n‫خمــس ســنوات وحكمــت مبنــع املدعــى عليــه مــن الســفر ملــدة ســنتني‬\n‫تعتبــر مــن تاريــخ خروجــه مــن الســجن وبعــرض احلكــم علــى الطرفــن‬\n‫قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام بقائــه علــى‬\n‫اعتراضــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف‪1434/02/20‬هــ‪ .‬احلمــد هلل وحــده وبعـدـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة لــدي أنــا املــازم‬\n‫القضائــي باحملكمــة العامــة باجلبيــل والقائــم بعمــل املكتــب القضائــي‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫ـاء علــى تعميــد فضيلــة رئيــس احملكمــة رقــم‬‫الثانــي بهــذه احملكمــة بنـ ً‬\n      ‫‪ 34828702‬يف ‪1434/04/06‬ه ـ وقــد وردتنــي املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 34711066‬يف ‪1434/04/08‬ه ـ‬\n      ‫وبرفقهــا قــرار اصحــاب الفضيلــة رقــم ‪ 34174256‬يف ‪1434/03/29‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم ولبيانــه جــرى منــا تدوينــه‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                   ‫حــرر يف ‪ 1434/04/20‬ه ـ ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":175,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"07c88690d0d19eba710a0771989fc87252f99f2337ed4f8e47990e253ac536a1","normalized_text_hash":"76fd39a79f77791ec200cf76f49a78ab6331fcad9ef6d5ff3aded58d2c43b281","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p175-33410812"},{"id":"2e65e854-d0a3-5efb-8aa8-45b7012547c2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -قيادة سيارة حتت تأثير املخدر -تستر -إثبات إدانة -إقامة حد املسكر على متعاطي احلشيش -تعزير بالسجن واجللد والغرامة واإلبعاد املادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","document_number":"33439718","case_number":"33473749","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/28","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -قيادة سيارة حتت تأثير املخدر -تستر -إثبات إدانة -إقامة حد املسكر على متعاطي احلشيش -تعزير بالسجن واجللد والغرامة واإلبعاد املادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33439718 :‬تاريخه ‪1433/10/28 :‬هـ‬\n                    ‫رقم الدعوى‪33473749 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 33454856‬تاريخه‪1433/7/8 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬قيادة‬\n ‫ســيارة حتــت تأثيــر املخــدر ‪ -‬تســتر ‪ -‬إثبــات إدانــة ‪ -‬إقامــة حــد املســكر‬\n ‫علــى متعاطــي احلشــيش ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واإلبعــاد‬\n\n\n\n                  ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بترويجــه قطعــة مــن احلشــيش‬\n ‫املخــدر وتعاطيــه احلشــيش املخــدر وقيادتــه للســيارة حتــت تأثيــر تعاطــي‬\n ‫احلشــيش و تســتره علــى مصــدر مــا مت ترويجــه‪ ،‬طلــب املدعــي العــام‬\n ‫إثبــات مــا أســند إليــه و احلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n ‫املاليــة‪ ،‬إبعــاده إلــى خــارج البــاد بعــد انتهــاء عقوبــة الســجن وعــدم‬\n ‫الســماح لــه بالعــودة مــرة أخــرى وإجــراء املقتضــى الشــرعي لقــاء تعاطيــه‬\n ‫احلشــيش املخــدر ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة و إلغــاء‬\n ‫الشــريحة املســتخدمة يف اجلرميــة وإلــزام املدعــى عليــه بــرد املبلــغ املرقــم‬\n ‫كامـاً‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليــه بعــد ورود بــاغ عنــه‬\n ‫بأنــه يقــوم بالتوســط يف بيــع احلشــيش املخــدر‪ ،‬وقــد مت التنســيق مــع‬\n ‫أحــد املصــادر الســرية لإلطاحــة بــه و مت االتصــال علــى املدعــى عليــه‬\n\n                                                                                       ‫‪182‬‬\n\f      ‫مــن قبــل املصــدر ومت التنســيق معــه واالتفــاق علــى الزمــان و املــكان و‬\n      ‫بعــد ذلــك مت القبــض عليــه متلبسـ ًا بعــد اســتالم املبلــغ املرقــم مــن املصــدر‬\n      ‫واســتالم املدعى عليه قطعة احلشــيش من قائد ســيارة أخرى و تســليمها‬\n      ‫للمصــدر‪ ،‬صــادق املدعــى عليــه علــى مــا نســب إليــه بتعاطــي احلشــيش‬\n      ‫املخــدر‪ ،‬وأنكــر املدعــى عليــه ترويجــه لقطعــة احلشــيش املخــدر‪ ،‬رغــم‬\n      ‫إقــراره حتقيق ـ ًا وثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه‪ ،‬معاملــة‬\n      ‫املدعــى عليــه وفــق املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه‬\n      ‫بالســجن واجللــد وإقامــة حــد املســكر علــى املدعــى عليــه والغرامــة و‬\n      ‫اإلبعــاد وصــرف النظــر عــن دعــوى املدعي العام بإرجــاع املبلغ احلكومي‬\n                ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬            ‫و مصــادرة اجلــوال ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33473749‬وتاريــخ ‪ 1433/07/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331353830‬وتاريــخ ‪ 1433/07/19‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1433/08/07‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ....‬وقــدم الئحة الدعــوى قائال بصفتي عضو‬\n      ‫هيئــة التحقيــق واالدعــاء العــام بدائــرة شــرق مدينــة الريــاض ادعي على‪/‬‬\n      ‫اســم املتهــم‪ .... :‬اجلنــس‪ :‬ذكــر ‪،‬اجلنســية‪ :‬فلســطيني ‪،‬الديانــة‪ :‬مســلم‪،‬‬\n      ‫نــوع الهويــة‪ :‬رخصــة إقامــة‪ ،‬رقــم الهويــة‪ ،..... :‬املهنــة‪ :‬طالــب ‪ ،‬احلالــة‬\n      ‫االجتماعيــة‪ :‬أعــزب ‪،‬جهــة اإليقــاف‪ :‬شــعبة ســجن امللــز ‪،‬تاريــخ القبــض‪:‬‬\n\n‫‪183‬‬\n\f‫‪، 1433/6/5‬حالــة املتهــم‪ :‬موقــوف ‪،‬االتهــام‪ :‬بيــع ‪ ،‬املــواد املخــدرة‬\n‫الســوابق‪ :‬ال يوجــد فبتاريــخ ‪1433/6/5‬ه ـ قبــض علــى املذكــور مــن‬\n‫قبــل إحــدى فــرق قــوة املســاندة اخلاصــة اثــر توافــر معلومــات لــدى الفرقــة‬\n‫عــن طريــق أحــد مصادرهــا الســرية عــن قيــام املتهــم املذكــور بالتوســط‬\n‫يف ترويــج احلشــيش املخــدر ويســكن بحــي الربــوة ويتواجــد علــى هاتفــه‬\n‫اجلــوال رقــم (‪ )....‬وقــد اســتعد املصــدر لإلطاحــة بــه باجلــرم املشــهود عليــه‬\n‫مت اإليعــاز للمصــدر باالتصــال علــى جــوال املــروج وطلــب منــه كميــة مــن‬\n‫احلشــيش املخــدر مببلــغ وقــدره (‪ )200‬مائتــي ريــال وأفــاد للمصــدر بأنــه‬\n‫ســوف يأخــذ قطعــة احلشــيش مــن شــخص آخــر بعــد اســتالمه للمبلــغ‬\n‫ومت االتفــاق معــه علــى ذلــك وطلــب مــن املصــدر احلضــور إلــى أســواق‬\n‫(‪ )....‬ومت تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا وتزويــده باملبلــغ املرقــم وقــدره‬\n‫(‪ )200‬مائتــي ريــال ومت تكليــف أحــد أفــراد الفرقــة مبرافقــه املصــدر‬\n‫لإلشــراف علــى عمليــة االســتالم والتســليم وبانتقــال الفرقــة إلــى املوقــع‬\n‫املتفــق عليــه حضــر املــروج وركــب مــع املصــدر وفــرد الفرقــة املكلــف‬\n‫واســتلم املبلــغ املرقــم وقــدره (‪ )200‬مائتــي ثــم قــام باالتصــال علــى‬\n‫شــخص وأخبــره بأنــه يف املوقــع وعندهــا حضــرت ســيارة مــن نــوع ‪....‬‬\n‫حتمــل اللوحــة رقــم (‪( )......‬مت فــرز أوراق مســتقلة للســيارة وقائدهــا ومت‬\n‫بعثهــا إلــى مكافحــة املخــدرات بشــرق الريــاض مبوجــب اخلطــاب رقــم‬\n‫(‪ )5109‬وتاريــخ ‪1433/7/2‬ه ـ حلــن القبــض عليــه وإحضــاره) وتوقــف‬\n‫بجانــب ســيارة الفرقــة واســتلم املبلــغ املرقــم وقــدره (‪ )200‬مائتــي ريــال‬\n‫مــن املذكــور وســلمه قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر تــزن‬\n‫(‪ )5،2‬خمســة جرامــات وعشــري اجلــرام ثــم قــام بتســليمها إلــى الفــرد‬\n‫املكلــف ومتــت مداهمــة املذكــور والقبــض عليــه ومبتابعــة صاحــب‬\n\n\n                                                                                        ‫‪184‬‬\n\f      ‫الســيارة ‪ ....‬اختفــى عــن األنظــار لكونــه يقــود الســيارة بســرعة جنونيــة‬\n      ‫ومتهــورة وبتفتيــش املذكــور شــخصي ًا عثــر معــه علــى جهــاز جــوال مــن‬\n      ‫نــوع ‪ .....‬يحمــل الرقــم املصنعــي (‪ )............‬اتضــح انــه نفــس اجلــوال الــذي‬\n      ‫متــت عليــه عمليــة التفــاوض والتنســيق ولــم يعثــر معــه علــى املبلــغ املرقــم‬\n                                                           ‫وقــدره (‪ )200‬مائتــي ريــال ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض رقــم (‪/6317‬س) لعــام‬\n      ‫‪1433‬ه ـ ايجابيــة عينــة القطعــة املروجــة ملــادة احلشــيش وهــو مــن املــواد‬\n      ‫املخــدرة واملدرجــة يف اجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة ‪ .‬جــرى مخاطبــة مكافحــة املخــدرات‬\n      ‫بشــرق الريــاض مبوجــب اخلطــاب رقــم (‪ )2350‬وتاريــخ ‪1433/6/7‬ه ـ‬\n      ‫لطلــب حجــز الهاتــف مــع الشــريحة متهيــد ًا ملصادرتــه وبســماع أقــوال‬\n         ‫املتهــم اعتــرف بصحــة قيامــه بالتوســط يف ترويــج احلشــيش املخــدر ‪.‬‬\n      ‫وباســتجوابه اعتــرف حتقيقـ ًا بحيــازة احلشــيش املخــدر بقصــد التعاطــي‬\n      ‫وتعاطيــه احلشــيش املخــدر منــذ ثــاث ســنوات آخرهــا يــوم القبــض عليــه‬\n      ‫كمــا اعتــرف بقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر‬\n      ‫ولــم يــدل املذكــور بــأي معلومــات عــن مصــدر حصولــه علــى احلشــيش‬\n      ‫املخــدر ‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام إلــى‪...../‬‬\n      ‫ببيــع قطعــة مــن احلشــيش املخــدر تــزن (‪ )5،2‬خمســة جرامــات وعشــري‬\n      ‫اجلــرام بقصــد االجتــار والترويــج وتعاطيــه احلشــيش املخــدر املجــرم‬\n      ‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪،‬‬\n      ‫وقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش املخــدر املعاقــب علــى‬\n\n\n‫‪185‬‬\n\f‫ذلــك مبوجــب املــادة (‪ )68‬مــن نظــام املــرور الصــادر باملرســوم امللكــي‬\n   ‫رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ ‪ ،‬وتســتره علــى مصــدر مــا مت‬\n      ‫ترويجه املعاقب على ذلك شرع ًا ‪ .‬وذلك لألدلة والقرائن التالية ‪- :‬‬\n‫‪ -1‬مــا تضمنــه اعترافــه حتقيق ـ ًا بحيازتــه احلشــيش وتعاطيــه وقيادتــه‬\n‫)‪.‬‬              ‫للســيارة حتــت تأثيــره املنــوه عنــه املــدون علــى اللفــات رقــم (‬\n‫‪ -2‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املدون‬\n‫علــى الصفحــة رقــم ( ) مــن ملــف إجــراءات االســتدالل املرفــق لفــة ( ) ‪.‬‬\n‫‪ -3‬مــا تضمنــه محضــر البــاغ والقبــض واالنتقــال والتفتيــش املنــوه عنــه‬\n‫) مــن ملــف إجــراءات االســتدالل‬                  ‫املــدون علــى الصفحــات رقــم (‬\n                                                                      ‫املرفــق لفــة ( ) ‪.‬‬\n‫‪ -4‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n‫رقــم ( ) ‪ .‬وبــورود صحيفــة ســوابقه اتضــح عــدم وجــود ســوابق مســجلة‬\n                                                                 ‫ضــده حتــى تاريخــه ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪:‬‬\n‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا ملــا ورد بالفقــرة‬\n‫(األولــى) مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                             ‫العقليــة ملــا أســند إليــه‪.‬‬\n‫‪ -2‬إبعــاده إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه وعــدم‬\n‫الســماح لــه بالعــودة مــرة أخــرى وفق ـ ًا للفقــرة (الثانيــة) مــن املــادة (‪)56‬‬\n                                                          ‫مــن النظــام املشــار إليــه ‪.‬‬\n         ‫‪ -3‬إجراء املقتضى الشرعي بحقه لقاء تعاطيه احلشيش املخدر ‪.‬‬\n‫‪ -4‬مصــادرة الهاتــف اجلــوال املســتخدم يف التنســيق لعمليــة الترويــج مــن‬\n\n\n                                                                                              ‫‪186‬‬\n\f      ‫نــوع نوكيــا حامــل الرقــم املصنعــي (‪ )............‬وفق ـ ًا للفقــرة (‪ )1‬مــن‬\n                                                ‫املــادة (‪ )53‬مــن النظــام املشــار إليــه ‪.‬‬\n      ‫‪ -5‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة التــي حتمــل الرقــم (‪)....‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حالــة صــدور احلكــم باإللغــاء وإبــاغ‬\n      ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا لتعميــم صاحــب الســمو‬\n          ‫امللكــي وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n      ‫‪ -6‬النظــر فيمــا يتعلــق بقيادتــه للســيارة حتــت تأثيــر تعاطــي احلشــيش‬\n      ‫املخــدر وفــق الفقــرة (الثانيــة) مــن املرســوم امللكــي املشــار إليــه رقــم‬\n      ‫(م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ ‪ - .‬إلــزام املتهــم املذكــور بــرد املبلــغ‬\n      ‫ا وقــدره (‪ )200‬مائتــي ريــال اســتناد ًا لبرقيــة صاحــب‬           ‫املرقــم كام ـ ً‬\n      ‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n                                   ‫رقــم (‪ )65980‬وتاريــخ ‪1428/10/23-22‬ه ـ ‪.‬‬\n      ‫‪ -8‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا مت ترويجــه‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا‬\n      ‫ذكــره املدعــي العــام مــن توســطي يف بيــع احلشــيش املخــدر غيــر صحيــح‬\n      ‫والصحيــح انــه وجــد معــي قطعــة حشــيش قدرهــا خمســة جــرام وعشــري‬\n      ‫اجلــرام مــن احلشــيش املخــدر لغــرض االســتخدام فأنــا أدخــن احلشــيش‬\n      ‫وليــس علــي ســوابق هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام‬\n      ‫علــى توســط املدعــى عليــه مــن ترويــج احلشــيش قــال اطلــب رفــع اجللســة‬\n      ‫إلحضارهــا فرفعــت اجللســة وقــد حــددت لهمــا موعــدا هــو يــوم الســبت‬\n      ‫املوافق ‪1433/08/24‬هـ الساعة التاسعة ‪ .‬وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/08/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1433/08/24‬ه ـ‬\n\n\n‫‪187‬‬\n\f‫افتتحــت اجللســة الســاعة التاســعة وخمســون دقيقــة وفيهــا حضــر املدعي‬\n‫العــام ‪ ....‬واملدعــى عليــه ‪ ....‬ولــم حتضــر البينــة وحــددت لــه موعــدا هــو‬\n‫يــوم األحــد املوافــق ‪1433/09/10‬ه ـ الســاعة احلاديــة عشــر‪ .‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1433/08/24‬ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم األحــد‬\n‫املوافــق‪ 1433/09/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 02:00‬وفيهــا حضر‬\n‫املدعــي العــام ‪ ....‬واملدعــى عليــه ‪ ....‬ولــم يحضــر املدعــي العــام الفرقــة‬\n‫القابضــة وطلــب رفــع اجللســة إلحضارهــم ورفعــت اجللســة لذلــك وقــد‬\n‫حــددت لهمــا موعــدا هــو يــوم االثنــن ‪1433/10/9‬ه ـ الســاعة التاســعة‬\n    ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1433/09/10‬ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم األحــد‬\n‫املوافق‪1433/10/09‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وخمســن‬\n‫دقيقــه وفيهــا حضــر املدعــي العــام ‪ ....‬واملدعــى عليــه ‪ ....‬ولــم يحضــر‬\n‫املدعــي العــام الفرقــة القابضــة وطلــب رفــع اجللســة إلحضارهــم ورفعــت‬\n‫اجللســة لذلــك وقــد حــددت لهما موعدا هو يوم االثنــن ‪1433/10/16‬هـ‬\n‫الســاعة التاســعة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافق‪1433/10/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11:00‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه مؤيــد ولــم يحضــر املدعــي العــام الفرقــة القابضــة وهــذه هــي‬\n‫اجللســة الرابعــة لطلبهــا وقــد جــرى نقــاش املدعــى عليــه عــن دعــوى‬\n‫املدعــي العــام فأصــر علــى جوابــه وأقـ َّـر انــه قــاد الســيارة وهو حتــت تأثير‬\n‫احلشــيش هــذا وقــد جــرى اطالعــي علــى دفتــر التحقيــق املرفــق لفــه (‪)1‬‬\n\n\n                                                                                          ‫‪188‬‬\n\f      ‫صفحــة (‪ )18‬وجــدت املدعــى عليــه ‪ ...‬ملــا ســئل انــت متهــم بالتوســط‬\n      ‫يف ترويــج احلشــيش املخــدر اجــاب قائــا نعــم صحيــح وملــا ســئل مــا هــو‬\n      ‫قصــدك مــن التوســط يف تلــك العمليــة اجــاب بــأن الشــخص الــذي قــام‬\n      ‫بطلبــي احلشــيش قــال احضــر لــي احلشــيش مقابــل مبلــغ مالــي ولذلــك‬\n      ‫ســوف أوفــره لــك وبعرضــه عليــه اجــاب قائــا نعــم اجبــت مبــا ذكــر‬\n      ‫لــدى مكافحــة املخــدرات نتيجــة الضــرب مــن قبــل احملقــق وقــد بصمــت‬\n      ‫عليــه هــذا وقــد جــرى اطالعــي علــى واقعــة القبــض بدفتــر التحقيــق‬\n      ‫املرفــق لفــه (‪ )1‬ص (‪ )11.12‬وجدتــه كمــا نــص عليــه يف دعــوى املدعــي‬\n      ‫العــام ولــم اجــد فيــه اســماء االشــخاص اللذيــن قامــوا بالقبــض ولــم اجده‬\n      ‫موقعــا وبعرضــه علــى املدعــى عليــه اجــاب قائــا نعــم لقــد قبــض علــي‬\n      ‫مــن قبــل الفرقــة ولكــن وجــدوا معــي قطعــة حشــيش لكــن لــم ابــع ولــو‬\n      ‫كنــت بعــت ايــن دراهمــه فــا صحــة لذلــك هــذا وقــد جــرى اطالعــي‬\n      ‫علــى التقريــر الكيمــاوي الشــرعي رقــم ( ‪/6317‬س) لعــام ‪1433‬ه ـ‬\n      ‫املتضمــن ايجابيــة القطعــة املروجــة ملــادة احلشــيش كمــا جــرى اطالعــي‬\n      ‫علــى صحيفــة ســوابق املدعــى عليــه ‪ ...‬فلــم اجــد لــه ســوابقا وقــد وجــدت‬\n      ‫انــه اوقــف يف ‪1433/6/5‬ه ـ فبنــاء ملــا تقــدم مــن الدعــوى واالجابــة‬\n      ‫وحيــث اقــر املدعــى عليــه مؤيــد بحيازتــه لقطعــة احلشــيش املذكــورة‬\n      ‫يف الدعــوى وذكــر انهــا للتعاطــي وليســت للترويــج وحيــث اقــر بتدخــن‬\n      ‫احلشــيش وحيــث اقــر يف دفتــر التحقيــق لــدى احملقــق بالتوســط يف بيعــه‬\n      ‫قطعــة احلشــيش وادعــى انــه حتــت الضــرب وبنــاء ملــا ورد يف محضــر‬\n      ‫القبــض وحيــث لــم يحضــر شــهود الفرقــة القابضــة ولــم يــدل يف دفتــر‬\n      ‫التحقيــق وإلجابتــه عــن اســتخدامه للجــوال والشــريحة يف ترويــج‬\n      ‫املخــدرات فقــد ثبــت لــدي مــا نســب للمدعــى عليــه مــن ترويــج احلشــيش‬\n\n\n‫‪189‬‬\n\f‫البالــغ وزنــه خمســة جرامــات وعشــري اجلــرام وتعاطيــه للحشــيش ونظــرا‬\n‫لصغــر ســن املدعــى عليــه وعــدم ســوابقه ولقلــة الكميــة فقــد قــررت‬\n‫معاملتــه حســب املــادة الســتون مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة وقــررت مــا يلــي اوال ســجن املدعــى عليــه ســنة اعتبــارا مــن تاريــخ‬\n‫توقيفــه ثانيــا جلــده ثمانــن جلــده حــد املســكر ثالثــا جلــده تعزيــرا علــى‬\n‫تســتره علــى املصــدر اربعــن جلــده رابعــا تغرميــه الــف ريــال خلزينــة الدولــة‬\n‫تعزيــرا خامســا ابعــاده عــن اململكــة بعــد انتهــاء فتــرة عقوبــة ســجنه‬\n‫وعــدم الســماح بالرجــوع للمملكــة اال حســب مــا تقتضيــه تعليمــات‬\n‫احلــج والعمــرة سادســا ثبــت لــدي قيــادة املدعــى عليــه للســيارة وهــو حتــت‬\n‫تأثيــر احلشــيش ســابعا صرفــت النظــر عــن دعــوى املدعــي العــام ارجاعــه‬\n‫املبلــغ املرقــم مائتــي ريــال وكذلــك مصــادرة اجلــوال وبعــرض احلكــم‬\n‫علــى اجلميــع قنــع املدعــى عليــه باحلكــم ولــم يقنــع املدعــي العــام وطلــب‬\n‫تدقيقــه مــن قبــل محكمــة االســتئناف بــدون الئحــة فأجيــب لطلبــه‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم ‪ .‬حــرر يف ‪ 1433/10/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء ‪1434/3/18‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 1.30‬بعــد الظهــر وفيهــا حضــر املدعــي العــام ‪......‬‬\n‫واملدعــى عليــه ‪ ...‬وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف‬\n‫وبرفقهــا قــرار أصحــاب الفضيلــة رقــم ‪ 3439879‬يف ‪1434/2/18‬ه ـ‬\n‫ونــص احلاجــة منــه وبدراســة القــرار وصــورة وأوراق املعاملــة قررنــا‬\n‫إعادتهــا ملالحظــة اآلتــي ‪ :‬أوالً‪ /‬أثبــت فضيلتــه مــا نســب إلــى املدعــى‬\n‫عليــه مــن ترويــج احلشــيش املخــدر وهــذا محــل نظــر فليــس يف اعتــراف‬\n‫املدعــى عليــه حتقيق ـ ًا مــا يثبــت ذلــك ولــم يبــن فضيلتــه نــوع الترويــج‬\n\n\n                                                                                        ‫‪190‬‬\n\f      ‫ثانيـاً‪ /‬ملــا عــرض علــى املدعــى عليــه إقــراره حتقيقـ ًا ادعــى أنــه اعتــرف‬\n      ‫بــه نتيجــة الضــرب وهــذه الدعــوى يتوجــه عرضهــا علــى املدعــي العــام‬\n      ‫وإجــراء الوجــه الشــرعي فيهــا ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ .....‬توقيعــه‬\n      ‫وختمــه قاضــي اســتئناف ‪ ...‬توقيعــه وختمــه رئيــس الدائــرة ‪ ....‬توقيعــه‬\n      ‫وختمــه واجلــواب علــى مالحظــة أصحــاب الفضيلــة األولــى والثانيــة أنــه‬\n      ‫جــرى مناقشــة املدعــى عليــه ‪ .....‬عــن إقــراره لــدى احملقــق بــاع خمســة‬\n      ‫جرامــات مــن احلشــيش وعشــرين اجلــرام قــال نعــم أقــررت علــى الضــرب‬\n      ‫بحديــدة املســدس وال أطلــب بإحالــة للمستشــفى للكشــف علــي فــا‬\n      ‫أريــد ذلــك هكــذا قــال وعليــه فــإن نوعيــة الترويــج هــي التوســط يف بيــع‬\n      ‫احلشــيش واضيــف علــى مــا ذكــر يف سادسـ ًا بــأن عقوبتــه علــى قيادتــه‬\n      ‫للســيارة وهــو حتــت تأثيــر احلشــيش عائــدة للجهــة املختصــة واهلل املوفــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬حــرر‬\n                                                                ‫يف ‪ 1434/03/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34508739‬‬\n      ‫وتاريــخ ‪1434/6/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ ‪ ..... /‬املســجل برقــم ‪ 33439718‬وتاريــخ‬\n      ‫‪1433/10/28‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ( ...... /‬فلســطيني‬\n      ‫اجلنســية ) التهامــه بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وحيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب‬\n\n\n‫‪191‬‬\n\f‫بــه فضيلتــه علــى قــرار الدائــرة رقــم ‪ 3439879‬وتاريــخ ‪1434/2/18‬ه ـ‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر مــع تنبيــه فضيلتــه‬\n‫لذكــر املــدة بــن احلــد والتعزيــر يف القــرار قبــل بعثهــا جلهــة التنفيــذ ‪.‬‬\n ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪192‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":182,"source_page_end":192,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a06f4a9f5fd31ac5c02e152dfa8bbc82636429ca01a3a3ffdfd36a6892aff75","normalized_text_hash":"9a2e349b74c0b8a7934cea0075cf63ec48122557cda7defe7e3d6b278062b3c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p182-33439718"},{"id":"413f90cb-a595-56c2-b20e-dce4dc251185","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -تستر- إقامة حد املسكر على تعاطي احلشيش -التعزير بالسجن واجللد والغرامة واملنع من السفر -التعزير مبصادرة اجلوال والشريحة املستخدمتان يف اجلرمية -التعزير بالغرامة لتستره على املصدر.","document_number":"33361642","case_number":"33475473","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/3","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر -تستر- إقامة حد املسكر على تعاطي احلشيش -التعزير بالسجن واجللد والغرامة واملنع من السفر -التعزير مبصادرة اجلوال والشريحة املستخدمتان يف اجلرمية -التعزير بالغرامة لتستره على املصدر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 33361642:‬تاريخه ‪1433/7/3:‬هـ‬\n                         ‫رقم الدعوى‪33475473:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 33454856‬تاريخه‪1433/11/15 :‬هـ‬\n\n\n      ‫مخدرات ‪ -‬ترويج احلشــيش املخدر‪ -‬تعاطي احلشــيش املخدر‪ -‬تســتر‪-‬‬\n      ‫إقامــة حــد املســكر علــى تعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد‬\n      ‫والغرامــة واملنــع مــن الســفر‪ -‬التعزيــر مبصــادرة اجلــوال والشــريحة‬\n       ‫املســتخدمتان يف اجلرميــة ‪ -‬التعزيــر بالغرامــة لتســتره علــى املصــدر‪.‬‬\n\n\n\n\n                   ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                   ‫‪ -2‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n      ‫‪ -3‬الفقــرة األولــى مــن املــادة ‪ 58‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                             ‫العقلية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليــه ترويــج احلشــيش املخــدر وحيــازة‬\n      ‫احلشــيش املخــدر بقصــد الترويــج والتعاطــي وتعاطيــه للحشــيش املخدر‪،‬‬\n      ‫وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكم عليه بالســجن واجللد‬\n      ‫والغرامــة املاليــة ومنعــه مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء‬\n      ‫شــريحته املســتخدمة يف اجلرميــة وعــدم صرفهــا لنفــس املشــترك ‪ ،‬حيــث‬\n      ‫ـاء علــى إخباريــة مفادهــا أن املدعــى‬\n                                           ‫أنــه مت القبــض علــى املدعــى عليــه بنـ ً‬\n      ‫عليــه يقــوم بترويــج احلشــيش املخــدر فتــم التنســيق مــع أحــد املصــادر‬\n\n‫‪193‬‬\n\f‫الســرية لإلطاحــة باملدعــى عليــه ومت التنســيق مــع املدعــى عليــه مــن قبــل‬\n‫وس ـلِم للمصــدر املبلــغ املرقــم ومت تفتيشــه تفتيش ـ ًا دقيق ـ ًا ومت‬\n                                                                      ‫املصــدر ُ‬\n‫مقابلــة املصــدر للمدعــى عليــه وركــب معــه يف الســيارة ثــم نــزل املصــدر‬\n‫وســلم للفرقــة قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر ‪ ،‬ثــم قبــض‬\n‫علــى املدعــى عليــه ووجــد املبلــغ املرقــم معــه وكذلــك اجلــوال املســتخدم‬\n‫يف اجلرميــة ‪ ،‬إقــرار املدعــى عليــه ثبــوت إدانــة املدعــى عليــه ‪ ،‬بنــاء علــى‬\n‫مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســحن واجللــد‬\n‫والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال والشــريحة املســتخدمني‬\n‫يف اجلرميــة وإقامــة حــد املســكر ‪ ،‬وصــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33475473‬وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331360505‬وتاريــخ ‪1433/07/20‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1433/07/23‬ه ـ افتتحــت اجللســة الســاعة ‪02 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام‪ ...... /‬وادعــى علــى‪ ............ ...... /‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )......‬بتاريــخ ‪1433/6/6‬ه ـ‬\n‫قبــض علــى املذكــور مــن قبــل إحــدى فــرق قــوة املســاندة اخلاصــة التابعــة‬\n‫للمديريــة العامــة ملكافحــة املخــدرات مبنطقــة الريــاض وذلــك بنــاء‬\n‫علــى املعلومــات الــواردة لهــا عــن طريــق أحــد املصــادر الســرية عــن وجــود‬\n‫شــخص يدعــى ‪ ...... /‬يســكن يف حــي ‪ ............‬ويقــوم بترويــج احلشــيش‬\n\n                                                                                       ‫‪194‬‬\n\f      ‫املخــدر ويتواجــد علــى هاتفــه اجلــوال رقــم (‪ )......‬ويســتقل ســيارة مــن نــوع‬\n      ‫‪ ......‬وابــدى املصــدر اســتعداده بالتعــاون يف القبــض عليــه وبنــاء ًا علــى‬\n      ‫ذلــك مت االيعــاز للمصــدر باالتصــال عليــه وطلــب منــه توفيــر قطعــة مــن‬\n      ‫احلشــيش املخــدر مقابــل (‪ )200‬مائتــا ريــال فوافــق الشــخص املذكــور‬\n      ‫وحــدد مــع املصــدر مــكان وتوقيــت تســليم القطعة املروجة‪ ،‬وبنــاء ًا عليه‬\n      ‫مت ترقيــم مبلــغ مرقــم وقــدره (‪ )200‬مائتــان ريــال بعــد تفتيــش املصــدر‬\n      ‫بــكل دقــة وزود باملبلــغ املرقــم ويف املوعــد احملــدد نــزل املصــدر مــن‬\n      ‫ســيارة الفرقــة واجتــه الــى احــدى الصيدليــات ملقابلــة املــروج وبعد حوالي‬\n      ‫خمــس دقائــق حضــرت ســيارة مــن نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪).... ...‬‬\n      ‫(تعــود ملكيتهــا ملكتــب ‪ ............‬لتأجيــر الســيارات) كان يســتقلها‬\n      ‫املذكــور ووقفــت بجانــب املصــدر حيــث قــام املصــدر بالركــوب معــه‬\n      ‫يف الســيارة وبعــد ان حتــرك اخــذ املســار الثانــي مــن الشــارع وتوقفــت‬\n      ‫الســيارة ونــزل منهــا املصــدر وبعــد حتــرك الســيارة مــرة اخــرى ووقوفــه‬\n      ‫عنــد االشــارة متــت مداهمتــه والقبــض عليــه وقــام املصــدر بتســليم قائــد‬\n      ‫الفرقــة القطعــة املروجــة وهــي قطعــة تــزن (‪ )2,5‬جرامــن ونصــف‬\n      ‫اجلــرام يشــتبه ان تكــون مــن احلشــيش املخــدر ‪،‬وبتفتيــش املذكــور عثــر‬\n      ‫يف جيــب بنطلونــه اخللفــي علــى املبلــغ املرقــم وعثــر علــى الهاتــف اجلــوال‬\n      ‫املســتخدم يف عمليــة التفــاوض معــه ويحمــل الرقــم املصنعــي (‪.)............‬‬\n      ‫‪ -1‬مت االمــر بتســليم الســيارة مبوجــب اخلطــاب ‪ 2709‬وتاريــخ‬\n                                                                      ‫‪1433/6/9‬ه ـ ‪.‬‬\n      ‫‪ -2‬مت االمــر بحجــز اجلــوال والشــريحة متهيدا للمصــادرة مبوجب اخلطاب‬\n                                                    ‫رقم ‪ 2632‬وتاريخ ‪1433/6/9‬هـ ‪.‬‬\n      ‫‪ -3‬مت االمــر بتســليم املبلــغ املالــي وقــدره (‪ )167‬املضبــوط مــع املذكــور‬\n\n\n‫‪195‬‬\n\f                          ‫مبوجــب اخلطــاب رقــم ‪ 2464‬وتاريــخ ‪1433/6/8‬ه ـ ‪.‬‬\n‫‪ -4‬وبطلــب القــرار الشــرعي رقــم ‪66/5/‬ق وتاريــخ ‪1426/2/4‬ه ـ تبــن‬\n‫ان الســابقة املســجلة عليــه حيــازة احلشــيش املخــدر بقصــد التعاطــي‬\n                                                     ‫وليســت ترويــج مخــدرات‪.‬‬\n‫‪ -5‬مت مخاطبــة ادارة االدلــة اجلنائيــة لتعديــل الوصف اجلرمي يف صحيفة‬\n‫الســوابق مــن ترويــج املخــدرات الــى حيــازة املخــدرات بقصــد التعاطــي‬\n                        ‫مبوجــب اخلطــاب رقــم ‪ 6028‬وتاريــخ ‪1433/7/14‬هــ‪.‬‬\n              ‫وبسماع أقواله االولية اقر بانه سلم املصدر قطعة احلشيش ‪.‬‬\n‫وباســتجوابه اقــر بترويــج احلشــيش املخــدر واقــر بتعاطيــه لــه واقــر بانــه‬\n‫بعــد ان اشــترى القطعــة مــن شــخص يدعــى‪ ... /‬اقتطــع منهــا قطعــة‬\n‫صغيــرة وضعهــا يف جيبــه وانــه عنــد مداهمــة الفرقــة لــه قــام بإخراجهــا‬\n                                                              ‫مــن جيبــه ورماهــا‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي املرفــق رقــم (‪/6318‬س) لعــام‬\n‫‪1433‬ه ـ ايجابيــة عينــة القطعــة املروجــة للحشــيش وهــو املــواد املخــدرة‬\n‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــه املخــدرات‬\n‫واملؤثــرات العقليــة‪ .‬وقــد اســفرت اجــراءات التحقيــق الــى توجيــه االتهــام‬\n‫لــ‪ ........ /‬ببيــع مــا وزنــه (‪ )2,5‬جرامــن ونصــف اجلــرام مــن احلشــيش‬\n‫املخــدر بقصــد االجتــار والترويــج وحيازتــه لقطعــة حشــيش مخــدر مــن‬\n‫ذات نــوع القطعــة املبيعــة غيــر معروفــة الــوزن بقصــد الترويــج والتعاطــي‬\n‫وتعاطيــه للحشــيش املخــدر املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا مت ترويجــه‬\n                                                   ‫املعاقــب علــى ذلــك شــرع ًا ‪.‬‬\n\n\n                                                                                      ‫‪196‬‬\n\f                                                            ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n                 ‫‪ -1‬ما تضمنه اعترافه حتقيق ًا املنوه عنه يف محضر استجوابه‪.‬‬\n              ‫‪ -2‬ما تضمنته اعترافه مبحضر سماع اقواله االولية املنوه عنها ‪.‬‬\n                                                    ‫‪ -3‬ما تضمنه محضر القبض املنوه ‪.‬‬\n                                                     ‫‪ -4‬ما تضمنه التقرير الكيميائي ‪.‬‬\n                                                  ‫‪ -5‬ما تضمنه محضر مطابقة املبلغ ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪-:‬‬\n      ‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة وفق ـ ًا للفقــرة (األولــى) مــن‬\n      ‫املــادة رقــم (‪ )38‬مــن نظــام مكافحــه املخــدرات املؤثــرات العقلية املشــار‬\n      ‫إليــه ‪ ،‬وإعمــال الفقــرة (األولــى )مــن املادة(‪)62‬مــن ذات النظــام بحقــه‬\n                                                                         ‫لقــاء مــا أســند إليــه‪.‬‬\n      ‫‪-2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبتــه وفقـ ًا للفقرة‬\n      ‫(األولــى) مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                                        ‫العقليــة‪.‬‬\n      ‫‪ -3‬مصــادرة الهاتــف اجلــوال العائــد للمذكــور املســتخدم يف اجلرميــة وهــو‬\n      ‫مــن نــوع نوكيــا يحمــل الرقــم املصنعــي (‪ )............‬وفقـ ًا للفقــرة (األولــى)‬\n                                               ‫مــن املــادة (‪ )53‬مــن النظــام املشــار إليــه ‪.‬‬\n      ‫‪ -4‬الغــاء الشــريحة ذات الرقــم (‪ ).....‬املســتخدمة يف عمليــة الترويــج‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حالــة صــدور احلكــم باملصــادرة‬\n      ‫وإبــاغ الشــركة مصــدرة الشــريحة بذلــك اســتنادا لتعميــم وزيــر‬\n                            ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n                      ‫‪ -5‬اجراء املقتضى الشرعي لقاء تعاطيه احلشيش املخدر ‪.‬‬\n\n\n‫‪197‬‬\n\f                 ‫‪ -6‬بعقوبة تعزيرية لقاء تستره على مصدر ما مت ترويجه ‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي‬\n‫العــام أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه صحيــح فأنــا‬\n‫ـخص‬‫اشــتريت القطعــة وتعاطيــت منهــا شــيئ ًا يســير ًا وبعتهــا علــى شـ ٍ‬\n‫آخــر هكــذا أجــاب ‪ ،‬وحيــث األمــر مــا ذكــر مــن الدعــوى واإلجابــة‬\n‫وحيــث اعتــرف املدعــى عليــه بدعــوى املدعــي العــام جــرى اإلطــاع‬\n‫علــى التقريــر الكيمــاوي الشــرعي املرفــق باملعاملــة حتــت لفــة رقــم‬\n‫(‪ )31‬وهــو صــادر مــن مركــز مراقبــة الســموم والكيميــاء الشــرعية‬\n‫رقــم (‪/44/2/6318‬ك) يف ‪1433/6/22‬ه ـ واملتضمــن إيجابيــة القطعــة‬\n                                                      ‫املضبوطــة ملــادة احلشــيش املخــدر‪.‬‬\n‫ـاء عليــه ثبــت لــدي إدانــة املدعــى عليــه ببيــع مــا وزنــه جرامني ونصف‬         ‫وبنـ ـ ً‬\n‫اجلــرام بقصــد الترويــج واالجتــار وحيازتــه لقطعــة حشــيش مخــدر مــن‬\n‫ذات النــوع غيــر معروفــة الــوزن بقصــد الترويــج والتعاطــي وتعاطيــه‬\n‫ا باملــادة رقــم‬\n                ‫للحشــيش املخــدر وحكمــت عليــه مبــا يلــي‪ -:‬أوالً‪ :‬عم ـ ً‬\n‫(‪ )38‬مــن نظــام مكافحــة املخــدرات املؤثــرات العقليــة واملــادة رقــم (‪)60‬‬\n‫مــن ذات النظــام والتــي أجــازت للقاضــي النــزول عــن احلــد األدنــى إذا‬\n‫أتــى بأســباب مقنعــة وحيــث ال توجــد ســابقة ترويــج علــى املدعــى عليــه‬\n‫والكميــة املروجــة قليلــة لــذا حكمــت بتعزيــر املدعــى عليــه بســجنه‬\n‫ســنة مــن تاريــخ إيقافــه وجلــده خمســن جلــدة دفع ـ ًة واحــد ًة وتغرميــه‬\n‫ألفــي ريــال تدفــع للخزينــة العامــة للدولــة‪ .‬ثانيـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت‬\n‫مبنعــه مــن الســفر إلــى خــارج اململكــة ملــدة ســنتني بعــد تنفيــذ العقوبــة‬\n‫ـاء علــى الفقــرة األولــى مــن املــادة رقــم (‪ )58‬مــن ذات النظــام‪.‬‬          ‫عليــه بنـ ً‬\n‫ثالثـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت بإلغــاء الشــريحة ذات الرقــم (‪ ).......‬املســتخدمة‬\n\n\n                                                                                                 ‫‪198‬‬\n\f      ‫يف عمليــة الترويــج وعــدم صرفهــا لنفــس املشــترك وإبــاغ الشــركة‬\n      ‫مصــدرة الشــريحة بذلــك‪ .‬رابع ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت مبصــادرة الهاتــف‬\n      ‫اجلــوال العائــد للمذكــور املســتخدم يف اجلرميــة وهــو مــن نــوع ‪ ......‬يحمــل‬\n      ‫الرقــم املصنعــي (‪ )............‬وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن‬\n      ‫ذات النظــام املشــار إليــه‪ .‬خامسـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬جلــده حــد اخلمــر ثمانــن‬\n      ‫جلــدة لقــاء تعاطيــه احلشــيش املخــدر‪ .‬سادس ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـ ـاً‪ :‬حكمــت بتغرميــه‬\n      ‫ألــف ريــال لقــاء تســتره علــى مصــدر مــا ضبــط‪ .‬وبــه حكم ــت ‪ ،‬وبعــرض‬\n      ‫احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه قناعتــه‬\n      ‫باحلكــم أمــا املدعــي العــام فطلــب االســتئناف مكتفيـ ًا بالئحــة اإلدعــاء‬\n      ‫عــن الالئحــة اإلعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/07/23‬هـ ــ‪..‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة اجلزائية‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33475473‬وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331360505‬وتاريــخ ‪ 1433/07/20‬ه ـ ففــي يــوم‬\n      ‫اإلثنــن املوافــق‪ 1433/11/29‬ه ـ افتتحــت اجللســة ثــم عــادت العاملــة مــن‬\n      ‫محكمــة االســتئناف برقــم ‪ 33454856‬يف ‪1433/11/15‬ه ـ واملتضمن‬\n      ‫التصديــق علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض رقــم‬\n      ‫‪ 332129313‬وتاريــخ ‪ 1433/12/1‬ه ـ ومشــفوعة املعاملــة اخلاصــة‬\n      ‫بدعــوى ‪ /‬املدعــي العــام ضــد ‪ ....... /‬واملنظــورة لــدى فضيلــة الشــيخ ‪/‬‬\n\n\n‫‪199‬‬\n\f‫‪ .........‬واملنتهيــة لديــه بالقــرار رقــم ‪ 33361642 /‬وتاريــخ ‪ 1433/7/3‬هـ‬\n‫وبعــد اإلطــاع علــى املعاملــة تبــن أنــه ســبق دراســة احلكــم واملصادقــة‬\n‫عليــه مــن قبــل الدائــرة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪200‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":193,"source_page_end":200,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d966c2c7377de9c2f94aac35631bf5f52e2f0c7651137dcdd72ab0e674b14fa3","normalized_text_hash":"d3d2ea6128a17e41fb555f5e82e2344ad4b07dd53cde5f82ad29fef9c1e8017b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p193-33361642"},{"id":"66ee9976-2502-5a17-b599-86d831d1b367","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -بيع احلبوب احملظورة -حيازة احلبوب احملظورة -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -تعزير بالسجن واجللد والغرامة -مصادرة مبلغ -مصادرة اجلوال املستخدم يف اجلرمية -إلغاء شريحة جوال مستخدمة يف اجلرمية .","document_number":"33464331","case_number":"33475860","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"مخدرات -بيع احلبوب احملظورة -حيازة احلبوب احملظورة -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -تعزير بالسجن واجللد والغرامة -مصادرة مبلغ -مصادرة اجلوال املستخدم يف اجلرمية -إلغاء شريحة جوال مستخدمة يف اجلرمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33464331 :‬تاريخه ‪1433/11/23 :‬هـ‬\n                         ‫رقم الدعوى ‪33475860 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3424078‬تاريخه‪1434/01/27 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬بيــع احلبــوب احملظــورة ‪ -‬حيــازة احلبــوب احملظــورة ‪ -‬ترويــج‬\n       ‫احلبــوب احملظــورة ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬تعزيــر بالســجن‬\n       ‫واجللــد والغرامــة ‪ -‬مصــادرة مبلــغ ‪ -‬مصــادرة اجلــوال املســتخدم يف‬\n                  ‫اجلرميــة ‪ -‬إلغــاء شــريحة جــوال مســتخدمة يف اجلرميــة ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                    ‫‪ -2‬املادة ‪ 53‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                    ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n       ‫دعــوى املدعــي العــام ضــد املدعــى عليــه ببيــع احلبــوب احملظــورة بقصــد‬\n       ‫الترويــج و التعاطــي و تعاطيــه لهــا و ترويجــه للحبــوب احملظــورة ‪ -‬وطلــب‬\n       ‫املدعــي العــام إثبــات مــا أســند إليــه و احلكــم عليــه بالســجن و اجللــد‬\n       ‫والغرامــة و مصــادرة املبلــغ املالــي املضبــوط معــه و الســيارة املســتخدمة‬\n       ‫يف اجلرميــة و مصــادرة هاتفــه اجلــوال املســتخدم يف اجلرميــة و إلغــاء اخلدمــة‬\n       ‫مــن شــريحته و عــدم صرفهــا مــرة أخــرى و منعــه مــن الســفر إلــى خــارج‬\n       ‫اململكــة‪ ،‬مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا أنــه يقــوم‬\n       ‫بترويــج احلبــوب احملظــورة فتــم االتصــال عليــه مــن أحــد املصــادر ومت‬\n\n‫‪201‬‬\n\f‫االتفــاق معــه علــى شــراء كميــة مــن احلبــوب و اســتعد بذلــك وحضــر‬\n‫املصــدر للمــكان املتفــق عليــه وحضــر املدعــى عليــه ومت االســتالم‬\n‫والتســليم بــن الطرفــن وصــدر التقريــر الكيميائــي بإيجابيــة العينــة‬\n‫املرســلة‪ ،‬إقــرار املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد‬\n‫والغرامــة و مصــادرة اجلــوال و إلغــاء الشــريحة اخلاصــة بــه املســتخدمني‬\n                 ‫يف اجلرميــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪ ....‬وتاريــخ ‪ .....‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ ....‬وتاريــخ ‪ ....‬ه ـ ففــي يــوم االثنــن املوافــق‪....‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا أدعــى املدعــي العــام ‪/‬‬\n‫‪...‬نيابــة عــن ‪.... /‬مبوجــب خطــاب التعميــد رقــك ‪ 24/6‬يف تاريــخ ‪......‬هـ ‪،‬‬\n‫‪ )33(............‬عامـ ًا ‪ ،‬ســعودي اجلنســية‪ ،‬مبوجــب ســجل مدنــي رقــم(‪)....‬‬\n‫املهنة‪/‬عســكري‪ ،‬موقــوف بســجون محافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقــم(‪ ).....‬وتاريــخ ‪.....‬ه ـ اســتنادا للقــرار الــوزاري رقــم (‪)1900‬‬\n‫بتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة‪ .‬بتاريــخ ‪1433/5/20‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل‬\n‫أفــراد مكافحــة املخــدرات مبحافظــة جــدة بنــاء علــى إخباريــة أحــد‬\n‫املصــادر الســرية املتضمنــة ترويــج املدعــى عليــه للحبــوب احملظــورة‬\n‫علــى ســيارة مــن نــوع فــورد حتمــل اللوحــة رقــم (‪ ).....‬فتــم االتصــال علــى‬\n                                                          ‫جوالــه رقــم(‪ُ ).......‬‬\n‫وطلــب منــه شــراء حبــوب مؤثــرة عقليـ ًا مببلــغ مائتــن‬\n\n                                                                                        ‫‪202‬‬\n\f      ‫ريــال فوافــق وباملوقــع احملــدد حضــر املدعــى عليــه أعــاه بســيارته املنــوه‬\n      ‫عنهــا ونــزل منهــا وســلم للمتعــاون (‪)7‬ســبع حبــات واســتلم املبلــغ فتــم‬\n      ‫القبــض عليــه وضبــط املبلــغ املرقــم بجيبــه وضبــط معــه اجلــوال الــذي مت‬\n      ‫التنســيق عليــه واحلامــل للرقــم املصنعــي (‪ )..........‬وبتفتيــش ســيارته مت‬\n      ‫ضبــط بهــا(‪ )12‬اثنتــا عشــرة حبــة فتــم االنتقــال إلــى منزلــه وبتفتيشــه‬\n      ‫عثــر بغرفــة النــوم علــى خزانــه حديديــه بداخلهــا(‪ )836‬ثمامنائــة وســتة‬\n      ‫وثالثون حبة و مبلغ مالي وقدره (‪ )12703.5‬اثنا عشــر الفا وســبعمائة‬\n      ‫وثالثــة ريــاالت ونصــف الريــال كمــا ضبــط مســدس ربــع محشــو بأربــع‬\n      ‫طلقــات حيــة وأفــاد بــأن الســيارة عائــده لــه ولكنــه ســجلها باســم زوجته‬\n      ‫‪.‬وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )../...‬لعام‪1433‬ه ـ احتــواء‬\n      ‫العينــات (أ) و(ب) و(ج) مــن احلبــوب املضبوطــة واملرســلة للتحليــل علــى‬\n      ‫مــادة االمفيتامــن املؤثــرة عقلي ـ ًا املدرجــة باجلــدول رقــم (‪)2‬فئــة(ب)‬\n      ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وباســتجواب‬\n      ‫املدعــى عليه‪/‬أقــر ببيــع(‪ )7‬ســبع حبــات مؤثــرة عقليـ ًا مقابــل مائتــا ريــال‬\n      ‫و أن (‪)12‬االثنتــا عشــرة حبــة مــن ذات النــوع وكذلــك(‪ )836‬الثمامنائــة‬\n      ‫وســتة وثالثــون حبــة مــن ذات النــوع املضبوطــة مبنزلــه عائــده لــه بقصــد‬\n      ‫التعاطــي كمــا أقــر بتعاطيــه مــن ذات احلبــوب وترويجــه وتعاطيــه لنوعها‬\n      ‫ســابق ًا كمــا أقــر بــأن الســيارة عائــده لــه وقــام بتســجيلها باســم زوجتــه‬\n      ‫ومت فصل أوراق مســتقلة للســاح واالوراق ‪ .‬وأســفر التحقيق عن توجيه‬\n      ‫االتهــام إلــى املدعــى عليــه ببيــع (‪)7‬حبــات حتتــوي على مــادة االمفيتامني‬\n      ‫املؤثــرة عقليــا بقصــد االجتــار وحيــازة (‪ )848‬ثمامنائــة وثمانيــة وأربعــون‬\n      ‫حبــة مــن ذات النــوع بقصــد الترويــج والتعاطــي‪ ،‬وتعاطيــه منهــا وترويجه‬\n      ‫وتعاطيــه لنوعــه ســابق ًا املجـ ّـرم اســتنادا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن‬\n\n\n‫‪203‬‬\n\f‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫وباالطــاع علــى ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة عليــه‪ .‬وحيــث‬\n‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا مــن‬\n‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n                                                        ‫م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫واملعاقــب عليهــا اســتناد ًا للمادتــن (‪ )41.38‬مــع مراعــاة مــا ورد باملــادة‬\n‫(‪ )62‬مــن ذات النظــام لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n                                                          ‫عليــه بالعقوبتــن التاليتــن ‪:‬‬\n‫‪1‬ـ بالســجن واجللــد والغرامــة لقــاء مــا اســند إليــه اســتناد ًا للفقــرة (‪ )1‬مــع‬\n‫تشــديد العقوبــة عليــه وفقـ ًا للحالــة(ج) مــن الفقــرة ‪2‬مــن املــادة (‪ )38‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وتعميــم وزيــر الداخليــة‬\n    ‫رقــم ‪2/8346/4/5/1‬ش وتاريــخ ‪1427/2/8‬ه ـ لقــاء ترويــج احلبــوب‪.‬‬\n‫‪2‬ـ مصــادرة املبلــغ املالــي املضبــوط معــه وقــدره (‪ )12703‬اثنــا عشــر‬\n‫ألفـ ًا وســبعمائة وثالثــة ريــاالت ونصــف الريــال والســيارة املســتخدمة يف‬\n‫ارتــكاب اجلرميــة مــن نــوع فــورد فضيــة اللــون رقــم لوحتهــا (‪ ).....‬وهاتفــه‬\n‫اجلــوال املســتخدم يف ارتــكاب اجلرميــة ذي الرقــم املصنعــي (‪)............‬‬\n‫اســتنادا للفقــرة (‪ )2.1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه وإلغــاء اخلدمــة عــن شــريحة اجلــوال وعــدم صرفهــا ملــن أســاء‬\n‫اســتخدامها اســتناد ًا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n                                      ‫رقــم (‪ )9798‬وتاريــخ ‪ 9‬ــ‪1428/2/10‬ه ـ ‪.‬‬\n‫‪3‬ـ منعــه مــن الســفر الــى خــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتــه‬\n‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n\n\n                                                                                            ‫‪204‬‬\n\f      ‫واملؤثــرات العقليــة هــذه دعــواي واســاله اجلــواب وبســؤال املدعــى‬\n      ‫عليــه عــن الدعــوى قــال صحيــح أننــي قمــت ببيــع ‪ 7‬حبــات مــن حبــوب‬\n      ‫اإلمفتامــن احملظــورة وحــزت ‪ 848‬ثمامنائــة وثمانيــة وأربعــون حبــة مــن‬\n      ‫ذات النــوع بقصــد الترويــج والتعاطــي وتعاطيــه منهــا وانوعهــا يف الســابق‬\n      ‫وأن املبلــغ املذكــور البالــغ قــدره ‪ 12703‬ريــال أثنــا عشــر ألف وســبعمائة‬\n      ‫وثالثــة ريــال هــو لــي اكتســبته مــن الترويــج وأن الســيارة الفــورد موديــل‬\n      ‫‪99‬م والتــي ضبطــت فيهــا احلبــوب املخــدرة والتــي كنــت أقودهــا هــي‬\n      ‫ليســت لــي وإمنــا لزوجتــي ‪...............‬وأن الهاتــف اجلــوال مــع شــريحته‬\n      ‫املذكــور يعــود لــي هــذه هــي احلقيقــة وبعــرض ذلــك علــى املدعــي العــام‬\n      ‫بإمــكان الرجــوع إلــى اســتمارة الســيارة املذكــورة يف الدعــوى ملعرفــة‬\n      ‫مــن تعــود الســيارة إليــه وأطلــب إمهالــي لذلــك حــرر يف ‪......‬ه ـ ‪ .‬ويف يــوم‬\n      ‫األربعــاء املوافــق ‪.....‬ه ـ حضــر املدعــي العــام وحضــر حلضــوره الســجني‬\n      ‫املذكــور وقــد جــرى االطــاع علــى اســتمارة الســيارة املشــار إليهمــا‬\n      ‫أعــاه واملطلــوب مصادرتهــا يف الدعــوى فوجــدت أنهــا حتتــوي الرقــم‬\n      ‫املشــار إليــه أعــاه وهــي باســم املــرأة ‪ ................ /‬وأرفــق صــورة مــن‬\n      ‫االســتمارة املذكــورة يف املعاملــة وبعــرض ذلــك علــى املدعــي العــام‬\n      ‫قــال أطلــب إجــراء الوجــه الشــرعي وبالرجــوع إلــى أوراق املعاملــة وجــد‬\n      ‫التقريــر الكيميائــي الشــرعي املشــار إلــى رقمــه ومضمونــة أعــاه ولــم‬\n      ‫يعثــر لــه علــى ســوابق مســجلة وعليــه وحيــث احلــال مــا ذكــر مــن دعــوى‬\n      ‫املدعــي العــام ضــد املذكــور وبطلــب مجازاتــه وبعــد التأمــل واالطــاع‬\n      ‫ولكــون االعتــراف ســيد األدلــة فقــد ثبــت لــدي إدانــة املدعــى عليــه فيمــا‬\n      ‫نســب إليــه مــن الدعــوى أعــاه وهــي بيــع ســبع حبــات مــن احلبــوب املؤثــرة‬\n      ‫عقلي ـ ًا بقصــد اإلجتــار وحيــازة ثمامنائــة وثمانيــة وأربعــن حبــة مــن ذات‬\n\n\n‫‪205‬‬\n\f‫النــوع بقصــد الترويــج والتعاطــي وتعاطيــه منهــا وترويجــه وتعاطيه لنوعه‬\n‫ســابق ًا واســتخدامه للجــوال مــع شــريحته وان املبلــغ اعــاه مكتســب‬\n‫مــن الترويــج يف اجلرميــة وحكمــت أو ًال ‪ /‬تعزيــر املدعــى عليــه لبيعــه‬\n‫احلبــوب املذكــورة وحيازتــه لهــا بقصــد التعاطــي والترويــج بالســجن‬\n‫خمــس ســنوات مــن تاريــخ دخولــه الســجن وجلــده خمســمائة جلــدة علــى‬\n‫عشــر دفعــات كل دفعــة خمســون جلــده بــن الدفعــة والتــي تليهــا خمســة‬\n‫عشــر يوم ـ ًا وغرامــة ماليــة قدرهــا ألــف ريــال إســتناد ًا للمــادة (‪ )38‬مــن‬\n‫نظــام املخــدرات وهــذه العقوبــة شــاملة التعاطــي للحبــوب لنوعهــا مــن‬\n‫الســابق ‪ .‬ثاني ـ ًا ‪ /‬مصــادرة املبلــغ الشــارة إليــه أعــاه ومصــادرة اجلــوال‬\n‫مــع إلغــاء شــريحته ومنــع صرفهــا لــه مــرة أخــرى إســتناد ًا للمــادة (‪)53‬‬\n‫مــن ذات النظــام ‪ .‬ثالثـ ًا ‪ /‬منــع املذكــور مــن الســفر خــارج اململكــة بعــد‬\n‫إنتهــاء محكوميتــه ملــدة خمــس ســنوات إســتناد ًا للمــادة (‪ )56‬مــن ذات‬\n‫النظــام ‪ .‬رابع ـ ًا ‪ /‬صرفــت النظــر عــن طلــب املدعــي مصــادرة الســيارة‬\n‫املذكــورة واملســتخدمة يف اجلرميــة كونهــا ليســت للمذكــور املدعــى‬\n‫عليــه وبعرضــه عليهمــا قــرر املدعــى عليــه قناعتــه بذلــك وأبــدى املدعــي‬\n‫العــام إعتراضــه بالئحــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/01‬ه ـ ‪ .‬احلمــد‬\n‫هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى منــا‬\n‫نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بجــدة املســاعد رقــم وتاريــخ ‪........‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة الشــيخ‪ ......./‬القاضــي باحملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة رقــم ‪ ........‬وتاريــخ ‪.......‬ه ـ احملكــوم فيــه مبــا‬\n\n\n                                                                                      ‫‪206‬‬\n\f      ‫دون بباطــن القــرار املتضمــن دعــوى املدعــى العــام ضــد‪ ......./‬ســعودي‬\n      ‫اجلنســية املتهــم يف مخــدرات وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل‬\n                            ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪،،،،‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":201,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ecf8874e6e2ef18a8d51c0abd280f88ef6f32baec493902b21ff5cb9d4cb9e6","normalized_text_hash":"e0c4368ee336b9458d63a35b545e3dac1ffdfeb57d21d74059bb65deb90792c5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p201-33464331"}]$archive_payload$::jsonb) AS x LIMIT 25
